-- ============================================================
-- TABELA: catalogo.composicoes_grupos
-- Nível 1 da hierarquia de classificação.
--   CDHU: código numérico 'XX' (ex: '01', '02')
--   SINAPI: não usa — subgrupos têm sub_grp_id = NULL
--
-- DECISÃO (MVP): grupos/subgrupos são TAXONOMIA AUXILIAR de navegação,
--   SEM versionamento por edição. Se houver drift relevante de taxonomia
--   entre edições, cria-se versionamento próprio depois — não bloquear
--   importação por isso agora.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_grupos (
    grp_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grp_fte_id         INTEGER NOT NULL,
    grp_codigo         TEXT    NOT NULL,
    grp_descricao      TEXT    NOT NULL,
    grp_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    grp_atualizado_em  TIMESTAMPTZ,
    grp_criado_por     TEXT,
    grp_atualizado_por TEXT,

    CONSTRAINT fk_composicoes_grupos_fte
        FOREIGN KEY (grp_fte_id)
        REFERENCES catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_composicoes_grupos_fte_codigo
        UNIQUE (grp_fte_id, grp_codigo),

    CONSTRAINT ck_composicoes_grupos_codigo_vazio
        CHECK (btrim(grp_codigo) <> '')
);

CREATE INDEX ix_composicoes_grupos_fte
    ON catalogo.composicoes_grupos (grp_fte_id);

