-- ============================================================
-- TABELA: catalogo.insumos
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md
--   (classificação/origem/NC: CDHU e SINAPI nos contratos de import)
-- Identidade dos insumos — o que o insumo É, sem preço.
--
-- ins_ti_id: FK para insumos_tipo. NUNCA NULL — todo insumo é
--   classificado. SINAPI traz classificação nativa (FONTE); CDHU é
--   classificada por descrição+unidade pela regra; órfão do Analítico vai
--   por fuzzy; sem confiança cai em 'NC' (Não Classificado). Nunca NULL.
-- ins_ti_origem: autoridade da classificação — 'FONTE' (classif nativa da
--   fonte), 'REGRA' (parser/fuzzy/léxico) ou 'MANUAL' (curadoria humana).
--   PREVALÊNCIA no reimport: FONTE > MANUAL > REGRA. FONTE prevalece até
--   sobre MANUAL; MANUAL só prevalece quando a fonte NÃO classifica; REGRA/NC
--   são reaplicados a cada reimport. Default 'REGRA'. A prevalência é
--   garantida pelo PARSER (ON CONFLICT), não pelo banco.
-- ins_ativo: false quando ausente na edição mais recente da
--   fonte. Não exclui o registro — preserva histórico.
-- ins_external_path: FONTE ÚNICA (não cache) da ficha técnica do insumo
--   (§11.1/§11.10). Guarda a VIGÊNCIA POR VERSÃO na identidade:
--     { "ficha_tecnica": { "fonte":..., "versoes":[ {"desde_edi":E, "path":...} ] } }
--   Última versão = vigente ({cod}.html); anteriores → _old/{cod}_<sha>.html.
--   Resolução as-of edição = maior desde_edi com edi_mes_ref ≤ o da edição-alvo.
--   NÃO armazena conteúdo — só paths (url derivada = /doc-file/ + path).
--   ⚠️ REVISTO 2026-07-13: a ficha NÃO passa mais por catalogo.documentos.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos (
    ins_id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ins_fte_id         INTEGER NOT NULL,
    ins_ti_id          INTEGER NOT NULL,
    ins_ti_origem      TEXT    NOT NULL DEFAULT 'REGRA',   -- 'FONTE' | 'REGRA' | 'MANUAL'
    ins_codigo         TEXT    NOT NULL,
    ins_descricao      TEXT    NOT NULL,
    ins_unidade        TEXT    NOT NULL,
    ins_ativo          BOOLEAN NOT NULL DEFAULT TRUE,
    ins_external_path  JSONB,
    ins_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ins_atualizado_em  TIMESTAMPTZ,
    ins_criado_por     TEXT,
    ins_atualizado_por TEXT,

    CONSTRAINT fk_insumos_fte
        FOREIGN KEY (ins_fte_id)
        REFERENCES catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_ti
        FOREIGN KEY (ins_ti_id)
        REFERENCES catalogo.insumos_tipo (ti_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_insumos_fte_codigo
        UNIQUE (ins_fte_id, ins_codigo),

    -- Redundante como unicidade (ins_id já é PK), e é de propósito: existe só para ser ALVO da
    -- FK composta de equivalencias_ins/_mo, que é o que impede aquelas tabelas de guardarem uma
    -- fonte que não é a do item. Sem este UNIQUE declarado, o Postgres recusa a FK.
    CONSTRAINT uq_insumos_id_fte
        UNIQUE (ins_id, ins_fte_id),

    CONSTRAINT ck_insumos_ti_origem
        CHECK (ins_ti_origem IN ('FONTE', 'REGRA', 'MANUAL')),

    CONSTRAINT ck_insumos_codigo_vazio
        CHECK (btrim(ins_codigo) <> ''),

    CONSTRAINT ck_insumos_unidade_vazia
        CHECK (btrim(ins_unidade) <> ''),

    CONSTRAINT ck_insumos_external_path_obj
        CHECK (ins_external_path IS NULL
            OR jsonb_typeof(ins_external_path) = 'object')
);

CREATE INDEX ix_insumos_fte_ativo
    ON catalogo.insumos (ins_fte_id, ins_ativo, ins_codigo);

CREATE INDEX ix_insumos_ti
    ON catalogo.insumos (ins_ti_id);

-- Listagem ordenada por descrição (sort default da tela): sem isto o Postgres faz
-- Seq Scan + Sort dos ~10k insumos a cada página. Com o índice a página sai ordenada
-- direto (LIMIT 50). Em prod aplicar com CREATE INDEX CONCURRENTLY (sem travar).
CREATE INDEX ix_insumos_ativo_descricao
    ON catalogo.insumos (ins_ativo, ins_descricao);


-- ============================================================
-- TABELA: catalogo.insumos_preco
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md  (§3 Preço)
-- Preços dos insumos por edição / UF / modalidade.
-- Cada linha é imutável. Re-import da mesma
-- (insumo, edição, uf, modalidade) é upsert idempotente.
--
-- pri_uf:         UF da coleta ('SP', 'RJ', ...)
-- pri_modalidade: DOUTRINA "PELADO + LS" — insumos_preco é SE-ONLY.
--   O parser grava SEMPRE 'SE' (preço pelado, sem encargos) p/ TODO insumo —
--   MO e não-MO. SD/CD NÃO são gravados como preço de insumo: são DERIVADOS no
--   cálculo da CPU via trunc(pelado*(1+LS/100),2), com LS de edicoes_leis_sociais
--   (BUSINESS_RULES §3.1–3.3). Razão: o "com encargos" publicado pela fonte É
--   essa fórmula (provado ao centavo) → derivar não perde nada e reduz dados.
--   A coluna e o CHECK (SD/CD/SE) PERMANECEM: CD/SD seguem válidos no cadastro
--   p/ visualização/processamento dinâmico, mas não como linha de preço de insumo.
-- pri_origem:     'C' = coletado | 'CR' = coef. representativo | 'CT' = cotação
--   ('CT' = preço de MERCADO via cotação de fornecedores; o lastro/detalhe das
--    cotações e a certidão de pesquisa de preço vivem em catalogo.insumos_cotacoes;
--    a mediana de lá alimenta pri_valor desta linha. Ver BUSINESS_RULES §3.5.)
-- pri_valor:      valor publicado EXATAMENTE (inclui 0); NULL quando a fonte
--   não publicou preço — o MOTIVO fica em pri_situacao, nunca solto.
-- pri_situacao:   R3 (2026-07-14) — CHECK-text 'COM PREÇO' | 'SEM PREÇO' (fim do lookup situacoes).
--   NULL tolerado.
--   Contrato do parser: TODA UF da edição tem linha; AUSÊNCIA de linha =
--   falha/não-processado, NUNCA "sem preço". Coerência valor×situação é
--   responsabilidade do parser/importador — NÃO há trigger.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_preco (
    pri_id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pri_ins_id         BIGINT       NOT NULL,
    pri_edi_id         INTEGER       NOT NULL,
    pri_uf             CHAR(2)       NOT NULL DEFAULT 'SP',
    pri_modalidade     CHAR(2)       NOT NULL DEFAULT 'SE',
    pri_valor          NUMERIC(14,4),
    pri_situacao       TEXT,          -- R3: 'COM PREÇO' | 'SEM PREÇO' (CHECK abaixo); NULL tolerado
    pri_origem         CHAR(2),
    pri_criado_em      TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pri_atualizado_em  TIMESTAMPTZ,
    pri_criado_por     TEXT,
    pri_atualizado_por TEXT,

    CONSTRAINT fk_insumos_preco_ins
        FOREIGN KEY (pri_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_preco_edi
        FOREIGN KEY (pri_edi_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_insumos_preco_ins_edi_uf_mod
        UNIQUE (pri_ins_id, pri_edi_id, pri_uf, pri_modalidade),

    CONSTRAINT ck_insumos_preco_situacao   -- R3: situação de preço como CHECK-text (fim da FK p/ situacoes)
        CHECK (pri_situacao IS NULL OR pri_situacao IN ('COM PREÇO', 'SEM PREÇO')),

    CONSTRAINT ck_insumos_preco_modalidade
        CHECK (pri_modalidade IN ('SD', 'CD', 'SE')),

    CONSTRAINT ck_insumos_preco_origem
        CHECK (pri_origem IS NULL OR pri_origem IN ('C', 'CR', 'CT'))
);

-- (ix_insumos_preco_ins_edi removido: era DUPLICATA EXATA da constraint UNIQUE
--  uq_insumos_preco_ins_edi_uf_mod — mesmas colunas/ordem; o unique cobre 100% as leituras.)

CREATE INDEX ix_insumos_preco_edi
    ON catalogo.insumos_preco (pri_edi_id);

CREATE INDEX ix_insumos_preco_uf
    ON catalogo.insumos_preco (pri_uf, pri_edi_id);


-- ============================================================
-- TABELA: catalogo.insumos_cotacoes   (prefixo ic_)   — decisão Renan 2026-06-07
-- LASTRO de preço de MERCADO via cotação (insumos próprios / sem preço de fonte).
-- Fluxo: junta cotações de fornecedores aqui → mediana → vira o preço em
--   insumos_preco (pri_valor = ic_preco_mediano, pri_origem='CT'). A VERDADE do
--   preço continua sendo insumos_preco (§3.4); esta tabela é o detalhe/auditoria.
-- Preço de insumo é SE-only (§3.1) → a cotação produz a linha SE da UF; por isso
--   ic_uf (sem modalidade). Mediana (não média) = robusta a outlier.
-- Docs (proposta por fornecedor; certidão de pesquisa de preço) são justificativa
--   do usuário → R2 PRIVADO (não é o registro público de documentos da fonte).
-- Ver BUSINESS_RULES §3.5.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_cotacoes (
    ic_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ic_ins_id          BIGINT       NOT NULL,
    ic_edi_id          INTEGER       NOT NULL,
    ic_uf              CHAR(2)       NOT NULL DEFAULT 'SP',
    ic_preco_mediano   NUMERIC(14,4),   -- mediana dos 'valor' das cotações (alimenta insumos_preco SE/CT)
    -- ic_certidao_path: certidão de pesquisa de preço (1 por cotação) — {path,url,...} no R2 privado.
    ic_certidao_path   JSONB,
    -- ic_cotacoes: ARRAY de cotações de fornecedor. Cada item:
    --   { fornecedor: { nome, razao_social, cnpj, nome_fantasia, telefone, contato },
    --     data_cotacao, ambiente (online|link|presencial), valor (14,2),
    --     proposta_path: {path,url,...}  ← arquivo da proposta do fornecedor (R2 privado) }
    ic_cotacoes        JSONB,
    ic_criado_em       TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ic_atualizado_em   TIMESTAMPTZ,
    ic_criado_por      TEXT,
    ic_atualizado_por  TEXT,

    CONSTRAINT fk_insumos_cotacoes_ins
        FOREIGN KEY (ic_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_insumos_cotacoes_edi
        FOREIGN KEY (ic_edi_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_insumos_cotacoes
        UNIQUE (ic_ins_id, ic_edi_id, ic_uf)
);

CREATE INDEX ix_insumos_cotacoes_ins_edi
    ON catalogo.insumos_cotacoes (ic_ins_id, ic_edi_id);


-- ============================================================
-- TABELA: catalogo.insumos_familia   (prefixo fam_)
-- Família homogênea SINAPI (arquivo SINAPI_familias_e_coeficientes), POR EDIÇÃO.
-- Representativo (origem coleta) × representados (preço derivado por coeficiente
-- de UF). Guardado como dado-fonte (igual preço/LS): consulta rara, JSONB de
-- auditoria + carga no import. Uso no cálculo: insumo representado SEM preço SE
-- numa UF (%AS) → preço atribuído = preço_SP × (coef_UF / coef_SP)  (≡
-- representativo_SP × coef_UF). Para MAT/EQUIP/SERV o coef é igual entre UFs
-- (ratio 1 → SP plano); o efeito real recai sobre MO. Ver BUSINESS_RULES §3.2.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.insumos_familia (
    fam_edi_id      INTEGER     NOT NULL,
    fam_ins_id      BIGINT     NOT NULL,
    fam_familia     TEXT,                       -- código da família (ex.: '4093')
    fam_categoria   TEXT,                       -- REPRESENTATIVO | REPRESENTADO
    fam_coefs       JSONB       NOT NULL,        -- {"AC": .., "MA": 190.25, .., "SP": 183.25}
    fam_criado_em   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fam_criado_por  TEXT,

    PRIMARY KEY (fam_edi_id, fam_ins_id),

    CONSTRAINT fk_fam_edi
        FOREIGN KEY (fam_edi_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT fk_fam_ins
        FOREIGN KEY (fam_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT ck_fam_categoria
        CHECK (fam_categoria IN ('REPRESENTATIVO', 'REPRESENTADO'))
);

CREATE INDEX ix_insumos_familia_edi
    ON catalogo.insumos_familia (fam_edi_id);

CREATE INDEX ix_insumos_familia_familia
    ON catalogo.insumos_familia (fam_edi_id, fam_familia);


-- ============================================================
-- TABELA: catalogo.composicoes
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md  (§4 Composição)
-- Cabeçalho das CPUs — FASE 2: IDENTIDADE VIGENTE (1 linha por (cmp_fte_id, cmp_codigo)).
-- Campos = estado vigente (última edição). A série por edição vive em composicoes_custo
-- (cc_edi_id) e a evolução cadastral/estrutural em composicoes_historico (snapshot na mudança).
--
-- cmp_situacao: situação OFICIAL publicada/consolidada pela fonte —
--               'COM CUSTO' | 'SEM CUSTO' | 'SUSPENSO' | 'EM ESTUDO'.
-- cmp_sub_id:   FK para composicoes_subgrupos (nullable — composições AXYS
--               são livres de subgrupo)
-- cmp_motivo_sem_custo: explicação objetiva do SEM CUSTO (ex.:
--   "Item 45087 sem preço na fonte SINAPI"). NULL quando não aplicável.
-- cmp_tem_item_sem_preco: ao menos um item direto (insumo) sem preço.
-- cmp_tem_item_sem_custo: ao menos uma subcomposição direta sem custo.
--   Estes flags tornam o SEM CUSTO AUDITÁVEL sem recalcular custo parcial.
-- Histórico cadastral/estrutural fica na tabela LATERAL
--   catalogo.composicoes_historico — NÃO em coluna JSON nesta tabela.
-- cmp_external_path: FONTE ÚNICA (não cache) do doc PRÓPRIO da composição —
--   caderno_cpu e CTC (publicacao.md §11.1/§11.10). Guarda a
--   VIGÊNCIA POR VERSÃO na identidade:
--     { <tipo>: { "fonte":..., "versoes":[ {"desde_edi":E, "path":...} ] } }
--   Última versão = vigente ({cod}.html); anteriores apontam pro _old/{cod}_<sha>.html.
--   Resolução as-of edição = maior desde_edi com edi_mes_ref ≤ o da edição-alvo.
--   NÃO armazena conteúdo (HTML/PDF) — só paths (url derivada = /doc-file/ + path).
--   ⚠️ REVISTO 2026-07-13: ficha/caderno_cpu/CTC NÃO passam por catalogo.documentos
--   (ficha idem, em ins_external_path). Auditoria formal continua no schema audit.
-- ============================================================
-- FASE 2 — COMPOSIÇÕES CONTÍNUAS (APLICADA). As tabelas abaixo SÃO o modelo Fase 2:
--   • composicoes = IDENTIDADE vigente (1 linha por (fte,código); SEM cmp_edi_id;
--     UNIQUE (cmp_fte_id, cmp_codigo)); descrição/unidade/situação/flags/external_path = vigente.
--   • composicoes_itens = RECEITA VIGENTE (ci_cmp_id → identidade).
--   • composicoes_custo = SÉRIE DENSA por cc_edi_id (simétrico a insumos_preco).
--   • composicoes_historico = SNAPSHOT-NA-MUDANÇA (retroação; custo nunca entra).
--   Regra canônica: listagem.md §9.6.
--   Nota: insumos_historico usa faixa (inicio/fim) e composicoes_historico usa evento
--   (origem/nova) — convenções diferentes p/ o mesmo papel; divergência ACEITA (ambas funcionam,
--   as-of resolve nos dois). Alinhar é opcional, sem gatilho.
CREATE TABLE IF NOT EXISTS catalogo.composicoes (
    cmp_id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cmp_fte_id          INTEGER NOT NULL,
    -- FASE 2: identidade VIGENTE (1 linha por (fonte, código)). SEM cmp_edi_id — a série por
    -- edição vive em composicoes_custo (cc_edi_id) e a evolução em composicoes_historico (snapshot).
    cmp_sub_id          INTEGER,
    cmp_grupo_id        INTEGER,                       -- FK composicoes_grupos; NULL p/ SINAPI (sem grupo), preenchido no import CDHU
    cmp_codigo          TEXT    NOT NULL,
    cmp_descricao       TEXT    NOT NULL,
    cmp_unidade         TEXT    NOT NULL,
    cmp_situacao        TEXT,
    cmp_motivo_sem_custo   TEXT,
    cmp_tem_item_sem_preco BOOLEAN NOT NULL DEFAULT FALSE,
    cmp_tem_item_sem_custo BOOLEAN NOT NULL DEFAULT FALSE,
    cmp_ativa           BOOLEAN NOT NULL DEFAULT TRUE,
    cmp_primeira_pub    DATE,
    cmp_ultima_pub      DATE,
    cmp_ultima_alteracao DATE,
    cmp_external_path   JSONB,
    cmp_descritivo      JSONB,                            -- CTC VERSIONADO (fonte de verdade do texto; a tela lê 100% do banco):
                                                          -- {modo, versoes:[{desde_edi, req_hash, status, medicao, remunera, origem}]}.
                                                          -- versoes[-1]=ATUAL; render por-edição = maior desde_edi<=edi. Mudança de fonte ANEXA versão
                                                          -- (preserva texto antigo no banco). _old .md = só auditoria/edição, render NÃO depende dele (§11.11).
                                                          -- ⚠️ REVISTO 2026-07-13: o prompt/MD do CTC vivem SÓ no storage
                                                          -- (ctc/prompt|doc/{cod}.md); o 'request' NUNCA aqui (era ~56MB
                                                          -- duplicado). req_hash versiona (delta:hash). NULL = em elaboração.
    cmp_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cmp_atualizado_em   TIMESTAMPTZ,
    cmp_criado_por      TEXT,
    cmp_atualizado_por  TEXT,

    CONSTRAINT fk_composicoes_fte
        FOREIGN KEY (cmp_fte_id)
        REFERENCES catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_sub
        FOREIGN KEY (cmp_sub_id)
        REFERENCES catalogo.composicoes_subgrupos (sub_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_composicoes_grp
        FOREIGN KEY (cmp_grupo_id)
        REFERENCES catalogo.composicoes_grupos (grp_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_composicoes_fte_codigo
        UNIQUE (cmp_fte_id, cmp_codigo),

    -- Alvo da FK composta de equivalencias_cpu/_mo (ver uq_insumos_id_fte).
    CONSTRAINT uq_composicoes_id_fte
        UNIQUE (cmp_id, cmp_fte_id),

    CONSTRAINT ck_composicoes_codigo_vazio
        CHECK (btrim(cmp_codigo) <> ''),

    CONSTRAINT ck_composicoes_unidade_vazia
        CHECK (btrim(cmp_unidade) <> ''),

    CONSTRAINT ck_composicoes_situacao
        CHECK (cmp_situacao IS NULL OR cmp_situacao IN (
            'COM CUSTO', 'SEM CUSTO', 'SUSPENSO', 'EM ESTUDO'
        )),

    CONSTRAINT ck_composicoes_external_path_obj
        CHECK (cmp_external_path IS NULL
            OR jsonb_typeof(cmp_external_path) = 'object')
);

CREATE INDEX ix_composicoes_fte_codigo
    ON catalogo.composicoes (cmp_fte_id, cmp_codigo);

CREATE INDEX ix_composicoes_sub
    ON catalogo.composicoes (cmp_sub_id)
    WHERE cmp_sub_id IS NOT NULL;

CREATE INDEX ix_composicoes_grp
    ON catalogo.composicoes (cmp_grupo_id)
    WHERE cmp_grupo_id IS NOT NULL;

CREATE INDEX ix_composicoes_situacao
    ON catalogo.composicoes (cmp_situacao)
    WHERE cmp_situacao IS NOT NULL;

-- Listagem ordenada por descrição (sort default da tela; filtra cmp_ativa=true): sem isto,
-- Seq Scan + Sort de TODAS as composições (muito mais que insumos). Escala. Em prod aplicar
-- com CREATE INDEX CONCURRENTLY (sem travar).
CREATE INDEX ix_composicoes_ativa_descricao
    ON catalogo.composicoes (cmp_ativa, cmp_descricao);


-- ============================================================
-- TABELA: catalogo.composicoes_itens
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md  (§4-§5)
-- Itens = RECEITA VIGENTE da composição (Fase 2): ci_cmp_id → IDENTIDADE (SEM edição).
-- Filho = insumo ('INSUMO') XOR sub-composição ('COMPOSICAO'). Ciclos proibidos (camada de app).
--
-- ci_situacao: situação do item na fonte — 'COM PREÇO' | 'SEM PREÇO'
--   | 'COM CUSTO' | 'SEM CUSTO' | 'SUSPENSO' | 'EM ESTUDO'.
-- R1 APLICADO (2026-07-14): removidas ci_*_fonte_original — o filho é resolvido pela IDENTIDADE
--   (associação determinística por código; auditoria = original em catalogo.documentos por edição).
--   Todos os parsers (SINAPI/CDHU/FDE) migrados; nenhum escritor/leitor referencia mais essas colunas.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_itens (
    ci_id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ci_cmp_id          BIGINT       NOT NULL,
    ci_tipo_filho      TEXT          NOT NULL,
    ci_ins_id          BIGINT,
    ci_cmp_filho_id    BIGINT,
    ci_coef            NUMERIC(14,10) NOT NULL,
    ci_situacao        TEXT,
    ci_ordem           SMALLINT      NOT NULL DEFAULT 0,
    ci_criado_em       TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ci_atualizado_em   TIMESTAMPTZ,
    ci_criado_por      TEXT,
    ci_atualizado_por  TEXT,

    CONSTRAINT fk_ci_cmp
        FOREIGN KEY (ci_cmp_id)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT fk_ci_ins
        FOREIGN KEY (ci_ins_id)
        REFERENCES catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT fk_ci_cmp_filho
        FOREIGN KEY (ci_cmp_filho_id)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT ck_ci_tipo_filho
        CHECK (ci_tipo_filho IN ('INSUMO', 'COMPOSICAO')),

    CONSTRAINT ck_ci_filho_xor
        CHECK (
            (ci_tipo_filho = 'INSUMO'
                AND ci_ins_id IS NOT NULL
                AND ci_cmp_filho_id IS NULL)
            OR
            (ci_tipo_filho = 'COMPOSICAO'
                AND ci_cmp_filho_id IS NOT NULL
                AND ci_ins_id IS NULL)
        ),

    -- Fidelidade à fonte: a CPU é gravada EXATAMENTE como a fonte apresenta.
    -- A SINAPI publica itens com coeficiente 0 (item presente na composição, com
    -- quantidade não atribuída / composição incompleta ou sem custo). Não cabe à
    -- app julgar o dado, só repeti-lo — por isso 0 é válido (≥ 0). Negativo segue
    -- barrado (não existe em SINAPI; seria lixo). Insumo SEM PREÇO com coef 0 ainda
    -- propaga sem-custo na árvore (a presença basta, não o coeficiente).
    CONSTRAINT ck_ci_coef_nao_negativo
        CHECK (ci_coef >= 0),

    CONSTRAINT ck_ci_situacao
        CHECK (
            ci_situacao IS NULL
            OR (ci_tipo_filho = 'INSUMO'
                AND ci_situacao IN ('COM PREÇO', 'SEM PREÇO'))
            OR (ci_tipo_filho = 'COMPOSICAO'
                AND ci_situacao IN ('COM CUSTO', 'SEM CUSTO', 'SUSPENSO', 'EM ESTUDO'))
        ),

    CONSTRAINT uq_ci_cmp_ins
        UNIQUE (ci_cmp_id, ci_ins_id),

    CONSTRAINT uq_ci_cmp_filho
        UNIQUE (ci_cmp_id, ci_cmp_filho_id)
);

CREATE INDEX ix_ci_cmp
    ON catalogo.composicoes_itens (ci_cmp_id, ci_ordem);

CREATE INDEX ix_ci_ins
    ON catalogo.composicoes_itens (ci_ins_id)
    WHERE ci_ins_id IS NOT NULL;

CREATE INDEX ix_ci_cmp_filho
    ON catalogo.composicoes_itens (ci_cmp_filho_id)
    WHERE ci_cmp_filho_id IS NOT NULL;


-- ============================================================
-- TABELA: catalogo.composicoes_custo
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/imports/sinapi.md  (§4-§5, %AS)
-- Custos pré-calculados por composição / edição / UF / modalidade.
-- SINAPI fornece os valores direto nas abas CSD/CCD.
-- Imutável — mesmo regime de insumos_preco.
--
-- Guarda DOIS valores lado a lado — dado contra dado, auditável:
-- cc_custo_fonte: valor OFICIAL publicado/importado da fonte-base.
--   NUNCA é sobrescrito/descartado. = NULL quando não há custo válido;
--   = 0 SÓ quando a fonte publica zero numérico. A situação oficial
--   (SEM CUSTO etc.) fica em composicoes.cmp_situacao.
-- cc_custo_calculado: valor recalculado pela aplicação a partir dos
--   itens e preços disponíveis. NÃO substitui automaticamente o oficial.
-- cc_diferenca_valor: cc_custo_calculado - cc_custo_fonte (pode ser < 0).
-- cc_diferenca_percentual: cc_diferenca_valor / cc_custo_fonte quando
--   cc_custo_fonte > 0; NULL quando fonte é NULL/0 (não forçar cálculo).
-- cc_status_conferencia: classificação fonte × cálculo (ver CHECK).
-- cc_observacao_conferencia: nota livre da conferência.
-- A UI pode exibir ambos e destacar a diferença; NÃO mascarar divergência
--   nem gravar custo parcial como oficial. (Motor/trigger: não aqui.)
--
-- FASE 2: a EDIÇÃO é cc_edi_id (série densa própria, simétrico a insumos_preco);
--   cc_cmp_id aponta p/ a IDENTIDADE vigente da composição (sem cmp_edi_id). Consultas por edição
--   fazem join com composicoes.
--
-- cc_pct_sp: % do custo atribuído ao preço de SP por ausência
--   de coleta local no estado. NULL para CDHU.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_custo (
    cc_id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cc_cmp_id          BIGINT       NOT NULL,
    cc_edi_id          INTEGER       NOT NULL,   -- FASE 2: série densa por edição (simétrico a insumos_preco)
    cc_uf              CHAR(2)       NOT NULL DEFAULT 'SP',
    cc_modalidade      CHAR(2)       NOT NULL DEFAULT 'SD',
    cc_custo_fonte          NUMERIC(14,4),
    cc_custo_calculado      NUMERIC(14,4),
    cc_diferenca_valor      NUMERIC(14,4),
    cc_diferenca_percentual NUMERIC(12,6),
    cc_status_conferencia   TEXT,
    cc_observacao_conferencia TEXT,
    cc_pct_sp          NUMERIC(8,6),
    cc_criado_em       TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cc_atualizado_em   TIMESTAMPTZ,
    cc_criado_por      TEXT,
    cc_atualizado_por  TEXT,

    CONSTRAINT fk_cc_cmp
        FOREIGN KEY (cc_cmp_id)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT fk_cc_edi
        FOREIGN KEY (cc_edi_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_cc_cmp_edi_uf_mod
        UNIQUE (cc_cmp_id, cc_edi_id, cc_uf, cc_modalidade),

    CONSTRAINT ck_cc_modalidade
        CHECK (cc_modalidade IN ('SD', 'CD', 'SE')),

    CONSTRAINT ck_cc_custo_fonte_nonneg
        CHECK (cc_custo_fonte IS NULL OR cc_custo_fonte >= 0),

    CONSTRAINT ck_cc_custo_calculado_nonneg
        CHECK (cc_custo_calculado IS NULL OR cc_custo_calculado >= 0),

    CONSTRAINT ck_cc_status_conferencia
        CHECK (cc_status_conferencia IS NULL OR cc_status_conferencia IN (
            'NAO_CALCULADO', 'IGUAL', 'DIVERGENTE_ARREDONDAMENTO',
            'DIVERGENTE_RELEVANTE', 'SEM_CUSTO_FONTE', 'SEM_CUSTO_CALCULADO',
            'DERIVADO', 'ERRO_PROCESSAMENTO'
        ))
);

-- (ix_cc_cmp removido: era DUPLICATA EXATA da constraint UNIQUE uq_cc_cmp_edi_uf_mod
--  — mesmas colunas/ordem; o unique cobre 100% as leituras e o delete+insert por edição
--  fica mais leve com 1 índice grande a menos p/ manter.)

-- FASE 2: custo@edição (retroanálise + reimport delete-then-insert por edição).
CREATE INDEX ix_cc_edi
    ON catalogo.composicoes_custo (cc_edi_id);

-- Lidera por cc_uf p/ o LOOSE INDEX SCAN das UFs no filtro (get_filtros). Sem isto, o
-- DISTINCT cc_uf varria os ~18M de linhas (~21s a cada abertura de tela/busca).
-- Em prod aplicar com CREATE INDEX CONCURRENTLY (tabela grande — leva ~1-2 min, sem travar).
CREATE INDEX ix_composicoes_custo_uf
    ON catalogo.composicoes_custo (cc_uf);

-- Recorte edição+UF. Sem ele o planejador cai na UNIQUE uq_cc_cmp_edi_uf_mod, que lidera
-- por cc_cmp_id: como a consulta não filtra por composição, ele não consegue se posicionar
-- e LÊ O ÍNDICE INTEIRO (1,6 GB em prod). Era por isso que somar o filtro de UF deixava a
-- consulta MAIS LENTA devolvendo 27x menos linhas — sintoma clássico de coluna líder errada.
-- Medido em dev (864k linhas): 63,8ms/646 buffers -> 1,5ms/30 buffers.
-- Em prod aplicar com CREATE INDEX CONCURRENTLY, FORA de transação (leva alguns minutos).
CREATE INDEX ix_cc_edi_uf
    ON catalogo.composicoes_custo (cc_edi_id, cc_uf);


-- ============================================================
-- TABELA: catalogo.parametros_normativos   (2026-08-11)
-- Contrato: docs/projects/axys-easy/contracts/catalogo/parametros_normativos.md
-- Constantes LEGAIS/POLÍTICAS com VIGÊNCIA as-of (mudam por normativa, não por edição
-- nem por fonte): CPRB, JORNADA_H_MES… NÃO é um saco de "metadata" genérico — é só
-- parâmetro normativo versionado no tempo, com o REGISTRO do porquê (motivo/anotações).
--   • pn_codigo      identidade textual estável ('CPRB', 'JORNADA_H_MES')
--   • pn_vigencias   JSONB [{"inicio":"AAAA-MM-DD","valor":N}, …] — histórico as-of.
--       Resolução: maior `inicio` ≤ data-de-referência → `valor`. Agregado pequeno,
--       sempre lido junto e raramente escrito → JSONB (não merece tabela-filha).
-- Consumido por bdi_service (CPRB) e conversao_mdo/bancada (JORNADA_H_MES = h/mês).
-- Substitui os hardcodes CPRB_DESONERADO_POR_ANO (bdi_service) e cmm_qtd_h_mes (mapeamento_mdo).
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.parametros_normativos (
    pn_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pn_codigo         TEXT NOT NULL UNIQUE,
    pn_descricao      TEXT,
    pn_motivo         TEXT,                        -- normativa que originou (lei/decreto)
    pn_anotacoes      TEXT,                        -- histórico narrativo (o "porquê" no tempo)
    pn_vigencias      JSONB NOT NULL DEFAULT '[]', -- [{"inicio":"AAAA-MM-DD","valor":N}, …] as-of
    pn_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pn_criado_por     TEXT,
    pn_atualizado_em  TIMESTAMPTZ,
    pn_atualizado_por TEXT
);

-- Seed (get-or-create pelo código — idempotente):
INSERT INTO catalogo.parametros_normativos (pn_codigo, pn_descricao, pn_motivo, pn_anotacoes, pn_vigencias, pn_criado_por) VALUES
 ('JORNADA_H_MES',
  'Jornada mensal padrão (horas/mês) p/ conversão de MDO horista→mensalista. Fator H→MÊS = 1/valor.',
  'CLT art. 58 — 8h/dia, 44h/semana ≈ 220h/mês. Reforma trabalhista poderá reduzir para ~200h.',
  'Hoje 220. Quando a transição virar lei, acrescentar 1 vigência {inicio, 200} — boletim antigo pega o fator da época pela data da edição.',
  '[{"inicio":"1900-01-01","valor":220}]'::jsonb, 'sistema'),
 ('CPRB',
  'CPRB — Contribuição Previdenciária s/ Receita Bruta (construção, regime DESONERADO), % s/ a receita.',
  'Lei 12.844/2013 (4,5%); Lei 14.973/2024 (reoneração gradual até zerar em 2028).',
  'Aplicada no BDI só no regime DESONERADO. 80/60/40% de 4,5 até 2028; a partir daí volta integral à folha (0).',
  '[{"inicio":"2024-01-01","valor":4.5},{"inicio":"2025-01-01","valor":3.6},{"inicio":"2026-01-01","valor":2.7},{"inicio":"2027-01-01","valor":1.8},{"inicio":"2028-01-01","valor":0}]'::jsonb, 'sistema')
ON CONFLICT (pn_codigo) DO NOTHING;


-- ############################################################
-- §EQUIVALÊNCIAS E CONVERSÕES DE CATÁLOGO  (família — 3 tabelas, papéis distintos)
-- ############################################################
-- NÃO unificar (cada uma tem lados, cardinalidade e natureza diferentes; tabela
-- única geraria colunas-nulas e FK polimórfica nos dois lados — dívida estilo
-- ins_external_path). Mantidas separadas por CLAREZA DE PAPEL:
--
--   • composicoes_mapeamento_mdo   comp↔comp · DETERMINÍSTICA N:1 (via insumo MO) · INTRA-FONTE
--       swap exato horista→mensalista (88316→101452). Fator h/mês vem de parametros_normativos
--       (JORNADA_H_MES), não daqui. FORA do refactor de associações — outra finalidade.
--   • equivalencias_mo             MDO entre fontes · assimétrica (INS↔CPU ou INS↔INS) · identity-level
--       (era `conversao_mo_fte_to_sinapi`, renomeada; o prefixo `cmf_` nunca existiu no schema atual)
--   • equivalencias_ins / _cpu     não-MDO · par simétrico · identity-level
--
-- Pipeline de resolução de MO: 1º normaliza FONTE (equivalencias_mo, vira SINAPI-horista)
-- → 2º normaliza REGIME (composicoes_mapeamento_mdo, horista→mensalista).
--
-- ⚠️ `insumos_equivalencias` (legada, insumo↔insumo difusa) NÃO entra mais nesta família:
-- decisão 2026-09-21 — a tabela SOBRA e será removida quando as telas pararem de usá-la.
-- ############################################################

-- ============================================================
-- TABELA: catalogo.composicoes_mapeamento_mdo
-- Contrato de regra de negócio (canônico):
--   docs/projects/axys-easy/contracts/catalogo/listagem.md  (§3.4)
-- Mapa horista <-> mensalista de CPUs de mão de obra, FONTE-LEVEL. A conversão
--   H<->MES NÃO é linear (a CPU mensalista tem itens próprios, não é horista*220)
--   → guarda-se o PAR. Populado por fuzzy pós-import (PLANO Fase 3.5). Consumido
--   no módulo ATIVO/orçamento (escolha da base mensalista), não no catálogo.
-- FONTE-LEVEL (2026-08-11): cmp_id é IDENTIDADE (1 linha por fonte+código; custo por
--   edição vive em composicoes_custo), então o par vale no catálogo inteiro — uq só em
--   cmm_cmp_id_h. Removidos cmm_edi_id (era só proveniência) e cmm_qtd_h_mes (o fator
--   h/mês é lei, não dado do par → migrou p/ parametros_normativos.JORNADA_H_MES, as-of).
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.composicoes_mapeamento_mdo (
    cmm_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cmm_cmp_id_h       BIGINT NOT NULL,
    cmm_cmp_id_mes     BIGINT NOT NULL,
    cmm_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cmm_atualizado_em  TIMESTAMPTZ,
    cmm_criado_por     TEXT,
    cmm_atualizado_por TEXT,

    CONSTRAINT fk_composicoes_mapeamento_mdo_h
        FOREIGN KEY (cmm_cmp_id_h)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    CONSTRAINT fk_composicoes_mapeamento_mdo_mes
        FOREIGN KEY (cmm_cmp_id_mes)
        REFERENCES catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,

    -- N:1 permitido: N CPUs-H podem apontar p/ a MESMA CPU-MÊS (ex.: CALCETEIRO + RASTELEIRO → 1 MÊS
    -- CALCETEIRO; SINAPI tem 1 insumo/CPU-MÊS p/ 2 ofícios-H, mesmo preço). Cada H tem 1 MÊS (uq_h); o
    -- MÊS NÃO é único (2026-07-12: removida uq_cmm_mes; era 1:1). Pareamento pelo INSUMO MO (a verdade).
    CONSTRAINT uq_composicoes_mapeamento_mdo_h
        UNIQUE (cmm_cmp_id_h)
);

CREATE INDEX ix_composicoes_mapeamento_mdo_mes
    ON catalogo.composicoes_mapeamento_mdo (cmm_cmp_id_mes);


-- ============================================================
-- GUARDA de catalogo.composicoes_mapeamento_mdo (H↔MÊS)
-- Contrato: contracts/catalogo/vinculacoes.md §0 (tabela FORA do refactor de associações)
--
-- A tabela é INTRA-FONTE e CPU↔CPU: horista [H] → mensalista [MÊS] da MESMA fonte.
-- Isso nunca esteve escrito no banco — só no comportamento do gerador (conciliar_mdo).
-- A exposição real é a tela `hmes/curar`, onde um humano escolhe a composição à mão.
--
-- NÃO se checa o subgrupo ('CÁLCULOS E PARÂMETROS'): é nome específico do SINAPI, muda
-- quando a fonte renomeia, e é redundante — que outra composição vai de HORA para MÊS?
-- A unidade carrega a semântica inteira e vale para qualquer fonte futura com H/MÊS.
-- ============================================================
CREATE OR REPLACE FUNCTION catalogo.trg_cmm_guarda() RETURNS trigger AS $$
DECLARE
    un_h TEXT; un_m TEXT; fte_h INTEGER; fte_m INTEGER;
BEGIN
    IF NEW.cmm_cmp_id_h = NEW.cmm_cmp_id_mes THEN
        RAISE EXCEPTION 'H<->MES: horista e mensalista nao podem ser a mesma composicao (cmp_id=%)',
            NEW.cmm_cmp_id_h;
    END IF;

    SELECT upper(btrim(cmp_unidade)), cmp_fte_id INTO un_h, fte_h
      FROM catalogo.composicoes WHERE cmp_id = NEW.cmm_cmp_id_h;
    SELECT upper(btrim(cmp_unidade)), cmp_fte_id INTO un_m, fte_m
      FROM catalogo.composicoes WHERE cmp_id = NEW.cmm_cmp_id_mes;

    IF un_h IS DISTINCT FROM 'H' THEN
        RAISE EXCEPTION 'H<->MES: o lado horista tem de ser [H] (cmp_id=%, unidade=%)',
            NEW.cmm_cmp_id_h, COALESCE(un_h, '<inexistente>');
    END IF;

    IF catalogo.unaccent(COALESCE(un_m, '')) IS DISTINCT FROM 'MES' THEN
        RAISE EXCEPTION 'H<->MES: o lado mensalista tem de ser [MES] (cmp_id=%, unidade=%)',
            NEW.cmm_cmp_id_mes, COALESCE(un_m, '<inexistente>');
    END IF;

    IF fte_h IS DISTINCT FROM fte_m THEN
        RAISE EXCEPTION 'H<->MES: os dois lados tem de ser da MESMA fonte (fte % <> fte %)',
            fte_h, fte_m;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_cmm_guarda ON catalogo.composicoes_mapeamento_mdo;
CREATE TRIGGER t_cmm_guarda
    BEFORE INSERT OR UPDATE ON catalogo.composicoes_mapeamento_mdo
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_cmm_guarda();


-- ============================================================
-- TABELAS: catalogo.equivalencias_ins  +  catalogo.equivalencias_cpu   (NÃO-MDO)
-- Contrato: docs/.../contracts/catalogo/vinculacoes.md §11 · §12 · §13.3
--
-- REFACTOR 2026-09-22 — o que mudou e por quê:
--  · Caiu o CHECK ref_fonte IN ('SINAPI','SICRO'): enquanto existia, fonte→fonte era
--    PROIBIDO pelo banco, não apenas ausente do código.
--  · Caíram ei_ref_fonte/ei_fte_codigo (e ec_*): redundância PROVADA — divergiam do
--    ins_fte_id em 0 de 357 linhas e nenhuma constraint as usava. A fonte deriva do id.
--  · ref/fte → a/b: sem âncora, "referência" e "fonte" não descrevem mais os lados.
--  · A UNIQUE sobre a tupla ORDENADA saiu. Ela aceitava (A,B) E (B,A) como linhas
--    distintas para o MESMO fato — a relação é SIMÉTRICA (§11.1). O índice funcional
--    sobre LEAST/GREATEST garante UM par, UMA linha, e é à prova de corrida (checagem
--    em trigger ou na aplicação não é: duas gravações simultâneas não se enxergam).
--
-- A relação é simétrica mas NÃO transitiva (§11.1): A=B e A=C nada dizem sobre B e C.
-- Por isso NÃO HÁ PONTE — CDHU→FDE não se deriva de CDHU→SINAPI + FDE→SINAPI.
-- A DIREÇÃO permanece nas colunas porque o fator tem sentido (GL → 3,6 L ≠ o inverso).
-- Identity-level: a equivalência é fato sobre o ITEM, não sobre a edição.
-- Revalidação por hash da descrição (§9). metodo: TOKEN|IA|MANUAL.
-- ============================================================
-- HASH de identidade (ringue R3, 2026-09-23). `hash_a` acompanha a coluna `a` e `hash_b` a `b` —
-- os nomes anteriores (origem/equivalente) não descreviam nada num par SIMÉTRICO e já causaram uma
-- inversão real na carga da curadoria do Maicon. Guarda sha1 de `descrição|unidade` normalizadas:
-- é a foto do item COMO ESTAVA QUANDO UMA PESSOA DECIDIU. "Mudou desde a curadoria?" é este hash
-- contra o do texto atual, e a tela deriva de status × hash. Só ação humana atualiza o hash — a
-- máquina lê, nunca escreve (senão a pergunta perde a resposta, que foi por que existia 'revisar').
-- STATUS das três tabelas de equivalência — vocabulário FECHADO por CHECK (ringue R0, 2026-09-22).
--   pendente   proposta de MÁQUINA. Só sobrevive DENTRO de um import: o gate não deixa a etapa
--              fechar deixando pendente para trás.
--   confirmado | rejeitado   DECISÃO HUMANA, tomada em tela. A IA propõe, ranqueia e REAPLICA
--              decisão existente — nunca cria decisão. Rejeição mata a DUPLA, não o item: o item
--              continua recebendo outros candidatos.
-- NÃO existe status 'revisar'. "Mudou desde a curadoria?" é hash guardado × hash do texto atual,
-- e a tela é derivada de status × hash. O hash só é atualizado por ação humana.
-- Ver contracts/catalogo/vinculacoes.md.
CREATE TABLE IF NOT EXISTS catalogo.equivalencias_ins (
    ei_id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- LADOS CANÔNICOS: `ori` guarda o item da fonte de MAIOR fte_id, `dest` o da MENOR.
    -- "ori/dest" é POSIÇÃO DE ARMAZENAMENTO, não sentido de conversão — a conversão vale nos dois
    -- sentidos. A ordem é imposta pelo ck_ei_canonico e normalizada pela trigger: o motor grava na
    -- ordem que quiser e o banco arruma. Sem isso os índices abaixo não seguram (ver comentário).
    ei_ori_ins_id        BIGINT  NOT NULL REFERENCES catalogo.insumos(ins_id) ON UPDATE CASCADE ON DELETE CASCADE,
    ei_dest_ins_id       BIGINT  NOT NULL REFERENCES catalogo.insumos(ins_id) ON UPDATE CASCADE ON DELETE CASCADE,
    -- fonte de CADA lado, desnormalizada: o índice não consegue fazer JOIN para descobri-la.
    -- Derivada e conferida pela trigger — mesmo arranjo do mo_dest_fte_id.
    ei_ori_fte_id        INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    ei_dest_fte_id       INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    ei_classe            TEXT,                              -- 'direta' | 'calculada' | 'especial'
    ei_fator_conversao   NUMERIC(12,6),                     -- NULL=especial · 1=direta · k=calculada
    ei_status            TEXT    NOT NULL DEFAULT 'pendente',   -- pendente | confirmado | rejeitado
    ei_score             NUMERIC(4,3),
    ei_metodo            TEXT,
    ei_hash_ori          TEXT, ei_hash_dest TEXT,           -- identidade (desc+unidade) de CADA lado
    ei_observacao        TEXT,
    ei_ativo             BOOLEAN NOT NULL DEFAULT TRUE,
    ei_criado_em         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, ei_atualizado_em TIMESTAMPTZ,
    ei_criado_por        TEXT, ei_atualizado_por TEXT,
    CONSTRAINT ck_ei_classe    CHECK (ei_classe IS NULL OR ei_classe IN ('direta', 'calculada', 'especial')),
    CONSTRAINT ck_ei_status    CHECK (ei_status IN ('pendente', 'confirmado', 'rejeitado')),
    CONSTRAINT ck_ei_nao_self  CHECK (ei_ori_ins_id <> ei_dest_ins_id),
    CONSTRAINT ck_ei_canonico  CHECK (ei_ori_fte_id > ei_dest_fte_id)
);
-- ═══ 1×1 DURO — a razão de ser desta tabela ═══════════════════════════════════════════════════
-- Ela existe para CONVERTER orçamento entre fontes. Se um insumo tivesse dois equivalentes na
-- mesma fonte, o back teria de ESCOLHER — decisão de máquina em cima de decisão humana, que é
-- justamente o que o motor inteiro proíbe. Então: um item tem NO MÁXIMO UM parceiro por fonte.
--
-- São DOIS índices porque a conversão vale nos DOIS sentidos, e cada um larga um dos itens: o que
-- se quer proibir é "o cimento do CDHU ter dois parceiros no SINAPI". Incluir o parceiro na chave
-- não proíbe nada — cada parceiro diferente vira uma chave diferente. Medido em 2026-09-23 contra
-- o caso real do CIMENTO CPII-E-32: um único índice sobre a tupla inteira aceitou 5 linhas onde
-- deviam entrar 3.
--
-- E os dois índices SÓ funcionam com a ordem canônica: se o item pudesse cair ora num lado ora no
-- outro, ele se esconderia entre os dois. Por isso o ck_ei_canonico.
CREATE UNIQUE INDEX uq_ei_ori  ON catalogo.equivalencias_ins (ei_ori_ins_id,  ei_dest_fte_id);
CREATE UNIQUE INDEX uq_ei_dest ON catalogo.equivalencias_ins (ei_dest_ins_id, ei_ori_fte_id);
CREATE INDEX ix_ei_ori  ON catalogo.equivalencias_ins (ei_ori_ins_id);
CREATE INDEX ix_ei_dest ON catalogo.equivalencias_ins (ei_dest_ins_id);

-- ═══ A FONTE DE CADA LADO NÃO PODE MENTIR ════════════════════════════════════════════════════
-- `ei_{ori,dest}_fte_id` é desnormalização OBRIGATÓRIA: a regra é "um parceiro por FONTE", e o
-- "por fonte" tem de ser COLUNA porque índice não faz JOIN — ele não consegue ir até catalogo.insumos
-- perguntar de que fonte é o item. Se a coluna divergisse do item, o índice único estaria
-- garantindo unicidade sobre uma ficção e dois parceiros da mesma fonte entrariam.
-- Antes isso era mantido por trigger. Agora é FK COMPOSTA: declarativa, no schema, e sem como
-- burlar. Exige o UNIQUE (id, fte_id) do outro lado, criado junto de catalogo.insumos.
ALTER TABLE catalogo.equivalencias_ins
    ADD CONSTRAINT fk_ei_ori_fte  FOREIGN KEY (ei_ori_ins_id,  ei_ori_fte_id)
        REFERENCES catalogo.insumos(ins_id, ins_fte_id),
    ADD CONSTRAINT fk_ei_dest_fte FOREIGN KEY (ei_dest_ins_id, ei_dest_fte_id)
        REFERENCES catalogo.insumos(ins_id, ins_fte_id);

CREATE TABLE IF NOT EXISTS catalogo.equivalencias_cpu (
    ec_id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- mesma regra de equivalencias_ins: `ori` = fonte de MAIOR fte_id, `dest` = MENOR.
    ec_ori_cmp_id        BIGINT  NOT NULL REFERENCES catalogo.composicoes(cmp_id) ON UPDATE CASCADE ON DELETE CASCADE,
    ec_dest_cmp_id       BIGINT  NOT NULL REFERENCES catalogo.composicoes(cmp_id) ON UPDATE CASCADE ON DELETE CASCADE,
    ec_ori_fte_id        INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    ec_dest_fte_id       INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    ec_classe            TEXT, ec_fator_conversao NUMERIC(12,6),
    ec_status            TEXT    NOT NULL DEFAULT 'pendente', ec_score NUMERIC(4,3), ec_metodo TEXT,
    ec_hash_ori          TEXT, ec_hash_dest TEXT, ec_observacao TEXT,
    ec_ativo             BOOLEAN NOT NULL DEFAULT TRUE,
    ec_criado_em         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, ec_atualizado_em TIMESTAMPTZ,
    ec_criado_por        TEXT, ec_atualizado_por TEXT,
    CONSTRAINT ck_ec_classe   CHECK (ec_classe IS NULL OR ec_classe IN ('direta', 'calculada', 'especial')),
    CONSTRAINT ck_ec_status   CHECK (ec_status IN ('pendente', 'confirmado', 'rejeitado')),
    CONSTRAINT ck_ec_nao_self CHECK (ec_ori_cmp_id <> ec_dest_cmp_id),
    CONSTRAINT ck_ec_canonico CHECK (ec_ori_fte_id > ec_dest_fte_id)
);
CREATE UNIQUE INDEX uq_ec_ori  ON catalogo.equivalencias_cpu (ec_ori_cmp_id,  ec_dest_fte_id);
CREATE UNIQUE INDEX uq_ec_dest ON catalogo.equivalencias_cpu (ec_dest_cmp_id, ec_ori_fte_id);
CREATE INDEX ix_ec_ori  ON catalogo.equivalencias_cpu (ec_ori_cmp_id);
CREATE INDEX ix_ec_dest ON catalogo.equivalencias_cpu (ec_dest_cmp_id);

-- ═══ A FONTE DE CADA LADO NÃO PODE MENTIR ════════════════════════════════════════════════════
-- `ec_{ori,dest}_fte_id` é desnormalização OBRIGATÓRIA: a regra é "um parceiro por FONTE", e o
-- "por fonte" tem de ser COLUNA porque índice não faz JOIN — ele não consegue ir até catalogo.composicoes
-- perguntar de que fonte é o item. Se a coluna divergisse do item, o índice único estaria
-- garantindo unicidade sobre uma ficção e dois parceiros da mesma fonte entrariam.
-- Antes isso era mantido por trigger. Agora é FK COMPOSTA: declarativa, no schema, e sem como
-- burlar. Exige o UNIQUE (id, fte_id) do outro lado, criado junto de catalogo.composicoes.
ALTER TABLE catalogo.equivalencias_cpu
    ADD CONSTRAINT fk_ec_ori_fte  FOREIGN KEY (ec_ori_cmp_id,  ec_ori_fte_id)
        REFERENCES catalogo.composicoes(cmp_id, cmp_fte_id),
    ADD CONSTRAINT fk_ec_dest_fte FOREIGN KEY (ec_dest_cmp_id, ec_dest_fte_id)
        REFERENCES catalogo.composicoes(cmp_id, cmp_fte_id);


-- ============================================================
-- TABELA: catalogo.equivalencias_mo   (MÃO DE OBRA — isolada)
-- Contrato: vinculacoes.md §13.3(d)
--
-- Por que é separada de equivalencias_ins: a MDO é ASSIMÉTRICA por natureza — nas fontes
-- (CDHU/FDE) é INSUMO; no SINAPI é COMPOSIÇÃO ("… COM ENCARGOS COMPLEMENTARES"), porque
-- ali moram os encargos.
--
-- REFACTOR 2026-09-22 — 4 colunas nuláveis no lugar do id polimórfico:
--  · A FK física antiga (mo_ref_item_id -> composicoes) CONTRADIZIA o próprio mo_ref_tipo:
--    obrigava o lado ref a ser CPU. MO fonte→fonte (pedreiro-CDHU ↔ pedreiro-FDE) tem os
--    DOIS lados insumo → violava a FK na hora.
--  · O id polimórfico não tinha FK do lado da fonte, e 12.216 ids existem ao mesmo tempo
--    em insumos e composicoes: um id errado não falhava — apontava em silêncio para a
--    linha errada do tipo errado. Agora cada id mora na coluna com FK à tabela certa.
--  · mo_ref_tipo/mo_fte_tipo caíram: o tipo é derivável da coluna preenchida.
--  · mo_ori_cpu fica SEM caso de uso hoje (a MDO das fontes é sempre insumo) — é
--    deliberado: se surgir fonte no formato SINAPI, a app aguenta sem migração.
--  · SEM coluna de fator: os dois lados são sempre [H] (garantido por trigger).
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.equivalencias_mo (
    mo_id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mo_ori_ins       BIGINT NULL REFERENCES catalogo.insumos(ins_id)     ON UPDATE CASCADE ON DELETE CASCADE,
    mo_ori_cpu       BIGINT NULL REFERENCES catalogo.composicoes(cmp_id) ON UPDATE CASCADE ON DELETE CASCADE,
    mo_dest_ins      BIGINT NULL REFERENCES catalogo.insumos(ins_id)     ON UPDATE CASCADE ON DELETE CASCADE,
    mo_dest_cpu      BIGINT NULL REFERENCES catalogo.composicoes(cmp_id) ON UPDATE CASCADE ON DELETE CASCADE,
    -- fonte do DESTINO: desnormalização necessária — Postgres não expressa
    -- "único por (origem, fonte_de(destino))" sem ela. Mantida honesta por trigger.
    mo_dest_fte_id   INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    mo_status        TEXT NOT NULL DEFAULT 'pendente',   -- pendente | confirmado | rejeitado
    mo_score         NUMERIC(4,3),
    mo_obs           TEXT,
    mo_criado_em     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, mo_atualizado_em TIMESTAMPTZ,
    mo_criado_por    TEXT, mo_atualizado_por TEXT,
    -- etiqueta canônica p/ o índice do par. O prefixo I/C é essencial: sem ele,
    -- insumo 500 e composição 500 seriam o mesmo valor (12.216 ids colidem).
    mo_a TEXT GENERATED ALWAYS AS (COALESCE('I' || mo_ori_ins,  'C' || mo_ori_cpu))  STORED,
    mo_b TEXT GENERATED ALWAYS AS (COALESCE('I' || mo_dest_ins, 'C' || mo_dest_cpu)) STORED,
    CONSTRAINT ck_mo_ori_um   CHECK (num_nonnulls(mo_ori_ins,  mo_ori_cpu)  = 1),
    CONSTRAINT ck_mo_dest_um  CHECK (num_nonnulls(mo_dest_ins, mo_dest_cpu) = 1),
    CONSTRAINT ck_mo_nao_self CHECK (mo_a <> mo_b),
    CONSTRAINT ck_mo_status   CHECK (mo_status IN ('pendente', 'confirmado', 'rejeitado'))
);
CREATE UNIQUE INDEX uq_mo_par  ON catalogo.equivalencias_mo (LEAST(mo_a, mo_b), GREATEST(mo_a, mo_b));
-- uma função, UM alvo por fonte-destino: não existem dois pedreiros com preço diferente.
CREATE UNIQUE INDEX uq_mo_alvo ON catalogo.equivalencias_mo (mo_a, mo_dest_fte_id);
CREATE INDEX ix_mo_dest_ins ON catalogo.equivalencias_mo (mo_dest_ins);
CREATE INDEX ix_mo_dest_cpu ON catalogo.equivalencias_mo (mo_dest_cpu);

-- Mesma ideia em MO, sobre as DUAS colunas nuláveis de destino. Exatamente uma delas está
-- preenchida (ck_mo_dest_um), e FK composta com NULL não é verificada — então vale sempre a
-- que importa, e a outra fica calada. MO não tem lado `ori` desnormalizado, logo são só duas.
ALTER TABLE catalogo.equivalencias_mo
    ADD CONSTRAINT fk_mo_dest_ins_fte FOREIGN KEY (mo_dest_ins, mo_dest_fte_id)
        REFERENCES catalogo.insumos(ins_id, ins_fte_id),
    ADD CONSTRAINT fk_mo_dest_cpu_fte FOREIGN KEY (mo_dest_cpu, mo_dest_fte_id)
        REFERENCES catalogo.composicoes(cmp_id, cmp_fte_id);


-- ═══════════ FASE C — guardas de tipo das 3 tabelas ═══════════
-- Contrato: vinculacoes.md §13.4 · Plano §2.4
--
-- Por que trigger e não CHECK: o tipo do item não está na linha gravada — está em
-- `insumos.ins_ti_id` / `composicoes_subgrupos.sub_descricao`. CHECK só enxerga a
-- própria linha. Custo: leitura por chave primária, microssegundos.
-- Ganho: não existe caminho que escape — import, tela, IA, script ou psql.

-- ── predicado único de "é composição MDO" (SINAPI/SICRO guardam MDO como CPU) ──
CREATE OR REPLACE FUNCTION catalogo.cmp_e_mdo(p_cmp_id BIGINT) RETURNS BOOLEAN AS $$
    SELECT EXISTS (
        SELECT 1 FROM catalogo.composicoes c
        JOIN catalogo.composicoes_subgrupos s ON s.sub_id = c.cmp_sub_id
        WHERE c.cmp_id = p_cmp_id
          AND catalogo.unaccent(upper(s.sub_descricao)) LIKE '%CALCULOS E PARAMETROS%');
$$ LANGUAGE sql STABLE;

CREATE OR REPLACE FUNCTION catalogo.ins_e_mo(p_ins_id BIGINT) RETURNS BOOLEAN AS $$
    SELECT EXISTS (
        SELECT 1 FROM catalogo.insumos i
        JOIN catalogo.insumos_tipo t ON t.ti_id = i.ins_ti_id
        WHERE i.ins_id = p_ins_id AND t.ti_codigo = 'MO');
$$ LANGUAGE sql STABLE;

-- ── (1) equivalencias_ins: mão de obra NÃO entra aqui ──
-- Esta guarda fecha uma sobreposição que o PRÓPRIO refactor criou: antes, MO sempre
-- tinha composição de um lado, o que não cabia nesta tabela — proteção ACIDENTAL.
-- Com MO fonte→fonte (pedreiro-CDHU ↔ pedreiro-FDE) a mesma linha passou a caber nas duas.
-- ═══ TRIGGER PODE RECUSAR. TRIGGER NÃO PODE REESCREVER. (2026-09-28) ═════════════════════════
-- Estas três triggers faziam as duas coisas, e a parte que reescrevia produziu dado errado em
-- silêncio: ao normalizar a ordem dos lados, ela trocava os ids E os hashes — mas NÃO invertia o
-- `fator_conversao`. Quem gravasse "SINAPI × 4 = CDHU" recebia "CDHU × 4 = SINAPI" guardado. O
-- correto era 0,25: erro de 16×, sem aviso, e invisível em code review porque o código que
-- reescreve não está no arquivo que se está lendo.
--
-- O que sobrou aqui são só `RAISE` — recusas que precisam de um JOIN e por isso não cabem num
-- CHECK. Uma trigger que só recusa não pode gerar dado errado: ela só faz o INSERT falhar, alto.
--
-- As três tarefas que REESCREVIAM saíram e viraram declarativas:
--   · reordenar os lados   → `ck_*_canonico` RECUSA a ordem invertida (o `>` é estrito, então
--                            ele também recusa par da mesma fonte, nos dois sentidos)
--   · derivar a fonte      → FK COMPOSTA (id, fte_id): não há como mentir a fonte de um lado
--   · inverter o hash      → deixa de existir; sem reordenação, o hash nunca cruza
-- Quem ordena canonicamente agora é o back (`_grava_par`), que RECUSA a ordem invertida em vez
-- de consertá-la — o chamador fica sabendo. Escritor é um só: a app.
-- ═════════════════════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION catalogo.trg_eq_ins_guarda() RETURNS trigger AS $$
BEGIN
    IF catalogo.ins_e_mo(NEW.ei_ori_ins_id) OR catalogo.ins_e_mo(NEW.ei_dest_ins_id) THEN
        RAISE EXCEPTION 'equivalencias_ins: mao de obra nao entra aqui - use equivalencias_mo (ins %, %)',
            NEW.ei_ori_ins_id, NEW.ei_dest_ins_id;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_ei_guarda ON catalogo.equivalencias_ins;
CREATE TRIGGER t_ei_guarda BEFORE INSERT OR UPDATE ON catalogo.equivalencias_ins
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_eq_ins_guarda();

-- ── (2) equivalencias_cpu: composição MDO do header JAMAIS entra aqui ──
CREATE OR REPLACE FUNCTION catalogo.trg_eq_cpu_guarda() RETURNS trigger AS $$
BEGIN
    IF catalogo.cmp_e_mdo(NEW.ec_ori_cmp_id) OR catalogo.cmp_e_mdo(NEW.ec_dest_cmp_id) THEN
        RAISE EXCEPTION 'equivalencias_cpu: composicao MDO nao entra aqui - use equivalencias_mo (cmp %, %)',
            NEW.ec_ori_cmp_id, NEW.ec_dest_cmp_id;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_ec_guarda ON catalogo.equivalencias_cpu;
CREATE TRIGGER t_ec_guarda BEFORE INSERT OR UPDATE ON catalogo.equivalencias_cpu
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_eq_cpu_guarda();

-- ── (3) equivalencias_mo: só MO, só [H], destino certo, fonte honesta ──
CREATE OR REPLACE FUNCTION catalogo.trg_eq_mo_guarda() RETURNS trigger AS $$
DECLARE
    un_o TEXT; un_d TEXT; fte_d INTEGER;
BEGIN
    -- (a) os dois lados TÊM de ser mão de obra
    IF NEW.mo_ori_ins IS NOT NULL AND NOT catalogo.ins_e_mo(NEW.mo_ori_ins) THEN
        RAISE EXCEPTION 'equivalencias_mo: a origem (ins %) nao e mao de obra', NEW.mo_ori_ins;
    END IF;
    IF NEW.mo_ori_cpu IS NOT NULL AND NOT catalogo.cmp_e_mdo(NEW.mo_ori_cpu) THEN
        RAISE EXCEPTION 'equivalencias_mo: a origem (cmp %) nao e composicao MDO', NEW.mo_ori_cpu;
    END IF;
    IF NEW.mo_dest_ins IS NOT NULL AND NOT catalogo.ins_e_mo(NEW.mo_dest_ins) THEN
        RAISE EXCEPTION 'equivalencias_mo: o destino (ins %) nao e mao de obra', NEW.mo_dest_ins;
    END IF;
    IF NEW.mo_dest_cpu IS NOT NULL AND NOT catalogo.cmp_e_mdo(NEW.mo_dest_cpu) THEN
        RAISE EXCEPTION 'equivalencias_mo: o destino (cmp %) nao e composicao MDO', NEW.mo_dest_cpu;
    END IF;

    -- (b) unidade [H] dos DOIS lados — é o que torna "MO nao tem fator" uma INVARIANTE.
    -- O SINAPI tem 92 insumos e 184 composicoes MDO em [MES]; se uma entrasse, a ausencia
    -- de fator nao daria erro: daria resultado 220x errado, calado.
    SELECT upper(btrim(u)) INTO un_o FROM (
        SELECT (SELECT ins_unidade FROM catalogo.insumos     WHERE ins_id = NEW.mo_ori_ins) AS u
        UNION ALL
        SELECT (SELECT cmp_unidade FROM catalogo.composicoes WHERE cmp_id = NEW.mo_ori_cpu)
    ) z WHERE u IS NOT NULL LIMIT 1;
    SELECT upper(btrim(u)), f INTO un_d, fte_d FROM (
        SELECT (SELECT ins_unidade FROM catalogo.insumos     WHERE ins_id = NEW.mo_dest_ins) AS u,
               (SELECT ins_fte_id  FROM catalogo.insumos     WHERE ins_id = NEW.mo_dest_ins) AS f
        UNION ALL
        SELECT (SELECT cmp_unidade FROM catalogo.composicoes WHERE cmp_id = NEW.mo_dest_cpu),
               (SELECT cmp_fte_id  FROM catalogo.composicoes WHERE cmp_id = NEW.mo_dest_cpu)
    ) z WHERE u IS NOT NULL LIMIT 1;

    IF un_o IS DISTINCT FROM 'H' THEN
        RAISE EXCEPTION 'equivalencias_mo: a origem tem de ser [H] (unidade=%)', COALESCE(un_o,'<inexistente>');
    END IF;
    IF un_d IS DISTINCT FROM 'H' THEN
        RAISE EXCEPTION 'equivalencias_mo: o destino tem de ser [H] (unidade=%)', COALESCE(un_d,'<inexistente>');
    END IF;

    -- (c) se a fonte-destino modela MDO como COMPOSICAO, o destino nao pode ser o insumo.
    -- Risco que nasceu das colunas nulaveis: o SINAPI tem 94 insumos MO [H] E 193 composicoes
    -- MDO [H]. Apontar para o INSUMO entrega o preco PELADO, sem encargos - e passa em (a) e (b).
    IF NEW.mo_dest_ins IS NOT NULL AND EXISTS (
        SELECT 1 FROM catalogo.composicoes c
        JOIN catalogo.composicoes_subgrupos s ON s.sub_id = c.cmp_sub_id
        WHERE c.cmp_fte_id = fte_d
          AND catalogo.unaccent(upper(s.sub_descricao)) LIKE '%CALCULOS E PARAMETROS%') THEN
        RAISE EXCEPTION 'equivalencias_mo: a fonte-destino guarda MDO como COMPOSICAO - aponte para a composicao "... COM ENCARGOS COMPLEMENTARES", nao para o insumo % (preco pelado, sem encargos)',
            NEW.mo_dest_ins;
    END IF;

    -- (d) a honestidade de mo_dest_fte_id agora e da FK COMPOSTA (fk_mo_dest_ins_fte /
    -- fk_mo_dest_cpu_fte), nao desta trigger: declarativa, visivel no schema, e o chamador
    -- simplesmente nao consegue mentir. Aqui so se RECUSA.
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_mo_guarda ON catalogo.equivalencias_mo;
CREATE TRIGGER t_mo_guarda BEFORE INSERT OR UPDATE ON catalogo.equivalencias_mo
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_eq_mo_guarda();


-- ============================================================
-- TABELAS: catalogo.equivalencias_ins_negadas / _cpu_negadas   (2026-10-06)
-- Contrato: docs/projects/axys-easy/contracts/catalogo/vinculacoes.md §5.7 · §1.1
--
-- A RECUSA COMO FATO. Guardam "este item foi examinado contra esta fonte, contra estes
-- candidatos, nesta data, e a resposta foi NÃO". Não é ausência (que não se guarda, §1.1) —
-- é decisão humana datada, e decisão se guarda. Sem isto, as 16.006 recusas da curadoria
-- voltam à fila no próximo import e a IA é paga de novo para reencontrar o mesmo "não".
--
-- POR QUE TABELA PRÓPRIA, e não `status='rejeitado'` nas três. Duas razões independentes:
--   1. `uq_ei_ori (ei_ori_ins_id, ei_dest_fte_id)` NÃO é parcial. Uma linha de recusa lá
--      consumiria a ÚNICA VAGA do item naquela fonte e bloquearia o parceiro verdadeiro para
--      sempre. Hospedar recusa exigiria afrouxar a trava que é a razão de ser da tabela (§14).
--   2. Recusa aqui NÃO É PAR: as 16.006 têm destino nulo, sem exceção — dizem "este item não
--      tem equivalente nesta fonte", não "A não é B". Um dest_id nulo quebraria junto
--      ck_*_nao_self, ck_*_canonico e a FK composta, que pressupõem dois lados reais.
-- Por isso a forma NÃO replica as três: classe, fator e ordem canônica não significam nada aqui.
--
-- DOIS SINAIS, e é o ponto do desenho. `hash_item` responde "o item mudou?"; ele NÃO responde
-- "nasceu candidato novo?", e a regra do motor é OS DOIS LADOS CONTAM. Sem o segundo a negativa
-- deixa de ser memória e vira MORDAÇA: o item nunca mais seria reconsiderado, mesmo que a fonte de
-- destino publicasse amanhã exatamente o par que faltava.
--
-- O segundo sinal é a LISTA dos candidatos examinados, não uma hash dela. Hash só responde
-- "conjunto idêntico?", e o conjunto que a curadoria examinou veio de OUTRO produtor (os scripts
-- de curadoria) — nunca bateria com o que o matcher monta hoje, e a negativa reabriria sempre.
-- Com a lista, a pergunta é a certa: REABRE se o item mudou OU se existe candidato hoje que NÃO
-- estava na lista. Candidato que DESAPARECEU não reabre (não há nada novo a examinar).
-- Volume: mediana 15 ids, máximo 141.
--
-- MDO FICA FORA de propósito: seu matcher é determinístico e não chama IA — são 8 recusas, e
-- recomputá-las custa zero. Tabela para 8 linhas sem custo é peso sem retorno (§5.7).
--
-- SEM coluna de caminho do R2: o path é determinístico (storage_paths.associacao) e path
-- determinístico não se guarda.
-- ============================================================

CREATE TABLE IF NOT EXISTS catalogo.equivalencias_ins_negadas (
    ein_id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ein_ins_id           BIGINT  NOT NULL REFERENCES catalogo.insumos(ins_id)
                                 ON UPDATE CASCADE ON DELETE CASCADE,
    ein_fte_id           INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),   -- onde NÃO há equivalente
    ein_hash_item        TEXT    NOT NULL,       -- identidade (desc+unidade) quando se decidiu
    ein_candidatos       BIGINT[],                -- ids examinados (NULL = não registrado → só a hash vale)
    ein_motivo           TEXT,
    ein_por              TEXT,
    ein_em               TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- o análogo do 1×1: uma negativa por item×fonte. Reexaminar NÃO cria linha nova — atualiza
    -- as hashes da existente (get-or-create), senão o histórico de uma recusa viraria N linhas.
    CONSTRAINT uq_ein UNIQUE (ein_ins_id, ein_fte_id)
);

CREATE INDEX ix_ein_fte ON catalogo.equivalencias_ins_negadas (ein_fte_id);

CREATE TABLE IF NOT EXISTS catalogo.equivalencias_cpu_negadas (
    ecn_id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ecn_cmp_id           BIGINT  NOT NULL REFERENCES catalogo.composicoes(cmp_id)
                                 ON UPDATE CASCADE ON DELETE CASCADE,
    ecn_fte_id           INTEGER NOT NULL REFERENCES catalogo.fontes(fte_id),
    ecn_hash_item        TEXT    NOT NULL,
    ecn_candidatos       BIGINT[],
    ecn_motivo           TEXT,
    ecn_por              TEXT,
    ecn_em               TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_ecn UNIQUE (ecn_cmp_id, ecn_fte_id)
);

CREATE INDEX ix_ecn_fte ON catalogo.equivalencias_cpu_negadas (ecn_fte_id);

-- ── guardas das negadas: RECUSAM, não reescrevem (mesma doutrina da FASE C acima) ──
-- Duas recusas, as duas precisando de JOIN (por isso trigger e não CHECK):
--   (a) negativa contra a fonte DO PRÓPRIO item é contradição — nada é equivalente a si;
--   (b) confirmado e negado são MUTUAMENTE EXCLUSIVOS no mesmo (item, fonte): ou o item tem
--       parceiro ali, ou tem negativa. As duas coisas juntas é registro que se contradiz, e
--       quem leria primeiro decidiria o comportamento — exatamente o tipo de silêncio que a
--       nota da FASE C manda não repetir.
CREATE OR REPLACE FUNCTION catalogo.trg_eq_ins_negada_guarda() RETURNS trigger AS $$
DECLARE fte_item INTEGER;
BEGIN
    SELECT ins_fte_id INTO fte_item FROM catalogo.insumos WHERE ins_id = NEW.ein_ins_id;
    IF fte_item = NEW.ein_fte_id THEN
        RAISE EXCEPTION 'equivalencias_ins_negadas: negativa contra a propria fonte do insumo % (fte %)',
            NEW.ein_ins_id, NEW.ein_fte_id;
    END IF;
    IF EXISTS (SELECT 1 FROM catalogo.equivalencias_ins e
                WHERE e.ei_status = 'confirmado'
                  AND ((e.ei_ori_ins_id  = NEW.ein_ins_id AND e.ei_dest_fte_id = NEW.ein_fte_id)
                    OR (e.ei_dest_ins_id = NEW.ein_ins_id AND e.ei_ori_fte_id  = NEW.ein_fte_id))) THEN
        RAISE EXCEPTION 'equivalencias_ins_negadas: insumo % JA tem equivalente confirmado na fonte % - negado e confirmado sao mutuamente exclusivos',
            NEW.ein_ins_id, NEW.ein_fte_id;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_ein_guarda ON catalogo.equivalencias_ins_negadas;
CREATE TRIGGER t_ein_guarda BEFORE INSERT OR UPDATE ON catalogo.equivalencias_ins_negadas
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_eq_ins_negada_guarda();

CREATE OR REPLACE FUNCTION catalogo.trg_eq_cpu_negada_guarda() RETURNS trigger AS $$
DECLARE fte_item INTEGER;
BEGIN
    SELECT cmp_fte_id INTO fte_item FROM catalogo.composicoes WHERE cmp_id = NEW.ecn_cmp_id;
    IF fte_item = NEW.ecn_fte_id THEN
        RAISE EXCEPTION 'equivalencias_cpu_negadas: negativa contra a propria fonte da composicao % (fte %)',
            NEW.ecn_cmp_id, NEW.ecn_fte_id;
    END IF;
    IF EXISTS (SELECT 1 FROM catalogo.equivalencias_cpu e
                WHERE e.ec_status = 'confirmado'
                  AND ((e.ec_ori_cmp_id  = NEW.ecn_cmp_id AND e.ec_dest_fte_id = NEW.ecn_fte_id)
                    OR (e.ec_dest_cmp_id = NEW.ecn_cmp_id AND e.ec_ori_fte_id  = NEW.ecn_fte_id))) THEN
        RAISE EXCEPTION 'equivalencias_cpu_negadas: composicao % JA tem equivalente confirmado na fonte % - negado e confirmado sao mutuamente exclusivos',
            NEW.ecn_cmp_id, NEW.ecn_fte_id;
    END IF;
    RETURN NEW;
END; $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS t_ecn_guarda ON catalogo.equivalencias_cpu_negadas;
CREATE TRIGGER t_ecn_guarda BEFORE INSERT OR UPDATE ON catalogo.equivalencias_cpu_negadas
    FOR EACH ROW EXECUTE FUNCTION catalogo.trg_eq_cpu_negada_guarda();


-- ============================================================
-- TABELA: catalogo.equivalencias_subgrupos   (mapa de grupos — Ringue 2)
-- Contrato: docs/.../contracts/catalogo/vinculacoes.md §3.4.1
-- Mapa subgrupo-fonte → subgrupo(s) SINAPI (SINAPI só usa subgrupo → subgrupo×subgrupo).
-- Restringe o match de CPUs ao grupo análogo. Cardinalidade 1:1 / N:1 / N:N.
-- TODO subgrupo-fonte recebe alvo (mesmo casual — se não houver CPU a vincular, nada muda;
-- o resíduo vai pra IA). Seed IA em schemas/seeds/equivalencias_subgrupos_seed.sql.
-- Subgrupo NOVO no import → manifesto → GATE entre estágio 1/2 (sem associar não avança).
-- NOTA: renomear p/ equivalencias_subgrupos (padrão equivalencias_*) — pendência.
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.equivalencias_subgrupos (
    es_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    es_fonte_sub_id   INTEGER NOT NULL,   -- subgrupo da FONTE (composicoes_subgrupos.sub_id; a fonte vem do sub_fte_id)
    es_sinapi_sub_id  INTEGER,            -- subgrupo SINAPI (âncora); NULL = sem análogo
    es_status         TEXT NOT NULL DEFAULT 'pendente', -- pendente | confirmado
    es_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    es_atualizado_em  TIMESTAMPTZ,
    es_atualizado_por TEXT,
    -- 1 subgrupo-fonte → N destinos SINAPI (ex.: CDHU "bloco de concreto" = vedação E estrutural).
    -- NULLS NOT DISTINCT impede 2 linhas (fonte, NULL) duplicadas. N fonte→1 SINAPI também livre.
    CONSTRAINT uq_es UNIQUE NULLS NOT DISTINCT (es_fonte_sub_id, es_sinapi_sub_id),
    CONSTRAINT fk_es_fonte  FOREIGN KEY (es_fonte_sub_id)  REFERENCES catalogo.composicoes_subgrupos (sub_id) ON DELETE CASCADE,
    CONSTRAINT fk_es_sinapi FOREIGN KEY (es_sinapi_sub_id) REFERENCES catalogo.composicoes_subgrupos (sub_id) ON DELETE SET NULL
);
CREATE INDEX ix_es_sinapi ON catalogo.equivalencias_subgrupos (es_sinapi_sub_id);

