CREATE TABLE IF NOT EXISTS catalogo.indices_historico (
    idh_id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    idh_idc_codigo    TEXT NOT NULL REFERENCES catalogo.indices(idc_codigo),
    idh_mes_ref       DATE NOT NULL,             -- 1º dia do mês de referência
    idh_numero_indice NUMERIC(16,6),             -- nível acumulado (base do gráfico → rebaseia a 100)
    idh_variacao_pct  NUMERIC(10,4),             -- variação % no mês (opcional)
    idh_criado_em     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_indices_historico UNIQUE (idh_idc_codigo, idh_mes_ref)
);
CREATE INDEX IF NOT EXISTS ix_indices_historico_codigo_mes
    ON catalogo.indices_historico(idh_idc_codigo, idh_mes_ref);

-- ============================================================
-- TABELA: catalogo.search_document   (prefixo sd_)   — decisão Renan 2026-06-11
-- ÍNDICE DE BUSCA TEXTUAL (1×1 por entidade ATIVA: insumo ou composição/CPU).
-- Contrato canônico: docs/.../contracts/catalogo/listagem.md.
--
-- Doutrina: PostgreSQL é a FONTE DA VERDADE. Esta tabela é um ÍNDICE — duplica
-- só TEXTO PESQUISÁVEL + FACETAS de filtro; NUNCA preço, composição analítica,
-- coeficientes ou regra de negócio. A busca devolve CANDIDATOS (entity_type+id+
-- score); a app REIDRATA o dado oficial nas tabelas-fonte. Arquitetura preparada
-- p/ trocar o motor (Postgres→Elasticsearch/OpenSearch) mudando só o adapter —
-- o contrato (SearchService) e esta tabela não mudam.
--
-- Campos: sd_descricao_normalizada (unaccent+upper, p/ trigram), sd_texto_busca
-- (haystack: código+descrição+aliases), sd_search_vector (tsvector pt p/ full-text),
-- sd_aliases (sinônimos/curadoria; MVP vazio), sd_tokens (palavras normalizadas).
-- FACETAS: sd_fte_id, sd_tipo (ti_codigo p/ INS; NULL p/ CPU), sd_unidade,
-- sd_is_active. sd_source_hash detecta mudança (skip reindex / base do delta worker).
-- Mantida por SearchIndexer (rebuild/rebuild_all + upsert); reindex no CRUD e em
-- LOTE ao fim do import. (UF/preço NÃO entram aqui — são dimensão de exibição.)
-- ============================================================
CREATE TABLE IF NOT EXISTS catalogo.search_document (
    sd_id                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sd_entity_type           TEXT    NOT NULL,   -- 'INS' (insumo) | 'CPU' (composição)
    sd_entity_id             INTEGER NOT NULL,   -- ins_id | cmp_id (da linha vigente)
    sd_codigo                TEXT    NOT NULL,
    sd_descricao_original    TEXT    NOT NULL,
    sd_descricao_normalizada TEXT    NOT NULL,   -- upper(unaccent(descricao)) — p/ pg_trgm
    sd_texto_busca           TEXT    NOT NULL,   -- haystack: codigo + descricao + aliases
    sd_aliases               TEXT[]  NOT NULL DEFAULT '{}',  -- sinônimos/curadoria (MVP vazio)
    sd_tokens                TEXT[]  NOT NULL DEFAULT '{}',  -- palavras normalizadas
    sd_search_vector         TSVECTOR,            -- to_tsvector('portuguese', unaccent(texto_busca))
    -- facetas de filtro (denormalização barata — NÃO é regra de negócio):
    sd_fte_id                INTEGER,
    sd_tipo                  TEXT,                -- ti_codigo (INS); NULL p/ CPU
    sd_unidade               TEXT,
    sd_is_active             BOOLEAN NOT NULL DEFAULT TRUE,
    sd_source_hash           TEXT    NOT NULL,    -- md5 das fontes → detecta mudança
    sd_indexed_at            TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT ck_search_document_entity CHECK (sd_entity_type IN ('INS', 'CPU')),
    CONSTRAINT uq_search_document_entity UNIQUE (sd_entity_type, sd_entity_id)
);

CREATE INDEX IF NOT EXISTS ix_search_document_vector
    ON catalogo.search_document USING GIN (sd_search_vector);
CREATE INDEX IF NOT EXISTS ix_search_document_norm_trgm
    ON catalogo.search_document USING GIN (sd_descricao_normalizada catalogo.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_search_document_texto_trgm
    ON catalogo.search_document USING GIN (sd_texto_busca catalogo.gin_trgm_ops);
CREATE INDEX IF NOT EXISTS ix_search_document_facets
    ON catalogo.search_document (sd_entity_type, sd_fte_id, sd_tipo, sd_is_active);
CREATE INDEX IF NOT EXISTS ix_search_document_codigo
    ON catalogo.search_document (sd_codigo);


-- ============================================================
-- ROLE: easy_mobile_reader   (consumidor da Easy Mobile API)
-- Contrato: docs/projects/axys-easy/modules/easy-mobile/projeto.md §4
-- ============================================================
-- A Easy Mobile API é um SERVIÇO INDEPENDENTE que apenas COMPARTILHA CÓDIGO com o
-- Easy Web. Compartilhar código não pode significar compartilhar permissão: a
-- fronteira é o PROCESSO. Aquele processo recebe EASY_DB_URL apontando para este
-- role, e então TODA função de serviço reusada (get_cpu_precificada, SearchService,
-- get_historico_custos…) passa a conectar em modo leitura — sem alterar uma linha.
--
-- DECISÃO: sem camada de views. As funções reusadas têm `catalogo.*` escrito no SQL;
-- um schema de views obrigaria a forkar todas elas. O recorte de linha (edição
-- publicada, item ativo) já vive nas funções; o de coluna, no serializer da API.
--
-- SENHA: definida POR AMBIENTE, fora deste arquivo. Use o meta-comando do psql:
--     \password easy_mobile_reader
-- e NÃO `ALTER ROLE ... PASSWORD '…'`. O \password pergunta a senha, escapa sozinho e
-- não grava no histórico do terminal. O ALTER exige aspa RETA ('), e senha colada de
-- editor costuma vir com aspa curva (' '), que o Postgres rejeita — já aconteceu em prod
-- (21/08/2026). Role com LOGIN e sem senha não autentica: estado intermediário seguro.
-- ------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'easy_mobile_reader') THEN
        CREATE ROLE easy_mobile_reader LOGIN;
    END IF;
END $$;

-- Teto de conexões: é o que impede o app GRATUITO de consumir as conexões de que o
-- Easy Web (pago) precisa. O limite mora na role, não na boa vontade do código.
-- 20 de 103 (max_connections de prod, medido em 21/08/2026) = ~19% do banco. É TETO,
-- não reserva: só consome o que usar. Com pool de 5 por instância, cabem 4 instâncias
-- antes de encostar. Ajustar é ALTER ROLE — sem deploy, sem downtime.
ALTER ROLE easy_mobile_reader CONNECTION LIMIT 20;

-- Cinto de segurança: nem transação de escrita, nem query eterna, nem transação
-- pendurada segurando conexão.
ALTER ROLE easy_mobile_reader SET default_transaction_read_only = on;
ALTER ROLE easy_mobile_reader SET statement_timeout = '5s';
ALTER ROLE easy_mobile_reader SET idle_in_transaction_session_timeout = '10s';

-- CONNECT no banco. Sem isto, a role só entra porque HERDA o privilégio que o PUBLIC tem
-- por padrão — e revogar o PUBLIC é passo comum de endurecimento, que derrubaria o app
-- gratuito sem ninguém relacionar as duas coisas. A fronteira do serviço não pode depender
-- de um default que alguém pode fechar num dia de faxina. Nome do banco vem de
-- current_database() porque muda entre ambientes.
DO $$
BEGIN
    EXECUTE format('GRANT CONNECT ON DATABASE %I TO easy_mobile_reader',
                   current_database());
END $$;

-- USAGE no schema: necessário para RESOLVER NOMES — inclusive os das extensões, que
-- vivem aqui (catalogo.unaccent, catalogo.word_similarity, operador catalogo.<%).
-- Sem isto a busca elástica quebra. Conceder é seguro: USAGE não dá acesso a dado.
GRANT USAGE ON SCHEMA catalogo TO easy_mobile_reader;

-- Lista EXPLÍCITA. Nada de "ON ALL TABLES", e nenhum ALTER DEFAULT PRIVILEGES: assim
-- tabela nova nasce FORA do alcance do mobile, e incluí-la é ato consciente. O inverso
-- faria toda tabela futura vazar por omissão — a pior forma de vazar.
GRANT SELECT ON
    catalogo.fontes,
    catalogo.edicoes,
    catalogo.composicoes,
    catalogo.composicoes_custo,
    catalogo.composicoes_itens,      -- analítica SERVIDA (decisão 16/08/2026, §5.1)
    catalogo.composicoes_grupos,
    catalogo.composicoes_subgrupos,
    catalogo.composicoes_historico,
    catalogo.insumos,
    catalogo.insumos_tipo,
    catalogo.insumos_preco,
    catalogo.insumos_familia,
    catalogo.insumos_historico,
    catalogo.edicoes_leis_sociais,
    catalogo.search_document,
    catalogo.indices,
    catalogo.indices_historico,
    -- ── conversão de regime horista→mensalista (21/08/2026) ──
    -- CPRB e JORNADA_H_MES: constantes LEGAIS versionadas no tempo, públicas por
    -- natureza. Conceder não entrega nada da Axys.
    catalogo.parametros_normativos,
    -- EXCEÇÃO CONSCIENTE ao §5.1, que manteve a normalização fora do alcance: sem esta
    -- tabela não existe conversão de regime, e conversão é a função mais diferenciada
    -- do app. Decisão do dono do produto em 21/08/2026 — o mapeamento MO horista↔
    -- mensalista passa a ser legível pelo mobile. As DEMAIS tabelas de normalização
    -- (equivalencias_cpu, equivalencias_ins, equivalencias_subgrupos,
    -- insumos_equivalencias) CONTINUAM FORA.
    catalogo.composicoes_mapeamento_mdo
TO easy_mobile_reader;

-- FORA do alcance, deliberadamente — é aqui que mora o ativo da Axys. O coeficiente
-- já é público na origem (as fontes o publicam); o que é PRÓPRIO é a NORMALIZAÇÃO:
--   equivalencias_cpu · equivalencias_ins · equivalencias_subgrupos
--   insumos_equivalencias
-- (composicoes_mapeamento_mdo SAIU desta lista em 21/08/2026 — ver o GRANT acima)
-- E os schemas ativo, tenant_catalogo, audit e core NUNCA são concedidos: mesmo com a
-- API mobile inteiramente comprometida, não há caminho até orçamento de cliente pagante.


-- ============================================================
-- SCHEMA: audit
-- Trilha de auditoria. Append-only — sem UPDATE nem DELETE via app.
--
-- Tabelas ativas:
--   audit.logs_retencao     — políticas de retenção (lookup controlado
--                             pelo gestor tech — users não vêem)
--   audit.criterio_retencao — mapeamento (schema, tabela) → política
--   audit.logs              — histórico de alterações em dados
--   audit.login_logs        — eventos de autenticação e origem
--   audit.api_logs          — chamadas externas à API (writes only)
--
-- Limpeza periódica (dias 5/10/15/20/25 de cada mês, 02h00):
--
--   DELETE FROM audit.logs l
--   USING audit.criterio_retencao cr
--   JOIN  audit.logs_retencao lr ON cr.crit_ret_id = lr.ret_id
--   WHERE cr.crit_schema   = l.log_schema
--     AND cr.crit_tabela   = l.log_tabela
--     AND lr.ret_permanente = false
--     AND l.log_criado_em  < NOW() - (lr.ret_dias || ' days')::INTERVAL;
--
--   Tabelas SEM critério definido → NÃO deletadas (seguro por omissão).
--   Detectar tabelas não configuradas:
--     SELECT DISTINCT log_schema, log_tabela FROM audit.logs l
--     WHERE NOT EXISTS (
--         SELECT 1 FROM audit.criterio_retencao cr
--         WHERE cr.crit_schema = l.log_schema
--           AND cr.crit_tabela = l.log_tabela
--     );
--
-- ── Arquitetura futura: sanitização de dados de tenants ──────
--
-- Distinção importante: limpeza de logs ≠ sanitização de dados.
-- A sanitização afeta dados de negócio do tenant (futuro módulo
-- "ativo") de tenants que encerraram uso. Por isso, o worker deve
-- ser tratado em separado do cleanup de audit.logs.
--
-- Tabelas previstas (a implementar quando o módulo "ativo" estiver maduro):
--
--   audit.logs_retencao_by_tenant
--     id, tenant_id, tenant_role
--     → marca tenants que NÃO podem ter dados tocados,
--       independente do critério global de retenção.
--
--   audit.logs_table_arquivar_r2
--     id, schema, tabela
--     → cataloga quais tabelas devem ter seus dados exportados
--       para R2 como CSV antes da sanitização (fallback de controle).
--
-- Worker executar_limpeza() — três passagens:
--   1. retencao_criterios()    → avalia quais tabelas/registros limpar
--   2. retencao_by_tenant()    → exclui UUIDs de tenants protegidos
--   3. gerar_backup_tenants()  → exporta CSV para R2 os registros
--                                 que serão sanitizados
--   DELETE final apenas após o backup confirmado no R2.
--
-- Rationale: tenants de uso único geram orçamentos e não retornam.
-- O banco é sanitizado, mas o dado fica no R2 ad-aeternum como
-- fallback para reinsert controlado se necessário.
-- Tudo na app é auditável — este schema é o lugar canônico para
-- documentar essa intenção.
--
-- Decisões de design:
--   - Retenção determinada no momento da limpeza (não gravada por linha)
--     → política pode ser ajustada retroativamente sem perda silenciosa
--   - Sem FK para tabelas de negócio (sobrevive a soft/hard delete)
--   - audit.logs: full JSON em cadastros, diff parcial em alta frequência
--   - audit.api_logs: apenas writes (POST/PUT/DELETE); GETs ignorados
--   - audit.login_logs: campo origem prevê OAuth futuro (gov.br, Apple…)
-- ============================================================

CREATE SCHEMA IF NOT EXISTS audit;

GRANT USAGE ON SCHEMA audit TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA audit
    GRANT SELECT, INSERT ON TABLES TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA audit
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";


-- ------------------------------------------------------------
-- audit.logs_retencao — políticas de retenção (lookup)
-- Seed inline logo abaixo (todos os seeds vivem no schema).
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit.logs_retencao (
    ret_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ret_descricao   TEXT    NOT NULL,
    ret_permanente  BOOLEAN NOT NULL DEFAULT false,
    ret_dias        INTEGER NULL,

    CONSTRAINT ck_retencao_permanencia CHECK (
        (ret_permanente = true  AND ret_dias IS NULL)
        OR
        (ret_permanente = false AND ret_dias IS NOT NULL AND ret_dias > 0)
    )
);

-- Seed inline — políticas de retenção.
INSERT INTO audit.logs_retencao (ret_descricao, ret_permanente, ret_dias) VALUES
    ('Permanente', true,  NULL),
    ('90 dias',    false,   90),
    ('180 dias',   false,  180),
    ('1 ano',      false,  365),
    ('2 anos',     false,  730),
    ('5 anos',     false, 1825)
ON CONFLICT DO NOTHING;


-- ------------------------------------------------------------
-- audit.criterio_retencao — mapeamento (schema, tabela) → política
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit.criterio_retencao (
    crit_id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    crit_schema   TEXT    NOT NULL,
    crit_tabela   TEXT    NOT NULL,
    crit_ret_id   INTEGER NOT NULL,

    CONSTRAINT fk_criterio_retencao
        FOREIGN KEY (crit_ret_id)
        REFERENCES audit.logs_retencao (ret_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,

    CONSTRAINT uq_criterio_schema_tabela
        UNIQUE (crit_schema, crit_tabela)
);

CREATE INDEX ix_criterio_schema_tabela
    ON audit.criterio_retencao (crit_schema, crit_tabela);

-- Seed inline — catálogo histórico é tudo permanente. Depende do seed de
-- audit.logs_retencao acima.
INSERT INTO audit.criterio_retencao (crit_schema, crit_tabela, crit_ret_id)
SELECT v.sch, v.tab, lr.ret_id
FROM (VALUES
    ('catalogo', 'fontes'),
    ('catalogo', 'insumos_tipo'),
    ('catalogo', 'edicoes'),
    ('catalogo', 'edicoes_leis_sociais'),
    ('catalogo', 'composicoes_grupos'),
    ('catalogo', 'composicoes_subgrupos'),
    ('catalogo', 'insumos'),
    ('catalogo', 'insumos_preco'),
    ('catalogo', 'insumos_familia'),
    ('catalogo', 'composicoes'),
    ('catalogo', 'composicoes_itens'),
    ('catalogo', 'composicoes_custo'),
    ('catalogo', 'composicoes_mapeamento_mdo'),
    ('catalogo', 'sinapi_manutencoes')
) AS v(sch, tab)
CROSS JOIN audit.logs_retencao lr
WHERE lr.ret_descricao = 'Permanente'
ON CONFLICT (crit_schema, crit_tabela) DO NOTHING;


-- ------------------------------------------------------------
-- audit.logs — histórico de alterações em dados
-- Retenção determinada por audit.criterio_retencao no cleanup job.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit.logs (
    log_id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    -- O quê
    log_schema       TEXT          NOT NULL,
    log_tabela       TEXT          NOT NULL,
    log_registro_id  TEXT          NOT NULL,
    log_acao         TEXT          NOT NULL
                     CHECK (log_acao IN ('INSERT', 'UPDATE', 'DELETE')),

    -- Quem / quando
    log_usuario      TEXT          NOT NULL,
    log_ip           TEXT,

    -- Como estava / como ficou
    log_dados_antes  JSONB,
    log_dados_depois JSONB,

    log_criado_em    TIMESTAMPTZ   NOT NULL DEFAULT NOW()
);

CREATE INDEX ix_audit_logs_registro
    ON audit.logs (log_tabela, log_registro_id);
CREATE INDEX ix_audit_logs_usuario
    ON audit.logs (log_usuario);
CREATE INDEX ix_audit_logs_criado_em
    ON audit.logs (log_criado_em DESC);


-- ------------------------------------------------------------
-- audit.login_logs — eventos de autenticação e origem
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit.login_logs (
    log_id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    log_user_id     TEXT,
    log_email       TEXT,
    log_nome        TEXT,
    log_tenant_id   TEXT,

    log_acao        TEXT         NOT NULL
                    CHECK (log_acao IN ('LOGIN', 'LOGOUT', 'LOGIN_FALHA')),

    log_origem      TEXT         NOT NULL DEFAULT 'LOCAL'
                    CHECK (log_origem IN (
                        'LOCAL',
                        'SSO',
                        'GOV_BR',
                        'APPLE',
                        'GOOGLE',
                        'API_KEY'
                    )),

    log_ip          TEXT,
    log_user_agent  TEXT,
    log_detalhes    JSONB,

    log_criado_em   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX ix_audit_login_email
    ON audit.login_logs (log_email);
CREATE INDEX ix_audit_login_user_id
    ON audit.login_logs (log_user_id)
    WHERE log_user_id IS NOT NULL;
CREATE INDEX ix_audit_login_criado_em
    ON audit.login_logs (log_criado_em DESC);


-- ------------------------------------------------------------
-- audit.api_logs — chamadas externas à API (writes only)
-- Registra POST/PUT/PATCH/DELETE; GETs ignorados.
-- audit.api_logs captura o contexto HTTP; audit.logs captura o dado.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS audit.api_logs (
    log_id          BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    log_method      TEXT         NOT NULL
                    CHECK (log_method IN ('POST', 'PUT', 'PATCH', 'DELETE')),
    log_endpoint    TEXT         NOT NULL,
    log_status      SMALLINT     NOT NULL,

    log_cliente     TEXT,
    log_usuario     TEXT,
    log_ip          TEXT,

    log_corpo_req   JSONB,
    log_duracao_ms  INTEGER,

    log_criado_em   TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX ix_audit_api_endpoint
    ON audit.api_logs (log_endpoint, log_criado_em DESC);
CREATE INDEX ix_audit_api_cliente
    ON audit.api_logs (log_cliente)
    WHERE log_cliente IS NOT NULL;
CREATE INDEX ix_audit_api_criado_em
    ON audit.api_logs (log_criado_em DESC);


-- ------------------------------------------------------------
-- audit.uso_isolado — consumo dos produtos de USO ISOLADO (Price e CPU)
-- ------------------------------------------------------------
-- Price e CPU não são capacidade: são uso isolado, com SALDO CANÔNICO NO HUB. Cada consumo é
-- deliberado, transacional, auditável e IDEMPOTENTE. Esta tabela é a ponta do Easy: grava o evento
-- localmente ANTES de chamar o Hub, e `backend/core/licensing.py` a usa como OUTBOX — o retry
-- repete a mesma `uso_chave_idem` e nunca duplica o débito lá.
-- Contrato: `contracts/axys_easy_modelo_licenciamento.md` §11.
--
-- Nasceu como `audit.license_usage_event`, criada direto nos dois bancos pelo time do Hub, com
-- nomes em inglês e sem prefixo. Renomeada para a convenção da casa em 06/10, enquanto a tabela
-- ainda estava vazia e sem leitor — depois do primeiro evento gravado sairia caro.
--
-- `uso_sync` é o estado da SINCRONIZAÇÃO com o Hub, não do negócio: PENDENTE → CONFIRMADO | FALHOU.
CREATE TABLE IF NOT EXISTS audit.uso_isolado (
    uso_id            UUID        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,

    uso_tenant_uuid   UUID        NOT NULL,
    uso_usuario_uuid  UUID,                                  -- quem disparou; nulo em evento de sistema
    uso_produto       TEXT        NOT NULL,                  -- PRI | CPU (só uso isolado passa aqui)
    uso_recurso       TEXT        NOT NULL,                  -- unidade de trabalho consumida
    uso_evento        TEXT        NOT NULL,
    uso_qtd           INTEGER     NOT NULL DEFAULT 1,

    -- a chave da idempotência: o retry reusa, e o UNIQUE abaixo torna o segundo envio um UPDATE
    uso_chave_idem    TEXT        NOT NULL,

    uso_sync          TEXT        NOT NULL DEFAULT 'PENDENTE',
    uso_saldo_antes   BIGINT,
    uso_saldo_depois  BIGINT,
    uso_meta_json     JSONB       NOT NULL DEFAULT '{}'::jsonb,
    uso_erro          TEXT,

    uso_criado_em     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    uso_confirmado_em TIMESTAMPTZ,
    uso_atualizado_em TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_uso_idem UNIQUE (uso_tenant_uuid, uso_produto, uso_chave_idem),
    CONSTRAINT ck_uso_qtd  CHECK (uso_qtd > 0),
    CONSTRAINT ck_uso_sync CHECK (uso_sync IN ('PENDENTE', 'CONFIRMADO', 'FALHOU')),
    CONSTRAINT ck_uso_meta CHECK (jsonb_typeof(uso_meta_json) = 'object'),
    -- data de confirmação e estado não podem discordar
    CONSTRAINT ck_uso_confirmado
        CHECK ((uso_sync = 'CONFIRMADO') = (uso_confirmado_em IS NOT NULL))
);

-- Índice PARCIAL: quem varre esta tabela é o reprocessamento, e ele só quer o que não fechou.
CREATE INDEX IF NOT EXISTS ix_uso_pendente
    ON audit.uso_isolado (uso_atualizado_em)
    WHERE uso_sync IN ('PENDENTE', 'FALHOU');




-- ============================================================
-- SCHEMA: core  (infra transversal da app — não é domínio)
-- ============================================================
-- Casa de tabelas de plumbing que não pertencem a catalogo/ativo:
-- hoje, o registro durável de JOBS assíncronos (Celery).
-- Decisão: ADR-006 (docs/.../adrs/EASY-ADR-006-arquitetura-de-jobs-e-escala.md).
-- ============================================================
CREATE SCHEMA IF NOT EXISTS core;

GRANT USAGE ON SCHEMA core TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA core
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA core
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";

-- ------------------------------------------------------------
-- core.jobs — registro durável de jobs assíncronos (ADR-006 §3.4)
-- ------------------------------------------------------------
-- A VERDADE do status de um job (o AsyncResult do Redis expira em 24h e não é
-- consultável por tenant). Também é a fila lógica do ingest→process: linhas
-- 'pendente'/'agendado' aguardam o disparo ("processar agora" do admin).
--
-- ESTADO é MUTÁVEL (pendente→rodando→ok/erro) — por isso fica em `core`, não em
-- `audit` (que é trilha append-only). A auditoria de quem disparou continua em
-- audit.logs; aqui guardamos a execução.
--
-- TENANCY: job_tenant_uuid é a RAIZ de isolamento, NULLABLE — jobs de sistema/admin
-- (import de fonte-base) NÃO têm tenant; jobs de cliente (módulo ativo) SEMPRE têm.
-- RLS: ATIVA já neste subir (decisão 2026-06-18 — exceção ao deferral do resto do repo;
-- o custo da coluna+policy é baixo e preferimos subir isolado). Ver ADR-006 §3.5.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS core.jobs (
    job_id            INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,  -- INT basta: jobs são purgáveis (sanitização periódica) e o volume de inserts/vida não chega perto de 2,1 bi

    -- Identidade de execução
    job_task_id       TEXT,                              -- id da task Celery (AsyncResult); NULL enquanto só 'pendente'/'agendado'
    job_tenant_uuid   UUID,                              -- RAIZ de isolamento; NULL = job de sistema/admin (sem tenant). [VALIDAR] sem FK física (hub é banco externo).

    -- O quê / pra onde
    job_tipo          TEXT          NOT NULL,            -- ex.: 'importar_sinapi' | 'importar_cdhu' | 'gerar_caderno' | 'conversao_cliente' (conjunto aberto — sem CHECK p/ não acoplar)
    job_fila          TEXT          NOT NULL             -- classe de carga / roteamento (ADR-006 §3.1)
                      CHECK (job_fila IN ('imports', 'clients', 'maint')),
    job_prioridade    SMALLINT      NOT NULL DEFAULT 0,  -- ordenação OPCIONAL dentro da fila 'clients' (maior = antes); não preempta — ver ADR-006 §3.1

    -- Máquina de estados
    job_estado        TEXT          NOT NULL DEFAULT 'pendente'
                      CHECK (job_estado IN ('pendente', 'agendado', 'rodando', 'ok', 'erro', 'cancelado')),

    -- Dados (entrada / progresso / saída)
    job_payload       JSONB,                             -- args do enfileiramento (fte_id, edi_id, arquivos…)
    job_progresso     JSONB,                             -- stages/percentual em andamento (espelha o stage() do import)
    job_resultado     JSONB,                             -- retorno em sucesso (url do caderno, contagens…)
    job_erro          TEXT,                              -- mensagem em falha

    -- Quem / quando
    job_usuario       TEXT,                              -- quem disparou (mesmo rótulo do audit)
    job_agendado_para TIMESTAMPTZ,                       -- ingest→process: quando processar; NULL = assim que possível
    job_criado_em     TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    job_iniciado_em   TIMESTAMPTZ,
    job_terminado_em  TIMESTAMPTZ
);

-- drainer/painel: pega o próximo a rodar por fila (pendentes/agendados vencidos)
CREATE INDEX ix_core_jobs_fila_estado
    ON core.jobs (job_fila, job_estado, job_prioridade DESC, job_agendado_para);
-- histórico por tenant (área do cliente)
CREATE INDEX ix_core_jobs_tenant
    ON core.jobs (job_tenant_uuid, job_criado_em DESC)
    WHERE job_tenant_uuid IS NOT NULL;
-- lookup pelo id da task Celery (status em tempo real)
CREATE UNIQUE INDEX ix_core_jobs_task
    ON core.jobs (job_task_id)
    WHERE job_task_id IS NOT NULL;
CREATE INDEX ix_core_jobs_criado_em
    ON core.jobs (job_criado_em DESC);

-- ── RLS (ATIVA) — isolamento por tenant em core.jobs ──
-- Contrato de contexto de sessão (a app SETa por request/task):
--   • servidor/admin (workers, ingest, painel staff): SET app.is_internal = 'on'
--       → acesso total, inclui jobs de sistema sem tenant (ex.: import de fonte-base).
--   • área do cliente: SET app.current_tenant = '<uuid>' (sem is_internal)
--       → enxerga/escreve só os próprios jobs.
--   • nada setado → NEGA tudo (default-deny): contexto esquecido não vaza.
-- FORCE: o dono (axys_tec, não-superuser) também obedece — sem FORCE o owner ignora RLS.
ALTER TABLE core.jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.jobs FORCE  ROW LEVEL SECURITY;

DROP POLICY IF EXISTS jobs_acesso ON core.jobs;   -- idempotente (CREATE POLICY não tem IF NOT EXISTS)
CREATE POLICY jobs_acesso ON core.jobs
    USING (
        current_setting('app.is_internal', true) = 'on'
        OR job_tenant_uuid = NULLIF(current_setting('app.current_tenant', true), '')::uuid
    )
    WITH CHECK (
        current_setting('app.is_internal', true) = 'on'
        OR job_tenant_uuid = NULLIF(current_setting('app.current_tenant', true), '')::uuid
    );




-- ############################################################
-- ############################################################
-- MÓDULO ATIVO (+ tenant_catalogo + arquivo)
-- ############################################################
-- Origem: docs/projects/axys-easy/schemas/proposta_ativo.sql — proposta validada
--   (parse formal OK; revisada contra DDM JALES.xlsm e axysCAD_contract.md) e
--   PROMOVIDA para o schema.sql (foto do banco em dev) em 2026-06-14.
-- Contratos canônicos: docs/projects/axys-easy/contracts/ativo/ (arquitetural v0.2
--   + decisões 2026-06-14: árvore única/is_catalog_source, drivers, BDI/LS,
--   cronograma, diversidades, memo MANUAL|plugin) e EASY_HUB_ARQUIVAMENTO.md.
-- RLS: políticas ADIADAS (colunas tenant_uuid já presentes; habilitar quando liberar tenants).
-- ############################################################

-- ============================================================
-- SCHEMA: tenant_catalogo  (biblioteca técnica própria do tenant)
-- Contrato/proposta: docs/projects/axys-easy/contracts/catalogo/TENANT_CATALOGO_PROPOSTA.md (validado 2026-08-17).
-- Espelha a FORMA do catalogo, ENXUTO e isolado por tenant_uuid (raiz). 7 tabelas:
--   fontes · edicoes · insumos · insumos_preco · composicoes · composicoes_itens · composicoes_custo.
-- SEM: CTC, path/R2, grupos/subgrupos, BDI, conferência, encargos itemizados, cadernos, equivalências,
--      tabela de histórico/auditoria. Único histórico = série de PREÇO por edição.
-- FK física SÓ p/ o lookup GLOBAL catalogo.insumos_tipo. Unidade = texto livre (sem FK unidades).
-- UF vive no INSUMO (ins_uf); preço por (insumo, edição). L.S. mínima só p/ MO (edicoes.edi_ls_horista,
--   trunc SINAPI). Composição UF-agnóstica: aceita filho de qualquer UF; custo SEMPRE calculado (Σ) e
--   armazenado (cache) — 1 por (cmp, edição). Filho GLOBAL precificado por composicoes_itens.ci_uf.
-- Import por (fonte, edição, UF) é IDEMPOTENTE (put/update = delete+insert do escopo).
-- RLS: colunas *_tenant_uuid já presentes; políticas ADIADAS (habilitar ao liberar tenants).
-- ============================================================
CREATE SCHEMA IF NOT EXISTS tenant_catalogo;

GRANT USAGE ON SCHEMA tenant_catalogo TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA tenant_catalogo
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA tenant_catalogo
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";

-- ── 1) FONTES próprias/externas do tenant ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.fontes (
    fte_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fte_tenant_uuid    UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física.
    fte_codigo         TEXT    NOT NULL,
    fte_nome           TEXT    NOT NULL,
    fte_tipo           TEXT    NOT NULL DEFAULT 'PROPRIA', -- PROPRIA | EXTERNA
    -- O BUCKET canônico do tenant: onde o "derivar" deposita a composição adaptada. Marcador do
    -- SISTEMA, não editável — a identidade é o ID da linha, e nada que o usuário possa mudar.
    -- Antes isto era inferido do `fte_codigo` ("PROPRIA"), que é RÓTULO EDITÁVEL: a fonte criada
    -- pela UI nascia "PRÓPRIA" (com acento), o bootstrap procurava sem, não achava, criava uma
    -- SEGUNDA, e a composição derivada ia para um bucket que o usuário não enxerga (01/09/2026).
    -- Tipo também não serve: um tenant pode ter várias fontes do tipo PROPRIA legitimamente.
    fte_bootstrap      BOOLEAN NOT NULL DEFAULT FALSE,
    fte_ativa          BOOLEAN NOT NULL DEFAULT TRUE,
    fte_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fte_atualizado_em  TIMESTAMPTZ,
    fte_criado_por     TEXT,
    fte_atualizado_por TEXT,

    CONSTRAINT uq_tcf_tenant_codigo UNIQUE (fte_tenant_uuid, fte_codigo),
    CONSTRAINT ck_tcf_tipo   CHECK (fte_tipo IN ('PROPRIA', 'EXTERNA')),
    CONSTRAINT ck_tcf_codigo CHECK (btrim(fte_codigo) <> '')
);

CREATE INDEX ix_tcf_tenant ON tenant_catalogo.fontes (fte_tenant_uuid, fte_ativa);
-- UM bucket por tenant, garantido pelo banco: parcial, porque só a linha marcada participa.
CREATE UNIQUE INDEX uq_tcf_bootstrap ON tenant_catalogo.fontes (fte_tenant_uuid) WHERE fte_bootstrap;

-- ── 2) EDIÇÕES da fonte (sem UF padrão, sem pipeline; L.S. da edição p/ MO) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.edicoes (
    edi_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    edi_tenant_uuid    UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física.
    edi_fte_id         INTEGER NOT NULL,
    edi_referencia     DATE    NOT NULL,                  -- data efetiva da tabela de preços
    edi_codigo_versao  TEXT,                              -- número/rótulo livre ("184", "Tabela Jan/26")
    edi_ls_horista_sd  NUMERIC(8,4),                      -- L.S. horista MO — SD (sem desoneração/onerado); NULL = pelado
    edi_ls_horista_cd  NUMERIC(8,4),                      -- L.S. horista MO — CD (com desoneração/desonerado); NULL = pelado
    edi_ativa          BOOLEAN NOT NULL DEFAULT TRUE,     -- estado ativo/inativo (soft-delete; SEM rascunho/publicada)
    edi_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    edi_atualizado_em  TIMESTAMPTZ,
    edi_criado_por     TEXT,
    edi_atualizado_por TEXT,

    CONSTRAINT fk_tce_fte
        FOREIGN KEY (edi_fte_id)
        REFERENCES tenant_catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_tce_fte_ref UNIQUE (edi_fte_id, edi_referencia)
);

CREATE INDEX ix_tce_fte ON tenant_catalogo.edicoes (edi_fte_id, edi_referencia DESC);

-- ── 3) INSUMOS do tenant (UF vive aqui; ti_id → lookup GLOBAL; ins_ativo p/ soft-delete) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.insumos (
    ins_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ins_tenant_uuid    UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física.
    ins_fte_id         INTEGER NOT NULL,
    ins_ti_id          INTEGER NOT NULL,                  -- classificação (MO/MAT/EQ…) — FK ao lookup GLOBAL
    ins_codigo         TEXT    NOT NULL,
    ins_descricao      TEXT    NOT NULL,
    ins_unidade        TEXT    NOT NULL,                  -- texto livre (sem FK unidades)
    ins_uf             CHAR(2) NOT NULL DEFAULT 'SP',     -- UF do insumo (o preço herda daqui)
    ins_ativo          BOOLEAN NOT NULL DEFAULT TRUE,     -- estado ativo/inativo (soft-delete guardado por dependentes)
    ins_busca          TEXT,                              -- normalizado p/ busca (trigger set_busca): upper(unaccent(código||' '||descrição))
    ins_seq            INTEGER,
    -- Sequencial do CÓDIGO AUTOMÁTICO, por TENANT (não por fonte): I-000001 / C-000001.
    -- NULLABLE de propósito -- nulo = código digitado à mão pelo usuário, que a app permite.
    -- Editar um código que veio daqui ZERA esta coluna: a posição VAGA, e nunca é reaproveitada
    -- (sempre o último + 1). Vagar libera o número para quem quiser digitá-lo, não para a app
    -- reciclar -- reciclar faria dois itens carregarem o mesmo código ao longo do tempo, em
    -- documentos já emitidos.
    ins_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ins_atualizado_em  TIMESTAMPTZ,
    ins_criado_por     TEXT,
    ins_atualizado_por TEXT,

    CONSTRAINT fk_tci_fte
        FOREIGN KEY (ins_fte_id)
        REFERENCES tenant_catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_tci_ti
        FOREIGN KEY (ins_ti_id)
        REFERENCES catalogo.insumos_tipo (ti_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_tci_fte_codigo_uf UNIQUE (ins_fte_id, ins_codigo, ins_uf),
    CONSTRAINT uq_tci_tenant_seq     UNIQUE (ins_tenant_uuid, ins_seq),
    CONSTRAINT ck_tci_codigo CHECK (btrim(ins_codigo) <> '')
);

CREATE INDEX ix_tci_tenant ON tenant_catalogo.insumos (ins_tenant_uuid, ins_codigo);
CREATE INDEX ix_tci_busca_trgm ON tenant_catalogo.insumos USING GIN (ins_busca catalogo.gin_trgm_ops);

-- ── 4) PREÇO do insumo (UF herda do insumo; MO = pelado; cotação inline em JSONB) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.insumos_preco (
    pri_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pri_ins_id         INTEGER NOT NULL,
    pri_edi_id         INTEGER NOT NULL,
    pri_valor          NUMERIC(14,2),                     -- MO = Sem Encargos (SE); demais = valor final. 2 casas (padrão ativo)
    pri_situacao       TEXT,                              -- 'COM PREÇO' | 'SEM PREÇO' (null = sem preço)
    pri_origem         TEXT,                              -- PROPRIA | PESQUISA | COTACAO | IMPORT
    -- pri_cotacoes: {preco_informado: bool, metodo: MENOR|MEDIA|MEDIANA|MIN_MED_MEDIANA,
    --   itens: [{empresa,site,telefone,email,responsavel,data,valor,aplicada,path}]}  (máx 5 itens)
    --   preco_informado=true → pri_valor é digitado (cotações só consulta); false → pri_valor = método(itens aplicadas)
    --   path = chave R2 privado da proposta (null = sem documento). Estatística (CV/saneada) é derivada, não persiste.
    pri_cotacoes       JSONB,
    pri_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pri_atualizado_em  TIMESTAMPTZ,
    pri_criado_por     TEXT,
    pri_atualizado_por TEXT,

    CONSTRAINT fk_tcp_ins
        FOREIGN KEY (pri_ins_id)
        REFERENCES tenant_catalogo.insumos (ins_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_tcp_edi
        FOREIGN KEY (pri_edi_id)
        REFERENCES tenant_catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_tcp UNIQUE (pri_ins_id, pri_edi_id),    -- grão: (insumo, edição) — UF vem do insumo
    CONSTRAINT ck_tcp_situacao
        CHECK (pri_situacao IS NULL OR pri_situacao IN ('COM PREÇO', 'SEM PREÇO'))
);

CREATE INDEX ix_tcp_ins_edi ON tenant_catalogo.insumos_preco (pri_ins_id, pri_edi_id);

-- ── 5) COMPOSIÇÕES do tenant (cmp_ativa p/ soft-delete) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.composicoes (
    cmp_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cmp_tenant_uuid    UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física.
    cmp_fte_id         INTEGER NOT NULL,
    cmp_codigo         TEXT    NOT NULL,
    cmp_descricao      TEXT    NOT NULL,
    cmp_unidade        TEXT    NOT NULL,
    cmp_ativa          BOOLEAN NOT NULL DEFAULT TRUE,     -- estado ativo/inativo (soft-delete guardado por dependentes)
    cmp_justificativa  TEXT,                              -- memorial da montagem (adequação orçamentária / derivada de…)
    -- DESCRITIVO (forma de medição + o que remunera). MESMA FORMA de catalogo.composicoes.cmp_descritivo,
    -- de propósito: {modo, versoes:[{desde_edi, req_hash, status, medicao, remunera, origem}]}, versoes[-1]
    -- = atual. Espelhar a estrutura do catálogo faz o MESMO leitor servir aos dois — caderno de encargos,
    -- export, tela e, no dia em que houver, o CTC Fill escrevendo para o tenant. Campos que o tenant não
    -- usa (req_hash, desde_edi) ficam nulos e custam zero.
    -- SEM ISTO a composição própria entrava no caderno de encargos sem forma de medição e sem remuneração,
    -- e o usuário não tinha onde preencher (o caderno só resolvia CTC para o CATÁLOGO).
    cmp_descritivo     JSONB,
    cmp_busca          TEXT,                              -- normalizado p/ busca (trigger set_busca)
    cmp_seq            INTEGER,
    -- Sequencial do CÓDIGO AUTOMÁTICO, por TENANT (não por fonte): C-000001.
    -- NULLABLE de propósito -- nulo = código digitado à mão pelo usuário, que a app permite.
    -- Editar um código que veio daqui ZERA esta coluna: a posição VAGA, e nunca é reaproveitada
    -- (sempre o último + 1). Vagar libera o número para quem quiser digitá-lo, não para a app
    -- reciclar -- reciclar faria dois itens carregarem o mesmo código ao longo do tempo, em
    -- documentos já emitidos.
    cmp_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cmp_atualizado_em  TIMESTAMPTZ,
    cmp_criado_por     TEXT,
    cmp_atualizado_por TEXT,

    CONSTRAINT fk_tcc_fte
        FOREIGN KEY (cmp_fte_id)
        REFERENCES tenant_catalogo.fontes (fte_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_tcc_fte_codigo UNIQUE (cmp_fte_id, cmp_codigo),
    CONSTRAINT uq_tcc_tenant_seq UNIQUE (cmp_tenant_uuid, cmp_seq),
    CONSTRAINT ck_tcc_codigo CHECK (btrim(cmp_codigo) <> '')
);

CREATE INDEX ix_tcc_tenant ON tenant_catalogo.composicoes (cmp_tenant_uuid, cmp_codigo);
CREATE INDEX ix_tcc_busca_trgm ON tenant_catalogo.composicoes USING GIN (cmp_busca catalogo.gin_trgm_ops);

-- ── 6) ITENS da composição (ref polimórfica a.3: global OU tenant, insumo OU composição) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.composicoes_itens (
    ci_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ci_cmp_id          INTEGER NOT NULL,                  -- composição-mãe (sempre do tenant)
    ci_ref_origem      TEXT    NOT NULL,                  -- 'CATALOGO' | 'TENANT' (onde vive o filho)
    ci_ref_tipo        TEXT    NOT NULL,                  -- 'INSUMO' | 'COMPOSICAO' (o que é o filho)
    ci_ref_id          INTEGER NOT NULL,                  -- id na origem+tipo (FK polimórfica via app)
    ci_coeficiente     NUMERIC(14,10) NOT NULL,
    ci_edi_id          INTEGER,                           -- edição do filho p/ preço (polimórfica por ci_ref_origem: catalogo|tenant)
    ci_uf              CHAR(2),                           -- UF só p/ precificar filho GLOBAL (tenant herda de ins_uf)
    ci_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ci_atualizado_em   TIMESTAMPTZ,
    ci_criado_por      TEXT,
    ci_atualizado_por  TEXT,

    CONSTRAINT fk_tcci_cmp
        FOREIGN KEY (ci_cmp_id)
        REFERENCES tenant_catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_tcci_ref_origem CHECK (ci_ref_origem IN ('CATALOGO', 'TENANT')),
    CONSTRAINT ck_tcci_ref_tipo   CHECK (ci_ref_tipo IN ('INSUMO', 'COMPOSICAO'))
);

CREATE INDEX ix_tcci_cmp ON tenant_catalogo.composicoes_itens (ci_cmp_id);

-- ── 7) CUSTO da composição (cache; SEMPRE calculado; UF-agnóstico → 1 por (cmp, edição)) ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.composicoes_custo (
    cc_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cc_cmp_id          INTEGER NOT NULL,
    cc_edi_id          INTEGER NOT NULL,
    cc_custo_sd        NUMERIC(14,2),                     -- custo COM encargos SD (por regime)
    cc_custo_cd        NUMERIC(14,2),                     -- custo COM encargos CD (por regime)
    cc_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cc_atualizado_em   TIMESTAMPTZ,
    cc_criado_por      TEXT,
    cc_atualizado_por  TEXT,

    CONSTRAINT fk_tccu_cmp
        FOREIGN KEY (cc_cmp_id)
        REFERENCES tenant_catalogo.composicoes (cmp_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_tccu_edi
        FOREIGN KEY (cc_edi_id)
        REFERENCES tenant_catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_tccu UNIQUE (cc_cmp_id, cc_edi_id)
);

CREATE INDEX ix_tccu_cmp_edi ON tenant_catalogo.composicoes_custo (cc_cmp_id, cc_edi_id);

-- ── 8) UNIDADES próprias do tenant (código + descrição). Dropdown = catalogo.unidades ∪ estas.
--    insumos/composições guardam o CÓDIGO (texto livre); a descrição importa no descritivo do orçamento.
--    Mínima (sem ativo): vocabulário get-or-create; não orfaniza (código fica no insumo). ──
CREATE TABLE IF NOT EXISTS tenant_catalogo.unidades (
    un_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    un_tenant_uuid    UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física.
    un_codigo         TEXT    NOT NULL,                  -- VG, M3XKM…
    un_descricao      TEXT,                              -- importa no descritivo do orçamento
    un_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    un_atualizado_em  TIMESTAMPTZ,
    un_criado_por     TEXT,
    un_atualizado_por TEXT,

    CONSTRAINT uq_tcu_tenant_codigo UNIQUE (un_tenant_uuid, un_codigo),
    CONSTRAINT ck_tcu_codigo CHECK (btrim(un_codigo) <> '')
);

CREATE INDEX ix_tcu_tenant ON tenant_catalogo.unidades (un_tenant_uuid, un_codigo);


-- ══════════════════════════════════════════════════════════════════════════════
-- CONSELHO DE CLASSE e DOCUMENTO DE RESPONSABILIDADE TÉCNICA
-- Domínio da Axys, igual para todo tenant — por isso em `catalogo`, não em tenant_catalogo.
-- Semeado aqui (get-or-create por código), como os índices: é lista fechada e pequena.
-- ══════════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS catalogo.conselhos_classe (
    ccl_codigo TEXT PRIMARY KEY,                  -- CREA, CAU, CRT
    ccl_nome   TEXT    NOT NULL,         -- ordem de exibição na listbox
);

INSERT INTO catalogo.conselhos_classe (ccl_codigo, ccl_nome) VALUES
    ('CREA', 'CONSELHO REGIONAL DE ENGENHARIA E AGRONOMIA'),
    ('CAU',  'CONSELHO DE ARQUITETURA E URBANISMO'),
    ('CRT',  'CONSELHO REGIONAL DOS TÉCNICOS INDUSTRIAIS')
ON CONFLICT (ccl_codigo) DO NOTHING;   -- PK natural (não IDENTITY) → não queima sequence

CREATE TABLE IF NOT EXISTS catalogo.profissoes (
    prf_codigo   TEXT PRIMARY KEY,                -- ENG_CIVIL, ARQ_URB, TEC_EDIF…
    prf_nome     TEXT NOT NULL,                   -- como vai no bloco de assinatura
    prf_conselho TEXT NOT NULL REFERENCES catalogo.conselhos_classe (ccl_codigo),
    -- SUPERIOR × MEDIO explícito: "Tecnólogo em Edificações" (superior, CREA) e "Técnico em
    -- Edificações" (médio, CRT) são profissões distintas e o prefixo sozinho não deixa isso
    -- consultável. A tela agrupa a listbox por nível.
    prf_nivel    TEXT NOT NULL DEFAULT 'SUPERIOR',
    prf_ativa    BOOLEAN NOT NULL DEFAULT TRUE,   -- some da listbox sem sumir de quem já a usa

    CONSTRAINT uq_prf_conselho_nome UNIQUE (prf_conselho, prf_nome),
    CONSTRAINT ck_prf_nivel CHECK (prf_nivel IN ('SUPERIOR', 'MEDIO'))
);

-- Recorte: construção civil e infraestrutura. NÃO é a lista completa dos conselhos — é a fatia
-- que aparece em projeto e obra. Quem define atribuição é o conselho (Res. CONFEA 218/1973 e
-- sucessoras, Lei 12.378/2010 para o CAU, Lei 13.639/2018 para o CFT); esta tabela é só o
-- vocabulário da app, para o usuário escolher em vez de digitar.
