CREATE INDEX IF NOT EXISTS ix_prf_conselho ON catalogo.profissoes (prf_conselho, prf_nome)
    WHERE prf_ativa;

-- ------------------------------------------------------------
-- catalogo.municipios — os 5.571 municípios do Brasil (IBGE)
-- ------------------------------------------------------------
-- Entrou porque "Local e Data" do ofício pedia município DIGITADO e UF escolhida à parte: duas
-- chances de errar, e nenhuma garantia de que o par batia. Com a tabela, o usuário escolhe o
-- município e a UF vem junto — o banco já sabe.
--
-- A PK é o CÓDIGO IBGE, não uma sequence: é a identidade oficial do município, estável, e é por
-- ela que qualquer integração futura (dados do IBGE, UF do SINAPI) vai juntar. Sequence aqui seria
-- inventar um segundo id sem função.
--
-- Fonte: servicodados.ibge.gov.br/api/v1/localidades/municipios, lida uma vez em 06/10/2026 e
-- congelada aqui. Município não se cria todo dia; quando criar, é uma linha.
CREATE TABLE IF NOT EXISTS catalogo.municipios (
    mun_id   INTEGER NOT NULL PRIMARY KEY,   -- código IBGE (7 dígitos)
    mun_nome TEXT    NOT NULL,
    mun_uf   CHAR(2) NOT NULL,

    CONSTRAINT uq_mun_nome_uf UNIQUE (mun_nome, mun_uf)
);

-- a listbox lê em ordem de UF e nome, que é como a pessoa procura
CREATE INDEX IF NOT EXISTS ix_mun_uf_nome ON catalogo.municipios (mun_uf, mun_nome);

