CREATE TABLE IF NOT EXISTS catalogo.doc_resp_tecnica (
    drt_codigo TEXT PRIMARY KEY,                  -- ART, RRT, TRT
    drt_nome   TEXT    NOT NULL,
);

INSERT INTO catalogo.doc_resp_tecnica (drt_codigo, drt_nome) VALUES
    ('ART', 'ANOTAÇÃO DE RESPONSABILIDADE TÉCNICA'),
    ('RRT', 'REGISTRO DE RESPONSABILIDADE TÉCNICA'),
    ('TRT', 'TERMO DE RESPONSABILIDADE TÉCNICA')
ON CONFLICT (drt_codigo) DO NOTHING;

-- ══════════════════════════════════════════════════════════════════════════════
-- RESPONSÁVEL TÉCNICO — cadastro do tenant (quem assina os documentos)
-- Mora em tenant_catalogo porque é cadastro reusado pelo tenant inteiro, como unidade e fonte:
-- cadastra uma vez, usa em todos os empreendimentos. NÃO guarda user_uuid — o Hub é dono dos
-- usuários e não expõe "listar usuários do tenant"; coluna apontando para o que não se consulta
-- é FK fantasma. Entra por ALTER no dia em que o Hub expuser.
-- ══════════════════════════════════════════════════════════════════════════════
-- ══════════════════════════════════════════════════════════════════════════════
-- CONTRATANTE — para quem o orçamento é feito
-- Mora em tenant_catalogo pelo mesmo motivo do RT: é cadastro reusado pelo tenant inteiro —
-- a mesma prefeitura contrata várias obras.
--
-- Vínculo 1:N (FK no empreendimento), NÃO N:N como o RT. A diferença é do domínio: assinam
-- vários, contrata UM. O header mostra uma linha "Contratante:" e o ofício abre com "À {nome}".
-- Se um dia aparecer consórcio, vira tabela de ligação — mas inventar a ligação agora criaria uma
-- lista que a tela não sabe mostrar.
-- ══════════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS tenant_catalogo.contratantes (
    ctr_id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ctr_tenant_uuid   UUID    NOT NULL,              -- RAIZ de isolamento. [VALIDAR] sem FK física.
    ctr_nome          TEXT    NOT NULL,              -- como vai no documento: "PREFEITURA MUNICIPAL DE…"
    ctr_documento     TEXT,                          -- CNPJ ou CPF, como escrito
    ctr_ativo         BOOLEAN NOT NULL DEFAULT TRUE,  -- soft-delete (doutrina do tenant_catalogo)
    ctr_criado_em     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ctr_atualizado_em TIMESTAMPTZ,
    ctr_criado_por    TEXT,
    ctr_atualizado_por TEXT,

    -- prefixo tctr_, e não tcc_: este último já é de tenant_catalogo.composicoes, e nome de
    -- índice é único por SCHEMA — colidiria na criação.
    CONSTRAINT ck_tctr_nome CHECK (btrim(ctr_nome) <> '')
);

CREATE INDEX IF NOT EXISTS ix_tctr_tenant ON tenant_catalogo.contratantes (ctr_tenant_uuid)
    WHERE ctr_ativo;

CREATE TABLE IF NOT EXISTS tenant_catalogo.responsaveis_tecnicos (
    rt_id                     INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rt_tenant_uuid            UUID    NOT NULL,          -- RAIZ de isolamento. [VALIDAR] sem FK física.
    rt_nome                   TEXT    NOT NULL,
    -- Profissão ESCOLHIDA, não digitada: padroniza o que sai no bloco de assinatura e amarra à
    -- competência do conselho. A listbox da tela filtra por rt_conselho.
    rt_profissao              TEXT NOT NULL REFERENCES catalogo.profissoes (prf_codigo),
    -- Documento profissional em TRÊS partes, não em texto solto: o bloco de assinatura concatena
    -- ("CREA-SP 506.404.144-5"), e manter separado é o que permite validar, filtrar e, um dia,
    -- conferir contra o conselho. `rt_conselho_uf` aceita UF ou 'BR' (registro nacional).
    rt_conselho               TEXT NOT NULL REFERENCES catalogo.conselhos_classe (ccl_codigo),
    rt_conselho_uf            CHAR(2) NOT NULL,          -- UF ou 'BR' (registro nacional)
    rt_documento              TEXT    NOT NULL,          -- só o número: "506.404.144-5"
    rt_ativo                  BOOLEAN NOT NULL DEFAULT TRUE,   -- soft-delete (doutrina do tenant_catalogo)
    rt_criado_em              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rt_atualizado_em          TIMESTAMPTZ,
    rt_criado_por             TEXT,
    rt_atualizado_por         TEXT,

    -- O formulário exige estes campos; o banco TAMBÉM, para o dia em que alguém mexer na tela e
    -- esquecer a validação. Documento assinado sem profissão ou sem registro não é documento.
    CONSTRAINT ck_tcrt_nome      CHECK (btrim(rt_nome) <> ''),
    CONSTRAINT ck_tcrt_documento CHECK (btrim(rt_documento) <> ''),
    CONSTRAINT ck_tcrt_uf        CHECK (rt_conselho_uf = 'BR' OR rt_conselho_uf ~ '^[A-Z]{2}$')
);

CREATE INDEX ix_tcrt_tenant ON tenant_catalogo.responsaveis_tecnicos (rt_tenant_uuid) WHERE rt_ativo;

-- ── Busca: coluna normalizada mantida por trigger (upper+unaccent do código+descrição) ──
-- Fuzzy = pg_trgm word_similarity sobre ins_busca/cmp_busca (índices GIN acima); exata = ILIKE unaccent.
-- Sem search_document/indexer (isso é do catálogo global, milhões de linhas). Extensões unaccent/pg_trgm
-- vivem no schema catalogo (uso qualificado). unaccent é STABLE → ok em trigger, não em coluna GENERATED.
CREATE OR REPLACE FUNCTION tenant_catalogo.set_busca() RETURNS trigger AS $$
BEGIN
    IF TG_TABLE_NAME = 'insumos' THEN
        NEW.ins_busca := upper(catalogo.unaccent(coalesce(NEW.ins_codigo, '') || ' ' || coalesce(NEW.ins_descricao, '')));
    ELSIF TG_TABLE_NAME = 'composicoes' THEN
        NEW.cmp_busca := upper(catalogo.unaccent(coalesce(NEW.cmp_codigo, '') || ' ' || coalesce(NEW.cmp_descricao, '')));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_tci_busca BEFORE INSERT OR UPDATE ON tenant_catalogo.insumos
    FOR EACH ROW EXECUTE FUNCTION tenant_catalogo.set_busca();
CREATE TRIGGER trg_tcc_busca BEFORE INSERT OR UPDATE ON tenant_catalogo.composicoes
    FOR EACH ROW EXECUTE FUNCTION tenant_catalogo.set_busca();


-- ============================================================
-- SCHEMA: ativo
-- ============================================================
CREATE SCHEMA IF NOT EXISTS ativo;

GRANT USAGE ON SCHEMA ativo TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA ativo
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "axys_tec";

ALTER DEFAULT PRIVILEGES IN SCHEMA ativo
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";


-- ============================================================
-- TABELA: ativo.empreendimentos          (contrato §8.1)
-- Agrupador PURO de ativos do tenant. Sem ficha, sem motor.
-- Relatório consolidado = WHERE emp_id = X.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.empreendimentos (
    emp_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    emp_tenant_uuid     UUID    NOT NULL,                  -- RAIZ de isolamento. [VALIDAR] sem FK física (hub é banco externo).
    emp_codigo_interno  TEXT,                              -- código próprio do tenant (nullable)
    emp_nome            TEXT    NOT NULL,
    emp_descricao       TEXT,
    -- Endereço (NULLABLE; cadastro via BuscaCEP/ViaCEP). O ativo herda este endereço,
    -- mas pode ter o seu próprio (ativo.ativos.atv_end_*).
    emp_end_cep         TEXT,                              -- só dígitos (8); preenche logradouro/bairro/município/UF via CEP
    emp_end_logradouro  TEXT,
    emp_end_numero      TEXT,
    emp_end_complemento TEXT,
    emp_end_bairro      TEXT,
    emp_end_municipio   TEXT,
    emp_end_uf          CHAR(2),                           -- UF DO ENDEREÇO (≠ UF de preço do ativo)
    -- CONTRATANTE do empreendimento (quem contrata). RESTRICT: quem já aparece em documento
    -- emitido não some do cadastro por um clique — a saída é o soft-delete.
    emp_ctr_id          INTEGER REFERENCES tenant_catalogo.contratantes (ctr_id)
                        ON UPDATE CASCADE ON DELETE RESTRICT,
    emp_is_public       BOOLEAN NOT NULL DEFAULT FALSE,    -- ABRANGÊNCIA: TRUE=PÚBLICA (modelo Axys visível a todos), FALSE=PRIVADA (do tenant)
    emp_arquivado       BOOLEAN NOT NULL DEFAULT FALSE,    -- arquivado (sai da listagem padrão; reaparece com "exibir arquivados")
    emp_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    emp_atualizado_em   TIMESTAMPTZ,
    emp_criado_por      TEXT,
    emp_atualizado_por  TEXT,

    CONSTRAINT ck_empreendimentos_nome_vazio
        CHECK (btrim(emp_nome) <> '')
);

CREATE INDEX ix_empreendimentos_tenant
    ON ativo.empreendimentos (emp_tenant_uuid);


-- ============================================================
-- TABELA: ativo.ativo_tipos               (lookup — TIPOLOGIA do ativo)
-- "Listbox de valores conhecidos", SEEDADO na criação do banco.
-- Vocabulário controlado da TIPOLOGIA (Residencial, Hospitalar…), referenciado
-- por ativo.ativos.atv_tipo_id. atp_codigo = slug estável; atp_nome = rótulo exibido.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_tipos (
    atp_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    atp_codigo          TEXT    NOT NULL,                  -- slug estável (RESIDENCIAL, HOSPITALAR_COMPLEXO…)
    atp_nome            TEXT    NOT NULL,                  -- rótulo exibido na listbox
    atp_ordem           INTEGER NOT NULL DEFAULT 0,        -- ordem de exibição
    atp_ativo           BOOLEAN NOT NULL DEFAULT TRUE,     -- disponível na listbox?

    CONSTRAINT uq_ativo_tipos_codigo UNIQUE (atp_codigo),
    CONSTRAINT ck_ativo_tipos_nome_vazio CHECK (btrim(atp_nome) <> '')
);

-- SEED dos tipos conhecidos (idempotente).
