    ('LAJES_CORPORATIVAS',      'Lajes Corporativas',      5),
    ('INSTITUCIONAL',           'Institucional',           6),
    ('SEGURANCA_PUBLICA',       'Segurança Pública',       7),
    ('HOSPITALAR_COMPLEXO',     'Hospitalar Complexo',     8),
    ('HOSPITALAR_AMBULATORIAL', 'Hospitalar Ambulatorial', 9),
    ('INDUSTRIAL',              'Industrial',             10),
    ('ESPORTIVO',               'Esportivo',              11),
    ('OUTRO',                   'Outro',                  12)
ON CONFLICT (atp_codigo) DO NOTHING;


-- ============================================================
-- TABELA: ativo.ativos                    (contrato §8.2)
-- O objeto técnico real (obra/projeto/edificação/contrato).
-- Núcleo ao qual TUDO se conecta. Pertence a 0..1 empreendimento.
--
-- atv_tenant_uuid: SEMPRE preenchido. A Axys tem tenant próprio (role interna) —
--   modelos do "catálogo de ativos" são ativos desse tenant, não linhas órfãs.
-- atv_is_catalog_source: marca um ativo como FONTE do catálogo de ativos (modelo/
--   template que alimenta o gerador por drivers). Default FALSE. Um ativo comum
--   do tenant nasce FALSE; a Axys (ou futuramente o próprio tenant) marca TRUE
--   para reusá-lo como modelo. Decisão "árvore única": modelo = ativo, sem schema
--   espelhado nem duplicação de tabela.
-- Documentação do ativo (repo-paradigma): NÃO fica em JSONB de cabeçalho (lição do
--   Catálogo: ins_external_path virou dívida → migrou p/ registro catalogo.documentos).
--   Fica em TABELA dedicada ativo.ativo_diversidades_catalog (registro real, sem NULLs).
--   Ver §DOCUMENTOS / DIVERSIDADES adiante.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativos (
    atv_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    atv_tenant_uuid     UUID    NOT NULL,                  -- RAIZ de isolamento (inclui o tenant interno da Axys). [VALIDAR] sem FK física.
    atv_emp_id          INTEGER NOT NULL,                  -- empreendimento OBRIGATÓRIO (todo ativo pertence a um; sem obra avulsa)
    atv_is_catalog_source BOOLEAN NOT NULL DEFAULT FALSE,  -- TRUE = modelo/fonte do catálogo de ativos (drivers)
    atv_codigo_interno  TEXT,
    atv_tipo_id         INTEGER,                           -- TIPOLOGIA (FK ativo.ativo_tipos; listbox de valores conhecidos)
    atv_nome            TEXT    NOT NULL,
    atv_status          TEXT    NOT NULL DEFAULT 'RASCUNHO',-- rascunho/ativo/arquivado…
    atv_uf              CHAR(2),                           -- UF default (sobreposta no contexto de preço)
    -- Endereço PRÓPRIO do ativo (NULLABLE). Vazio = herda do empreendimento (emp_end_*).
    atv_end_cep         TEXT,                              -- só dígitos (8); BuscaCEP/ViaCEP
    atv_end_logradouro  TEXT,
    atv_end_numero      TEXT,
    atv_end_complemento TEXT,
    atv_end_bairro      TEXT,
    atv_end_municipio   TEXT,
    atv_end_uf          CHAR(2),                           -- UF DO ENDEREÇO (≠ atv_uf de preço)
    atv_orc_seq         INTEGER NOT NULL DEFAULT 0,        -- high-water do id LOCAL dos itens de orçamento (ativo_itens.ati_num); +1 a cada item criado, NUNCA reusa → id estável por ativo, começa em 1
    -- MOTOR DE BUSCA da bancada e da consulta de composições. TRUE = padrão (relevância pura).
    -- FALSE = ranqueia pondo a FONTE FAVORITA (★) no topo, mantida a relevância entre os pares.
    --
    -- É coluna própria, e não um efeito colateral de ter favorita, porque são duas decisões: a
    -- favorita existe para CONVERTER (insumo/MDO), e quem converte nem sempre quer que a busca
    -- mude de ordem por causa disso. Juntar as duas tirava do usuário uma escolha.
    -- DEFAULT TRUE preserva o comportamento de hoje — quem não escolher nada não vê diferença.
    atv_busca_padrao    BOOLEAN NOT NULL DEFAULT TRUE,
    -- RESPONSÁVEL TÉCNICO: TRUE = usa a equipe do empreendimento (herança VIVA, muda lá e reflete
    -- aqui — é o que evita repetir a cada ativo). FALSE = usa a lista própria em ativo_responsaveis.
    -- A lista própria NÃO é apagada ao religar a herança: desligar de novo devolve a escolha.
    atv_rt_herda        BOOLEAN NOT NULL DEFAULT TRUE,
    -- O que esta OBRA leva no documento: {"sintetico": true, "analitico": false, "param:Área": true}.
    -- Mora aqui, e não num JSON do empreendimento, porque a chave da tela é `atv{id}.sintetico`: no
    -- empreendimento o id do ativo viraria chave de JSON — id de outra tabela sem FK, o que a regra
    -- do P4 proíbe. Na linha da obra o id some: ele É a linha. E apagar a obra leva a escolha dela
    -- junto, de graça. Guarda o ESTADO, não só o marcado: chave ausente = "nunca configurada", e o
    -- checkbox cai no default — o certo para o parâmetro que nasceu depois da última gravação.
    atv_secoes          JSONB   NOT NULL DEFAULT '{}'::jsonb,
    atv_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    atv_atualizado_em   TIMESTAMPTZ,
    atv_criado_por      TEXT,
    atv_atualizado_por  TEXT,

    CONSTRAINT fk_ativos_emp
        FOREIGN KEY (atv_emp_id)
        REFERENCES ativo.empreendimentos (emp_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,   -- emp obrigatório; não pode virar NULL

    CONSTRAINT fk_ativos_tipo
        FOREIGN KEY (atv_tipo_id)
        REFERENCES ativo.ativo_tipos (atp_id)
        ON UPDATE CASCADE ON DELETE SET NULL,

    CONSTRAINT ck_ativos_nome_vazio
        CHECK (btrim(atv_nome) <> ''),

    -- objeto, sempre: `[]` ou um número aqui viraria erro de leitura lá na frente, longe daqui
    CONSTRAINT ck_atv_secoes CHECK (jsonb_typeof(atv_secoes) = 'object'),

    -- Redundante por si (atv_id já é a PK), existe para ser ALVO de FK COMPOSTA: é ela que faz o
    -- banco recusar um vínculo de produto cujo tenant não seja o tenant do ativo. Ver
    -- `ativo.ativo_produto_status`.
    CONSTRAINT uq_ativos_id_tenant UNIQUE (atv_id, atv_tenant_uuid)
);

CREATE INDEX ix_ativos_tenant
    ON ativo.ativos (atv_tenant_uuid);
CREATE INDEX ix_ativos_emp
    ON ativo.ativos (atv_emp_id);
-- localizar rapidamente os modelos/fontes do catálogo de ativos
CREATE INDEX ix_ativos_catalog_source
    ON ativo.ativos (atv_is_catalog_source)
    WHERE atv_is_catalog_source;

-- ============================================================
-- SEED: MODELOS AXYS (catálogo de ativos p/ o Easy Price — gerador por drivers).
-- Cada modelo = 1 empreendimento PÚBLICO (emp_is_public=TRUE) com 1 ativo "Edificação"
-- marcado como fonte do catálogo (atv_is_catalog_source=TRUE). Consultados GLOBALMENTE
-- pela flag (não entram na lista /empreendimentos de um tenant, que filtra por tenant).
-- Tenant: tenant Axys ATUAL ('7847231a-…' — PROVISÓRIO, VAI MUDAR).
--   [VALIDAR] atualizar quando o tenant definitivo da Axys existir no Hub
--   (trocar o UUID abaixo + UPDATE nas linhas já seedadas).
-- Idempotente (DO block: só insere o que falta, por nome). Rodar de novo não duplica.
-- ============================================================
DO $$
DECLARE
    v_axys uuid := '7847231a-4ba3-5138-b2d6-6943beb8e3f9';
    v_emp  int;
    r      record;
BEGIN
    FOR r IN
        SELECT * FROM (VALUES
            ('Construção Residencial AXYS | padrão popular',                                 'RESIDENCIAL'),
            ('Construção Residencial AXYS | padrão médio',                                   'RESIDENCIAL'),
            ('Construção Residencial AXYS | padrão alto',                                    'RESIDENCIAL'),
            ('Construção Comercial AXYS | Galeria Comercial',                                'COMERCIAL'),
            ('Construção Comercial AXYS | Lajes Corporativas',                               'LAJES_CORPORATIVAS'),
            ('Construção Escolar AXYS | Pré-Escola',                                         'EDUCACIONAL'),
            ('Construção Escolar AXYS | Ensino Médio',                                       'EDUCACIONAL'),
            ('Construção Escolar AXYS | Ensino Superior',                                    'EDUCACIONAL'),
            ('Construção Escolar AXYS | Quadras Poliesportivas',                             'ESPORTIVO'),
            ('Construção Institucional AXYS | Ginásio Poliesportivo',                        'ESPORTIVO'),
            ('Construção Institucional AXYS | Auditório',                                    'INSTITUCIONAL'),
            ('Construção Institucional AXYS | Térrea',                                       'INSTITUCIONAL'),
            ('Construção Institucional AXYS | Múltiplos Pavimentos',                         'INSTITUCIONAL'),
            ('Construção Hospitalar AXYS | Atendimento Ambulatorial',                        'HOSPITALAR_AMBULATORIAL'),
            ('Construção Hospitalar AXYS | Atendimento Ambulatorial, Urgência e Emergência', 'HOSPITALAR_AMBULATORIAL'),
            ('Construção Hospitalar AXYS | Alta Complexidade',                               'HOSPITALAR_COMPLEXO'),
            ('Construção Fábrica AXYS | Galpão-Edificação',                                  'INDUSTRIAL')
        ) AS t(nome, tipo_cod)
    LOOP
        SELECT emp_id INTO v_emp FROM ativo.empreendimentos
            WHERE emp_tenant_uuid = v_axys AND emp_nome = r.nome;
        IF v_emp IS NULL THEN
            INSERT INTO ativo.empreendimentos (emp_tenant_uuid, emp_nome, emp_is_public, emp_criado_por)
                VALUES (v_axys, r.nome, TRUE, 'Axys — seed modelos')
                RETURNING emp_id INTO v_emp;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM ativo.ativos
                       WHERE atv_emp_id = v_emp AND atv_nome = 'Edificação') THEN
            INSERT INTO ativo.ativos (atv_tenant_uuid, atv_emp_id, atv_nome,
                                      atv_is_catalog_source, atv_tipo_id, atv_status, atv_criado_por)
                VALUES (v_axys, v_emp, 'Edificação', TRUE,
                        (SELECT atp_id FROM ativo.ativo_tipos WHERE atp_codigo = r.tipo_cod),
                        'RASCUNHO', 'Axys — seed modelos');
        END IF;
    END LOOP;
END $$;


-- ############################################################
-- §FICHA TÉCNICA — REVISÃO 2026-06-16b (correção de seed + opções de LISTA)
-- ############################################################
-- CORREÇÕES desta revisão:
--  (1) SEED alinhado às etapas renomeadas/reordenadas pelo usuário:
--      • incêndio: parâmetros agora apontam 'INST_INCENDIO' (era 'COMBATE_INCENDIO')
--      • climatização: parâmetros agora apontam 'INST_CLIMATIZACAO' (era 'VENT_CLIMATIZACAO')
--      • comentários de ordem de etapa atualizados ao novo fet_ordem
--      (antes, o JOIN por fet_codigo não casava → 10 parâmetros sumiam em silêncio)
--  (2) NOVO: ficha_tec_param_opcoes — opções controladas dos parâmetros LISTA
--      (TIPO_* deixa de ser texto livre). Valor do ativo passa a guardar a OPÇÃO
--      via FK COMPOSTA (garante no banco que a opção pertence ao parâmetro certo).
--
-- ⚠️ DESTRUTIVO — rodar SOMENTE em banco dev/descartável.
-- ############################################################


-- ============================================================
-- 1) DROP (ordem: filhas → mães; inclui a nova ficha_tec_param_opcoes)
-- ============================================================
DROP TABLE IF EXISTS ativo.ficha_tec_itens;
DROP TABLE IF EXISTS ativo.ficha_tec_param_servicos;
DROP TABLE IF EXISTS ativo.ativo_ficha_tec_atributos;   -- referencia opcoes (FK composta) + parametros
DROP TABLE IF EXISTS ativo.ficha_tec_param_opcoes;      -- referencia parametros
DROP TABLE IF EXISTS ativo.ficha_tec_parametros;
DROP TABLE IF EXISTS ativo.ficha_tec_etapas;
DROP TABLE IF EXISTS ativo.ficha_tec;


-- ============================================================
-- 2) ativo.ficha_tec  (a GERAÇÃO / versão do deck)
-- ============================================================
-- ══════════════════════════════════════════════════════════════════════════════
-- QUEM ASSINA — ligação N:N entre os RTs do tenant e empreendimento/ativo
-- Dois níveis porque um empreendimento pode ter um assinante ou uma equipe, e o ativo idem:
-- podem convergir ou divergir. O ativo decide pela flag ativos.atv_rt_herda.
-- `ordem` existe porque bloco de assinatura é sequência: sem ela o banco não promete ordem e o
-- documento sai diferente entre dois renders.
-- NÃO é obrigatório: sem RT, o documento sai sem bloco de assinatura.
-- ══════════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS ativo.empreendimento_responsaveis (
    empr_emp_id  INTEGER NOT NULL,
    empr_rt_id   INTEGER NOT NULL,
    empr_ordem   INTEGER NOT NULL DEFAULT 1,
    -- ART/RRT/TRT é por OBRA, não por pessoa: o mesmo RT tem um documento em cada uma.
    empr_tipo_doc TEXT REFERENCES catalogo.doc_resp_tecnica (drt_codigo),
    empr_num_doc  TEXT,

    PRIMARY KEY (empr_emp_id, empr_rt_id),
    CONSTRAINT fk_empr_emp FOREIGN KEY (empr_emp_id)
        REFERENCES ativo.empreendimentos (emp_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_empr_rt  FOREIGN KEY (empr_rt_id)
        REFERENCES tenant_catalogo.responsaveis_tecnicos (rt_id) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS ativo.ativo_responsaveis (
    atvr_atv_id  INTEGER NOT NULL,
    atvr_rt_id   INTEGER NOT NULL,
    atvr_ordem   INTEGER NOT NULL DEFAULT 1,
    -- ART/RRT/TRT é por OBRA, não por pessoa: o mesmo RT tem um documento em cada uma.
    atvr_tipo_doc TEXT REFERENCES catalogo.doc_resp_tecnica (drt_codigo),
    atvr_num_doc  TEXT,

    PRIMARY KEY (atvr_atv_id, atvr_rt_id),
    CONSTRAINT fk_atvr_atv FOREIGN KEY (atvr_atv_id)
        REFERENCES ativo.ativos (atv_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_atvr_rt  FOREIGN KEY (atvr_rt_id)
        REFERENCES tenant_catalogo.responsaveis_tecnicos (rt_id) ON UPDATE CASCADE ON DELETE RESTRICT
);

-- ── Ocupação de capacidade: um vínculo por (ativo, produto) ───────────────────────────────────
-- Proposta do time do Hub em 06/10 (`contracts/axys_easy_modelo_licenciamento.md` §10.1), revisada
-- aqui. O CONCEITO é forçado pelo comercial: capacidade não forma saldo comum entre produtos, logo
-- "Orça 5 e Docs 5" são dois tetos, e o MESMO ativo pode estar em andamento no Orça sem ocupar
-- nada no Docs. Isso não cabe numa coluna de status do ativo — daí a tabela.
--
-- O slot é SEMPRE do ativo: empreendimento é agrupador e nunca ocupa nada (decisão de 01/10).
-- Criar empreendimento, ou só o cadastro-base do ativo, não cria vínculo. O vínculo nasce na
-- primeira operação que põe o ativo em andamento DENTRO de um produto. Concluir, revisar, reabrir,
-- recalcular ou emitir documento não geram consumo novo enquanto o vínculo seguir EM_ANDAMENTO.
--
-- O Hub NUNCA escreve aqui e nunca escolhe qual ativo arquivar. Ele pergunta a ocupação pelo
-- endpoint interno e aplica o próprio teto.
--
-- O QUE MUDOU DA PROPOSTA, e por quê:
--   · nomes na convenção da casa (prefixo `atvp_`, português) — a tabela é nossa, o Hub só lê pelo
--     endpoint, então nome em inglês sem prefixo seria dívida de leitura sem ganho nenhum;
--   · `atvp_tenant_uuid` ganhou GUARDA: a proposta dizia "deve corresponder ao tenant do ativo", e
--     regra sem guarda é a lição do P4. Aqui é FK COMPOSTA — o banco recusa o par incoerente;
--   · o tenant repetido se paga no índice parcial abaixo: a contagem de ocupação roda dentro do
--     lock, no caminho crítico de criar/desarquivar, e assim não precisa juntar `ativos`;
--   · `atvp_ativado_em` é a PRIMEIRA ativação e nunca se reescreve; quem registra ida e volta é
--     `audit.logs`, que é onde transição de estado mora nesta casa.
CREATE TABLE IF NOT EXISTS ativo.ativo_produto_status (
    atvp_atv_id         INTEGER NOT NULL,
    atvp_tenant_uuid    UUID    NOT NULL,
    -- produto operacional onde o ativo está em trabalho
    atvp_produto        TEXT    NOT NULL,
    -- licença que SUPORTA o slot; igual ao produto, exceto no Easy One, que consolida em 'ONE'
    atvp_licenca        TEXT    NOT NULL,
    atvp_status         TEXT    NOT NULL DEFAULT 'EM_ANDAMENTO',
    atvp_ativado_em     TIMESTAMPTZ NOT NULL DEFAULT now(),   -- primeira ativação, nunca reescrita
    atvp_arquivado_em   TIMESTAMPTZ,
    atvp_atualizado_em  TIMESTAMPTZ,
    atvp_atualizado_por TEXT,

    -- a chave natural é (ativo, produto); id próprio sem função não entra
    PRIMARY KEY (atvp_atv_id, atvp_produto),
    CONSTRAINT fk_atvp_ativo FOREIGN KEY (atvp_atv_id, atvp_tenant_uuid)
        REFERENCES ativo.ativos (atv_id, atv_tenant_uuid) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_atvp_produto CHECK (atvp_produto IN ('ORC', 'DOC', 'PM', 'LIC', 'BDR', 'FIN')),
    CONSTRAINT ck_atvp_licenca CHECK (atvp_licenca IN ('ORC', 'DOC', 'PM', 'LIC', 'BDR', 'FIN', 'ONE')),
    CONSTRAINT ck_atvp_status  CHECK (atvp_status IN ('EM_ANDAMENTO', 'ARQUIVADO')),
    -- data de arquivamento e status não podem discordar
    CONSTRAINT ck_atvp_arquivado CHECK ((atvp_status = 'ARQUIVADO') = (atvp_arquivado_em IS NOT NULL))
);

-- A pergunta que o gate faz, e a única que precisa ser rápida: quantos slots desta licença estão
-- ocupados neste tenant. Índice PARCIAL porque arquivado não conta e não precisa ser indexado.
CREATE INDEX IF NOT EXISTS ix_atvp_ocupacao
    ON ativo.ativo_produto_status (atvp_tenant_uuid, atvp_licenca)
    WHERE atvp_status = 'EM_ANDAMENTO';

CREATE TABLE IF NOT EXISTS ativo.ficha_tec (
    ft_id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ft_codigo           TEXT    NOT NULL,                  -- slug da geração (FT_V00, FT_V01…)
    ft_nome             TEXT    NOT NULL,                  -- rótulo curto ("Motor Paramétrico Inicial")
    ft_descricao        TEXT,                              -- texto COMERCIAL longo (venda/posicionamento da geração)
    ft_versao           INTEGER NOT NULL DEFAULT 1,
    ft_status           TEXT    NOT NULL DEFAULT 'ATIVA',  -- ATIVA | RASCUNHO | DESCONTINUADA
    ft_ativo            BOOLEAN NOT NULL DEFAULT TRUE,
    ft_criado_em        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ft_atualizado_em    TIMESTAMPTZ,
    ft_criado_por       TEXT,
    ft_atualizado_por   TEXT,

    CONSTRAINT uq_ft_codigo UNIQUE (ft_codigo),
    CONSTRAINT ck_ft_codigo_vazio CHECK (btrim(ft_codigo) <> ''),
    CONSTRAINT ck_ft_status CHECK (ft_status IN ('ATIVA', 'RASCUNHO', 'DESCONTINUADA'))
);

CREATE INDEX ix_ft_ativo ON ativo.ficha_tec (ft_ativo, ft_versao);


-- ============================================================
-- 3) ativo.ficha_tec_etapas  (LOOKUP de fases construtivas)
-- fet_is_etapa_obra: FALSE = conceitual (PARÂMETROS GERAIS); TRUE = etapa de obra.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_etapas (
    fet_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fet_codigo          TEXT    NOT NULL,                  -- slug estável (INST_HIDRAULICAS…)
    fet_nome            TEXT    NOT NULL,                  -- rótulo exibido (CAIXA ALTA)
    fet_ordem           INTEGER NOT NULL,                  -- sequência construtiva (0,10,20…)
    fet_is_etapa_obra   BOOLEAN NOT NULL DEFAULT TRUE,     -- FALSE = conceitual (guarda-chuva)
    fet_parent_id       INTEGER,                           -- SUB-ETAPA: etapa-grupo pai (NULL = grupo de topo = Nível 1 do orçamento; filha = Nível 2)
    fet_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    fet_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fet_atualizado_em   TIMESTAMPTZ,
    fet_criado_por      TEXT,
    fet_atualizado_por  TEXT,

    CONSTRAINT uq_fet_codigo UNIQUE (fet_codigo),
    CONSTRAINT fk_fet_parent
        FOREIGN KEY (fet_parent_id) REFERENCES ativo.ficha_tec_etapas (fet_id)
        ON UPDATE CASCADE ON DELETE CASCADE,               -- sub-etapa some com o grupo
    CONSTRAINT ck_fet_codigo_vazio CHECK (btrim(fet_codigo) <> ''),
    CONSTRAINT ck_fet_nome_vazio CHECK (btrim(fet_nome) <> '')
);

CREATE INDEX ix_fet_ordem ON ativo.ficha_tec_etapas (fet_ordem);
CREATE INDEX ix_fet_parent ON ativo.ficha_tec_etapas (fet_parent_id);


-- ============================================================
-- 4) ativo.ficha_tec_parametros  (VOCABULÁRIO de parâmetros)
-- fparam_etapa_id = FK NOT NULL p/ etapa. fparam_tipo = tipo do VALOR.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_parametros (
    fparam_id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fparam_etapa_id     INTEGER NOT NULL,
    fparam_codigo       TEXT    NOT NULL,
    fparam_descricao    TEXT    NOT NULL,
    fparam_tipo         TEXT    NOT NULL,                  -- NUMERO | TEXTO | BOOL | DATA | LISTA
    fparam_unidade      TEXT,
    fparam_ordem        INTEGER NOT NULL DEFAULT 1000,
    fparam_is_descritivel BOOLEAN NOT NULL DEFAULT FALSE,
    fparam_parent_id    INTEGER,                             -- CASCATA: parâmetro PAI (NULL = topo). Quais opções do pai abrem este filho ficam em ficha_tec_param_gatilho; SEM gatilho = qualquer valor do pai abre.
    fparam_ativo        BOOLEAN NOT NULL DEFAULT TRUE,
    fparam_criado_em    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fparam_atualizado_em TIMESTAMPTZ,
    fparam_criado_por   TEXT,
    fparam_atualizado_por TEXT,

    CONSTRAINT fk_fparam_etapa
        FOREIGN KEY (fparam_etapa_id)
        REFERENCES ativo.ficha_tec_etapas (fet_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_fparam_codigo UNIQUE (fparam_codigo),
    CONSTRAINT fk_fparam_parent
        FOREIGN KEY (fparam_parent_id)
        REFERENCES ativo.ficha_tec_parametros (fparam_id)
        ON UPDATE CASCADE ON DELETE CASCADE,                 -- cascata auto-referente (filho some com o pai)
    CONSTRAINT ck_fparam_tipo
        CHECK (fparam_tipo IN ('NUMERO', 'TEXTO', 'BOOL', 'DATA', 'LISTA')),
    CONSTRAINT ck_fparam_codigo_vazio CHECK (btrim(fparam_codigo) <> '')
);

CREATE INDEX ix_fparam_etapa ON ativo.ficha_tec_parametros (fparam_etapa_id, fparam_ordem);


-- ============================================================
-- 5) ativo.ficha_tec_param_opcoes   ★ NOVO ★  (opções controladas de LISTA)
-- Para parâmetros fparam_tipo = 'LISTA' (TIPO_ESTRUTURA = madeira/metal/concreto…).
-- Tira o valor-livre: a opção vira registro. uq (fpo_id, fpo_fparam_id) habilita a
-- FK COMPOSTA dos atributos (garante que a opção escolhida pertence ao parâmetro).
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_param_opcoes (
    fpo_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fpo_fparam_id       INTEGER NOT NULL,                  -- de qual parâmetro LISTA
    fpo_codigo          TEXT    NOT NULL,                  -- slug estável (MADEIRA, METALICA…)
    fpo_rotulo          TEXT    NOT NULL,                  -- exibido (Madeira, Metálica…)
    fpo_ordem           INTEGER NOT NULL DEFAULT 1000,
    fpo_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    fpo_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fpo_atualizado_em   TIMESTAMPTZ,
    fpo_criado_por      TEXT,
    fpo_atualizado_por  TEXT,

    CONSTRAINT fk_fpo_fparam
        FOREIGN KEY (fpo_fparam_id)
        REFERENCES ativo.ficha_tec_parametros (fparam_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_fpo_param_codigo UNIQUE (fpo_fparam_id, fpo_codigo),
    -- alvo da FK composta dos atributos (a opção carrega o param a que pertence)
    CONSTRAINT uq_fpo_id_param UNIQUE (fpo_id, fpo_fparam_id),
    CONSTRAINT ck_fpo_codigo_vazio CHECK (btrim(fpo_codigo) <> '')
);

CREATE INDEX ix_fpo_fparam ON ativo.ficha_tec_param_opcoes (fpo_fparam_id, fpo_ordem);
CREATE INDEX ix_fparam_parent ON ativo.ficha_tec_parametros (fparam_parent_id);

-- ============================================================
-- 5-bis) ativo.ficha_tec_param_gatilho  — quais OPÇÕES do pai abrem um parâmetro-filho.
-- Filho aparece quando o valor escolhido no pai ∈ gatilhos. SEM gatilho = qualquer valor abre.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_param_gatilho (
    fpg_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fpg_fparam_id       INTEGER NOT NULL,                  -- o parâmetro FILHO (condicional)
    fpg_fpo_id          INTEGER NOT NULL,                  -- a opção do PAI que o dispara
    CONSTRAINT fk_fpg_filho  FOREIGN KEY (fpg_fparam_id) REFERENCES ativo.ficha_tec_parametros (fparam_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_fpg_opcao  FOREIGN KEY (fpg_fpo_id)    REFERENCES ativo.ficha_tec_param_opcoes (fpo_id) ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_fpg UNIQUE (fpg_fparam_id, fpg_fpo_id)
);
CREATE INDEX ix_fpg_filho ON ativo.ficha_tec_param_gatilho (fpg_fparam_id);


-- ============================================================
-- 6) ativo.ficha_tec_itens  (PONTE N:N versão × parâmetro)
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_itens (
    fti_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fti_ft_id           INTEGER NOT NULL,
    fti_fparam_id       INTEGER NOT NULL,
    fti_ordem           INTEGER NOT NULL DEFAULT 1000,
    fti_obrigatorio     BOOLEAN NOT NULL DEFAULT FALSE,
    fti_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fti_criado_por      TEXT,

    CONSTRAINT fk_fti_ft
        FOREIGN KEY (fti_ft_id) REFERENCES ativo.ficha_tec (ft_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_fti_fparam
        FOREIGN KEY (fti_fparam_id) REFERENCES ativo.ficha_tec_parametros (fparam_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_fti_ft_fparam UNIQUE (fti_ft_id, fti_fparam_id)
);

CREATE INDEX ix_fti_ft     ON ativo.ficha_tec_itens (fti_ft_id, fti_ordem);
CREATE INDEX ix_fti_fparam ON ativo.ficha_tec_itens (fti_fparam_id);


-- ============================================================
-- 7) ativo.ficha_tec_param_servicos  (auto-check de parâmetros)
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ficha_tec_param_servicos (
    fps_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fps_fparam_id       INTEGER NOT NULL,
    fps_ref_origem      TEXT    NOT NULL,                  -- 'CATALOGO' | 'TENANT'
    fps_ref_id          INTEGER NOT NULL,
    fps_ordem           INTEGER NOT NULL DEFAULT 1000,
    fps_default         BOOLEAN NOT NULL DEFAULT FALSE,
    fps_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    fps_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fps_atualizado_em   TIMESTAMPTZ,
    fps_criado_por      TEXT,
    fps_atualizado_por  TEXT,

    CONSTRAINT fk_fps_fparam
        FOREIGN KEY (fps_fparam_id) REFERENCES ativo.ficha_tec_parametros (fparam_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_fps_ref_origem CHECK (fps_ref_origem IN ('CATALOGO', 'TENANT')),
    CONSTRAINT uq_fps_param_ref UNIQUE (fps_fparam_id, fps_ref_origem, fps_ref_id)
);

CREATE INDEX ix_fps_fparam ON ativo.ficha_tec_param_servicos (fps_fparam_id, fps_ordem);
CREATE UNIQUE INDEX uq_fps_um_default
    ON ativo.ficha_tec_param_servicos (fps_fparam_id) WHERE fps_default;


-- ============================================================
-- 8) ativo.ativo_ficha_tec_atributos  (VALOR por ativo)
-- Valor em coluna tipada conforme fparam_tipo:
--   NUMERO→numero · TEXTO→texto · BOOL→bool · DATA→data · LISTA→opcao_id (FK).
-- fatr_valor_opcao_id: FK COMPOSTA (fparam_id, opcao_id) → garante que a opção
--   pertence ao parâmetro. NULL p/ tipos não-LISTA (FK composta MATCH SIMPLE
--   só valida quando ambas as colunas estão preenchidas).
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_ficha_tec_atributos (
    fatr_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fatr_atv_id         INTEGER NOT NULL,
    fatr_fparam_id      INTEGER NOT NULL,
    fatr_valor_numero   NUMERIC(18,6),
    fatr_valor_texto    TEXT,
    fatr_valor_bool     BOOLEAN,
    fatr_valor_data     DATE,
    fatr_valor_opcao_id INTEGER,                           -- LISTA: FK p/ ficha_tec_param_opcoes (composta)
    fatr_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fatr_atualizado_em  TIMESTAMPTZ,
    fatr_criado_por     TEXT,
    fatr_atualizado_por TEXT,

    CONSTRAINT fk_fatr_atv
        FOREIGN KEY (fatr_atv_id) REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_fatr_fparam
        FOREIGN KEY (fatr_fparam_id) REFERENCES ativo.ficha_tec_parametros (fparam_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    -- integridade real: a opção escolhida TEM de pertencer ao parâmetro do atributo
    CONSTRAINT fk_fatr_opcao
        FOREIGN KEY (fatr_fparam_id, fatr_valor_opcao_id)
        REFERENCES ativo.ficha_tec_param_opcoes (fpo_fparam_id, fpo_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_fatr_atv_fparam UNIQUE (fatr_atv_id, fatr_fparam_id)
);

CREATE INDEX ix_fatr_atv    ON ativo.ativo_ficha_tec_atributos (fatr_atv_id);
CREATE INDEX ix_fatr_fparam ON ativo.ativo_ficha_tec_atributos (fatr_fparam_id);
CREATE INDEX ix_fatr_opcao  ON ativo.ativo_ficha_tec_atributos (fatr_valor_opcao_id)
    WHERE fatr_valor_opcao_id IS NOT NULL;


-- ============================================================
-- 9) SEED — FICHA TÉCNICA (gerado do estado curado; idempotente via helpers pg_temp).
--    Etapa-árvore (fet_parent_id) → params (fparam_parent_id + gatilhos) → opções + DECK.
-- ============================================================
CREATE OR REPLACE FUNCTION pg_temp.grp(p_cod text,p_nome text,p_ord int,p_obra boolean) RETURNS void LANGUAGE sql AS $$
  INSERT INTO ativo.ficha_tec_etapas (fet_codigo,fet_nome,fet_ordem,fet_is_etapa_obra,fet_parent_id) VALUES (p_cod,p_nome,p_ord,p_obra,NULL)
  ON CONFLICT (fet_codigo) DO UPDATE SET fet_nome=EXCLUDED.fet_nome,fet_ordem=EXCLUDED.fet_ordem,fet_is_etapa_obra=EXCLUDED.fet_is_etapa_obra,fet_parent_id=NULL; $$;
CREATE OR REPLACE FUNCTION pg_temp.sub(p_parent text,p_cod text,p_nome text,p_ord int) RETURNS void LANGUAGE sql AS $$
  INSERT INTO ativo.ficha_tec_etapas (fet_codigo,fet_nome,fet_ordem,fet_is_etapa_obra,fet_parent_id)
  SELECT p_cod,p_nome,p_ord,TRUE,(SELECT fet_id FROM ativo.ficha_tec_etapas WHERE fet_codigo=p_parent)
  ON CONFLICT (fet_codigo) DO UPDATE SET fet_nome=EXCLUDED.fet_nome,fet_ordem=EXCLUDED.fet_ordem,fet_parent_id=EXCLUDED.fet_parent_id; $$;
CREATE OR REPLACE FUNCTION pg_temp.par(p_etapa text,p_cod text,p_descr text,p_tipo text,p_unid text,p_ord int,p_parent text) RETURNS void LANGUAGE sql AS $$
  INSERT INTO ativo.ficha_tec_parametros (fparam_etapa_id,fparam_codigo,fparam_descricao,fparam_tipo,fparam_unidade,fparam_ordem,fparam_is_descritivel,fparam_parent_id)
  SELECT e.fet_id,p_cod,p_descr,p_tipo,NULLIF(p_unid,''),p_ord,FALSE,(SELECT fparam_id FROM ativo.ficha_tec_parametros WHERE fparam_codigo=p_parent)
  FROM ativo.ficha_tec_etapas e WHERE e.fet_codigo=p_etapa
  ON CONFLICT (fparam_codigo) DO UPDATE SET fparam_etapa_id=EXCLUDED.fparam_etapa_id,fparam_descricao=EXCLUDED.fparam_descricao,fparam_tipo=EXCLUDED.fparam_tipo,fparam_unidade=EXCLUDED.fparam_unidade,fparam_ordem=EXCLUDED.fparam_ordem,fparam_parent_id=EXCLUDED.fparam_parent_id; $$;
CREATE OR REPLACE FUNCTION pg_temp.opt(p_param text,p_cod text,p_rot text,p_ord int) RETURNS void LANGUAGE sql AS $$
  INSERT INTO ativo.ficha_tec_param_opcoes (fpo_fparam_id,fpo_codigo,fpo_rotulo,fpo_ordem)
  SELECT fparam_id,p_cod,p_rot,p_ord FROM ativo.ficha_tec_parametros WHERE fparam_codigo=p_param
  ON CONFLICT (fpo_fparam_id,fpo_codigo) DO UPDATE SET fpo_rotulo=EXCLUDED.fpo_rotulo,fpo_ordem=EXCLUDED.fpo_ordem; $$;
CREATE OR REPLACE FUNCTION pg_temp.gat(p_child text,p_parent text,p_opt text) RETURNS void LANGUAGE sql AS $$
  INSERT INTO ativo.ficha_tec_param_gatilho (fpg_fparam_id,fpg_fpo_id)
  SELECT c.fparam_id,o.fpo_id FROM ativo.ficha_tec_parametros c JOIN ativo.ficha_tec_parametros pp ON pp.fparam_codigo=p_parent
  JOIN ativo.ficha_tec_param_opcoes o ON o.fpo_fparam_id=pp.fparam_id AND o.fpo_codigo=p_opt WHERE c.fparam_codigo=p_child ON CONFLICT DO NOTHING; $$;

