-- descritível (7 indicadores macro)
UPDATE ativo.ficha_tec_parametros SET fparam_is_descritivel =
  (fparam_codigo IN ('AREA_CONSTRUIDA_TOTAL','AREA_COBERTURA','AREA_FUNDACAO','NUM_PAVIMENTOS','AREA_TERRENO','AREA_EXTERNA_PAVIMENTADA','AREA_EXTERNA_NAO_PAVIMENTADA'));
-- DECK v0.0 (motor paramétrico inicial)
INSERT INTO ativo.ficha_tec (ft_codigo, ft_nome, ft_descricao, ft_versao, ft_status) VALUES
  ('FT_V00','Motor Paramétrico Inicial','O motor paramétrico inicial da Axys estima seus quantitativos a partir de apenas 9 parâmetros simples.',0,'ATIVA')
ON CONFLICT (ft_codigo) DO NOTHING;
INSERT INTO ativo.ficha_tec_itens (fti_ft_id, fti_fparam_id, fti_ordem, fti_obrigatorio)
SELECT ft.ft_id, p.fparam_id, x.ord, TRUE FROM ativo.ficha_tec ft
JOIN (VALUES ('AREA_CONSTRUIDA_TOTAL',10),('AREA_COBERTURA',20),('AREA_EXTERNA_PAVIMENTADA',30),('NUM_PAVIMENTOS',40),('TOTAL_AMBIENTES',50),('QTD_SANITARIOS',60),('QTD_BACIAS',70),('QTD_LAVATORIOS',80),('QTD_DMLS',90)) AS x(cod,ord) ON TRUE
JOIN ativo.ficha_tec_parametros p ON p.fparam_codigo = x.cod
WHERE ft.ft_codigo='FT_V00' ON CONFLICT (fti_ft_id, fti_fparam_id) DO NOTHING;



-- ============================================================
-- TABELA: ativo.ativo_itens               (contrato §8.6)  ★ CORAÇÃO ★
-- Árvore canônica: parent_id + ordem ESPARSA + path. Numeração 1.2.3 é
-- RENDER, não dado. NÃO carrega tenant_uuid (deriva via ati_atv_id).
--
-- PREÇO NÃO É COLUNA AQUI. O item guarda o VÍNCULO (origem + cmp_id + qtd)
-- e a camada de AJUSTE reversível (ati_ajuste_json). Custo resolve ao vivo
-- contra a edição do contexto (orcamento_parametros). Sem ati_custo_base.
--
-- ati_cmp_origem: discriminador da FK polimórfica da composição.
--   CATALOGO → catalogo.composicoes | TENANT → tenant_catalogo.composicoes.
--   FK resolvida pelo app, NÃO pelo banco (polimórfica). NULL = linha estrutural
--   sem composição. (LOCAL removido 2026-06-16: alteração de composição espelha
--   direto para tenant_catalogo, não há mais fork de escopo-único.)
--
-- Vínculo item↔driver: NÃO é coluna aqui (evita zilhão de NULLs). É a tabela-ponte
--   ativo.ativo_itens_drivers (N:N) — só existe linha quando o item TEM driver.
--   Ver §CATÁLOGO DE ATIVOS / DRIVERS adiante.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_itens (
    ati_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  -- PK GLOBAL (interna): FK, parent_id, joins, API. NÃO exibida.
    ati_atv_id          INTEGER NOT NULL,
    ati_num             INTEGER NOT NULL,                  -- id LOCAL do item NESTE ativo (1..N, estável; vem de ativos.atv_orc_seq). EXIBIDO na tela e chave do round-trip Excel (§2/inv.2).
    ati_parent_id       INTEGER,                           -- pai na árvore; NULL = raiz. PROFUNDIDADE vem daqui.
    ati_ordem           INTEGER NOT NULL,                  -- ordem ESPARSA entre irmãos (1000, 2000…)
    ati_path            TEXT    NOT NULL,                  -- "0001.0002.0001" — DERIVADO; p/ ORDER BY e descendência
    ati_tipo            TEXT    NOT NULL,                  -- GRUPO | SERVIÇO | SUBTOTAL | TEXTO | OBSERVAÇÃO…
    ati_descricao       TEXT,
    ati_cmp_origem      TEXT,                              -- 'CATALOGO' | 'TENANT' | NULL
    ati_cmp_id          INTEGER,                           -- id da composição NA origem (FK polimórfica via app)
    ati_custo_unit      NUMERIC(14,2),                     -- CUSTO UNITÁRIO BASE da fonte, GRAVADO na entrada (pega de lá, grava cá, rotacionado ou nao, a depender do que o user setou de LS).
                                                           --   A L.S. JÁ entra aqui na captura, conforme a flag "rotacionar LS" da fonte-base (rotacionada = LS da obra; senão = LS de referência da fonte).
                                                           --   Imune a edição/reimport da fonte; só muda por ROTAÇÃO (comando do user). BDI/ajuste = camadas ao vivo por cima.
                                                           --   drift = comparar este valor com o preço atual da fonte na edição do contexto.
    ati_quantidade      NUMERIC(14,2),                     -- orçamento: 2 casas (preço já é TRUNC 2; +casas não muda o total).
                                                           --   Derivada da memória de cálculo (round 2, SEM trunc) ou digitada.
    ati_unidade         TEXT,
    ati_bdi_id          INTEGER,                           -- BDI da linha (FK ativo_bdi; NULL em título/não-precificável). FK via ALTER (ver §BDI)
    ati_ajuste_json     JSONB,                             -- camada de ajuste REVERSÍVEL sobre o preço resolvido (§10)
    ati_have_memory_calc BOOLEAN NOT NULL DEFAULT FALSE,   -- qtd vem de memória (true) ou digitação (false)
    ati_preco_fixado     BOOLEAN NOT NULL DEFAULT FALSE,   -- preço FIXADO manualmente (override): _capturar_custo_unit e rotação PULAM esta linha; desafixar re-rastreia a fonte. Espelha desc_fixada, mas explícito (ati_custo_unit é sempre gravado).
    ati_is_alo           BOOLEAN NOT NULL DEFAULT FALSE,   -- marcador ALO (Administração Local da Obra): SÓ em nó de nível 1; a subárvore inteira segue o %ALO derivado no cronograma. Y = total desta subárvore. Marcador durável (não a descrição). 1 por orçamento (garantido no serviço; índice parcial opcional).
    ati_regras_json     JSONB,                             -- metadados por tipo de linha
    ati_meta_json       JSONB,
    ati_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    ati_atualizado_em   TIMESTAMPTZ,
    ati_criado_por      TEXT,
    ati_atualizado_por  TEXT,

    CONSTRAINT fk_ati_atv
        FOREIGN KEY (ati_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_ati_parent
        FOREIGN KEY (ati_parent_id)
        REFERENCES ativo.ativo_itens (ati_id)
        ON UPDATE CASCADE ON DELETE CASCADE,  -- deletar nó = deletar subárvore (primitiva "deletar")

    CONSTRAINT ck_ati_tipo
        CHECK (ati_tipo IN ('GRUPO', 'SERVIÇO', 'SUBTOTAL', 'TEXTO', 'OBSERVAÇÃO')),
    CONSTRAINT ck_ati_cmp_origem
        CHECK (ati_cmp_origem IS NULL OR ati_cmp_origem IN ('CATALOGO', 'TENANT')),
    -- coerência vínculo: origem e id andam juntos (ambos nulos ou ambos preenchidos)
    CONSTRAINT ck_ati_cmp_par
        CHECK ( (ati_cmp_origem IS NULL     AND ati_cmp_id IS NULL)
             OR (ati_cmp_origem IS NOT NULL AND ati_cmp_id IS NOT NULL) ),
    CONSTRAINT ck_ati_ajuste_obj
        CHECK (ati_ajuste_json IS NULL OR jsonb_typeof(ati_ajuste_json) = 'object'),
    -- não há dois irmãos com a mesma ordem sob o mesmo pai (no mesmo ativo)
    CONSTRAINT uq_ati_irmaos_ordem
        UNIQUE (ati_atv_id, ati_parent_id, ati_ordem),
    -- id LOCAL único dentro do ativo (estável; nunca reusa — high-water em ativos.atv_orc_seq)
    CONSTRAINT uq_ati_num
        UNIQUE (ati_atv_id, ati_num)
);

-- leitura ordenada da árvore inteira de um ativo (ORDER BY ati_path)
CREATE INDEX ix_ati_atv_path
    ON ativo.ativo_itens (ati_atv_id, ati_path);
-- filhos diretos
CREATE INDEX ix_ati_parent
    ON ativo.ativo_itens (ati_parent_id);
-- descendência por prefixo de path (LIKE 'x.%')
CREATE INDEX ix_ati_atv_path_text
    ON ativo.ativo_itens (ati_atv_id, ati_path text_pattern_ops);


-- ============================================================
-- TABELA: ativo.orcamento_parametros      (contrato §8.7)
-- CONTEXTO de preço por fonte. ROTACIONÁVEL: trocar opa_edicao_id re-resolve
-- todo o orçamento sem tocar item algum.
-- LS saiu daqui → ativo.ativo_ls (ÚNICA por obra). BDI saiu daqui → ativo.ativo_bdi
--   (1+ por obra) + ati_bdi_id por linha. Decisão Renan 2026-06-14.
-- [VALIDAR] opa_modalidade (SD/CD) pode ser redundante com ativo_ls.als_tipo
--   (ONERADA/DESONERADA = obra-level); manter por ora, reavaliar na implementação.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.orcamento_parametros (
    opa_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    opa_atv_id          INTEGER NOT NULL,
    opa_fonte           TEXT    NOT NULL,                  -- SINAPI | CDHU | TENANT…
    opa_edicao_id       INTEGER,                           -- edição-base (catalogo.edicoes). NULL p/ fonte TENANT.
    opa_tenant_edicao_id INTEGER,                          -- edição-base da fonte TENANT (tenant_catalogo.edicoes; SEM FK física, padrão tenant). NULL p/ fonte de catálogo.
    opa_uf              CHAR(2) NOT NULL DEFAULT 'SP',
    opa_modalidade      TEXT    NOT NULL DEFAULT 'SD',      -- "LS da edição" da fonte: SD=sem desoneração (ONERADO) | CD=com desoneração (DESONERADO) | SE=sem encargos
    opa_converter_ls   BOOLEAN NOT NULL DEFAULT FALSE,     -- LS: aplica a LS DA OBRA (ativo_ls) sobre os insumos da fonte (preço pode diferir da fonte/edição)
    opa_converter_mdo  BOOLEAN NOT NULL DEFAULT FALSE,     -- MDO: substitui a mão-de-obra pelos equivalentes da fonte FAVORITA (inter-fonte, pivô SINAPI via equivalencias_mo)
    opa_converter_ins  BOOLEAN NOT NULL DEFAULT FALSE,     -- INS: substitui os insumos (material) pelos equivalentes da fonte FAVORITA (equivalencias_ins)
    opa_converter_reg  BOOLEAN NOT NULL DEFAULT FALSE,     -- REG: regime MENSALISTA (SINAPI-exclusivo: FONTE_H→SINAPI_H→SINAPI_MÊS); auto pelo ativo_ls, força SINAPI favorito
    opa_default         BOOLEAN NOT NULL DEFAULT FALSE,    -- FONTE FAVORITA: origem das substituições MDO/INS (contexto inicial herdado na criação)
    opa_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    opa_atualizado_em   TIMESTAMPTZ,
    opa_criado_por      TEXT,
    opa_atualizado_por  TEXT,

    CONSTRAINT fk_opa_atv
        FOREIGN KEY (opa_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_opa_edicao
        FOREIGN KEY (opa_edicao_id)
        REFERENCES catalogo.edicoes (edi_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT ck_opa_modalidade
        CHECK (opa_modalidade IN ('SD', 'CD', 'SE')),
    -- um contexto por (ativo, fonte)
    CONSTRAINT uq_opa_atv_fonte
        UNIQUE (opa_atv_id, opa_fonte)
);

-- no máximo UM contexto default por ativo
CREATE UNIQUE INDEX uq_opa_um_default
    ON ativo.orcamento_parametros (opa_atv_id)
    WHERE opa_default;

CREATE INDEX ix_opa_atv
    ON ativo.orcamento_parametros (opa_atv_id);


-- ══════════════════════════════════════════════════════════════════════════════
-- PARÂMETROS DO EMPREENDIMENTO — configuração do DOCUMENTO (1 linha por empreendimento)
--
-- Esta tabela já existiu com outro propósito: fonte-base herdada por todos os ativos (decisão de
-- 22/06/2026). Foi REFEITA em 05/10/2026, e o motivo é de modelo, não de conveniência —
-- empreendimento multi-ativo tem ativos de épocas e tabelas-base diferentes, então fonte no nível
-- do empreendimento está errada por natureza. O degrau existia, nunca foi usado (zero linhas em
-- dev E em prod, contra 28/31 em orcamento_parametros) e saiu junto com o código que o lia.
--
-- Agora guarda o que É do empreendimento: como os documentos dele se apresentam. 1×1, porque é um
-- conjunto de escolhas, não uma lista.
-- ══════════════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS ativo.empreendimento_parametros (
    epa_emp_id          INTEGER PRIMARY KEY
                        REFERENCES ativo.empreendimentos (emp_id)
                        ON UPDATE CASCADE ON DELETE CASCADE,

    -- ESTILO do papel timbrado. 1 = comercial compacto (o de sempre), 2 = comercial detalhado
    -- (contratante/objeto/endereço na faixa), 3 = institucional/público (+ encargos/BDI e fontes).
    epa_estilo          SMALLINT NOT NULL DEFAULT 1,

    -- B2B/B2C costuma ter preço próprio, diferente da fonte-base: esconder a procedência é
    -- legítimo ali, e o espaço liberado vai para a descrição.
    epa_ocultar_fonte   BOOLEAN NOT NULL DEFAULT FALSE,
    epa_ocultar_codigo  BOOLEAN NOT NULL DEFAULT FALSE,

    -- Direcionamento (A/C na apresentação)
    epa_direcionar      BOOLEAN NOT NULL DEFAULT FALSE,
    epa_prefixo         TEXT,                               -- Sr. | Sra. | Dr. | Dra. | Ilmo. | Exmo.
    epa_destinatario    TEXT,

    -- Local e data do fecho da apresentação. A data fica FIXA depois de preenchida — documento
    -- reemitido não pode mudar de data sozinho.
    epa_local_data      BOOLEAN NOT NULL DEFAULT FALSE,
    epa_municipio       TEXT,
    epa_uf              CHAR(2),
    epa_data            DATE,

    -- Orientação por documento. Guardada por documento porque a escolha é por documento: curva de
    -- insumos pode caber em pé e a de serviços não.
    -- curvas nascem VERTICAIS porque é assim que a app sempre as imprimiu; cronograma e
    -- histograma, horizontais. O default do parâmetro tem de reproduzir o que já saía.
    epa_orient_curva_serv  TEXT NOT NULL DEFAULT 'V',
    epa_orient_curva_ins   TEXT NOT NULL DEFAULT 'V',
    epa_orient_cronograma  TEXT NOT NULL DEFAULT 'H',
    epa_orient_histo_sint  TEXT NOT NULL DEFAULT 'H',
    epa_orient_histo_anal  TEXT NOT NULL DEFAULT 'H',
    epa_orient_proprias    TEXT NOT NULL DEFAULT 'H',
    -- A Curva S e as barras do histograma são ILUSTRAÇÃO, não a peça: quem analisa um orçamento
    -- lê a tabela. Entram só quando pedidas, e por isso nascem FALSE.
    epa_grafico_crono      BOOLEAN NOT NULL DEFAULT FALSE,
    epa_grafico_histo      BOOLEAN NOT NULL DEFAULT FALSE,
    epa_grafico_curva      BOOLEAN NOT NULL DEFAULT FALSE,

    epa_entrega         TEXT NOT NULL DEFAULT 'UNICO',      -- UNICO | ISOLADO (zip numerado)
    -- AGRUPAMENTO decide a FORMA do documento consolidado:
    --   ISOLADO  = cada ativo com seu sumário e seus documentos, em sequência. SEM repath — os
    --              itens mantêm a numeração que têm hoje dentro do ativo.
    --   AGRUPADO = capa única, sumário único, tudo misturado, COM repath: o ativo desce um nível
    --              e passa a ser 1., 2.… e os itens dele descem junto.
    epa_agrupamento     TEXT NOT NULL DEFAULT 'ISOLADO',

    -- EXECUÇÃO decide como os cronogramas de vários ativos se somam:
    --   CONCOMITANTE = obras ao mesmo tempo; mês 1 soma com mês 1 de cada ativo.
    --   ISOLADA      = obras em sequência; dois ativos de 10 meses viram 20 meses, em ordem.
    epa_execucao        TEXT NOT NULL DEFAULT 'CONCOMITANTE',
    -- como os ativos se juntam no agrupado: um depois do outro, ou casando as etapas
    epa_tipo_agrup      TEXT NOT NULL DEFAULT 'SEQUENCIAL',

    -- O que é do DOCUMENTO no que o usuário marcou na tab Finalização:
    -- {"doc.capa": true, "doc.apresentacao": false, "emp.campo:Nome do empreendimento": true}.
    -- O que é da OBRA mora em `ativo.ativos.atv_secoes` — ver a nota lá, que explica por que as
    -- duas metades não cabem num JSON só.
    epa_secoes          JSONB NOT NULL DEFAULT '{}'::jsonb,


    epa_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    epa_atualizado_em   TIMESTAMPTZ,
    epa_criado_por      TEXT,
    epa_atualizado_por  TEXT,

    CONSTRAINT ck_epa_estilo   CHECK (epa_estilo IN (1, 2, 3)),
    CONSTRAINT ck_epa_agrup    CHECK (epa_agrupamento IN ('AGRUPADO', 'ISOLADO')),
    CONSTRAINT ck_epa_exec     CHECK (epa_execucao IN ('CONCOMITANTE', 'ISOLADA')),
    CONSTRAINT ck_epa_tipoagr  CHECK (epa_tipo_agrup IN ('SEQUENCIAL', 'POR_ETAPAS')),
    CONSTRAINT ck_epa_entrega  CHECK (epa_entrega IN ('UNICO', 'ISOLADO')),
    CONSTRAINT ck_epa_orient   CHECK (epa_orient_curva_serv IN ('H','V') AND epa_orient_curva_ins IN ('H','V')
                                  AND epa_orient_cronograma IN ('H','V') AND epa_orient_histo_sint IN ('H','V')
                                  AND epa_orient_histo_anal IN ('H','V')
                                  AND epa_orient_proprias IN ('H','V')),
    -- marcou direcionar, tem de ter a quem; marcou local e data, tem de ter município
    CONSTRAINT ck_epa_direcionar CHECK (NOT epa_direcionar OR btrim(COALESCE(epa_destinatario,'')) <> ''),
    CONSTRAINT ck_epa_local      CHECK (NOT epa_local_data OR btrim(COALESCE(epa_municipio,'')) <> ''),
    -- objeto, sempre: `[]` ou um número aqui viraria erro de leitura lá na frente, longe daqui
    CONSTRAINT ck_epa_secoes     CHECK (jsonb_typeof(epa_secoes) = 'object')
);


-- ============================================================
-- (REMOVIDO 2026-06-16) ativo.orcamento_composicoes / _itens
-- Fim do LOCAL: composição alterada num orçamento agora ESPELHA direto para
-- tenant_catalogo (o user monta biblioteca própria sem perceber). Não há mais
-- fork de escopo-único. ati_cmp_origem passou a ser CATALOGO | TENANT (sem LOCAL).
-- ============================================================


-- ============================================================
-- TABELA: ativo.orcamento_insumos / _preco       (contrato §8.9)
-- Fork LOCAL de insumo. Situação CHECK-text coerente com a doutrina do Catálogo
-- (null = sem preço). Referenciado por origem='LOCAL'.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.orcamento_insumos (
    oin_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    oin_atv_id          INTEGER NOT NULL,
    oin_origem_ref      TEXT,                              -- origem+código original (rastreio)
    oin_descricao       TEXT,
    oin_unidade         TEXT,
    oin_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    oin_atualizado_em   TIMESTAMPTZ,
    oin_criado_por      TEXT,
    oin_atualizado_por  TEXT,

    CONSTRAINT fk_oin_atv
        FOREIGN KEY (oin_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX ix_oin_atv
    ON ativo.orcamento_insumos (oin_atv_id);

CREATE TABLE IF NOT EXISTS ativo.orcamento_insumos_preco (
    oip_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    oip_oin_id          INTEGER NOT NULL,
    oip_uf              CHAR(2) NOT NULL DEFAULT 'SP',
    oip_preco           NUMERIC(14,2),                     -- null = sem preço (2 casas TRUNC — padrão obra)
    oip_situacao        TEXT,                              -- 'COM PREÇO' | 'SEM PREÇO' (null = sem preço)
    oip_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    oip_atualizado_em   TIMESTAMPTZ,
    oip_criado_por      TEXT,
    oip_atualizado_por  TEXT,

    CONSTRAINT fk_oip_oin
        FOREIGN KEY (oip_oin_id)
        REFERENCES ativo.orcamento_insumos (oin_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_oip_situacao
        CHECK (oip_situacao IS NULL OR oip_situacao IN ('COM PREÇO', 'SEM PREÇO')),
    CONSTRAINT uq_oip_oin_uf
        UNIQUE (oip_oin_id, oip_uf)
);

CREATE INDEX ix_oip_oin
    ON ativo.orcamento_insumos_preco (oip_oin_id);


-- ============================================================
-- TABELA: ativo.memo_calc / memo_calc_item       (contrato §8.10)
-- Memória de cálculo. DUAS origens, MESMO schema (consistência — decisão Renan 2026-06-14):
--   • PLUGIN/API (CAD/RVT/IFC): VERDADE = mc_json_cru (payload bruto); itens parseados.
--   • MANUAL (usuário digita): mc_json_cru NULL; VERDADE = o grid (mc_corpo) + os memo_calc_item.
-- Um registro por import/lançamento; um filho por bloco/coletor/linha. SEM tabela de
-- entidades nem overlays relacionais (overlay é DERIVADO no viewer).
--
-- GRID MANUAL — mc_corpo (decisão Renan 2026-06-26: EXPANSIBILIDADE via ID ESTÁVEL):
--   { "prox_id": <int monotônico, NUNCA reusa>,
--     "celulas": { "<cell_id>": { "l":linha, "c":coluna, "raw":"…", "b":?,"i":?,"u":? } } }
--   A IDENTIDADE da célula é o cell_id (imutável); a posição A–K×linha é DISPLAY (renumera
--   estilo Excel ao inserir/mover/excluir linha). Fórmulas e o vínculo ao item (mci_cell_id)
--   apontam pro cell_id → inserir/mover linha NUNCA quebra associação nem fórmula.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.memo_calc (
    mc_id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mc_atv_id           INTEGER NOT NULL,
    mc_origem           TEXT    NOT NULL,                  -- VIA PLUGIN/API: 'CAD'|'BIM'|'RVT'|'IFC' | DIGITADA: 'MANUAL'. platform/detalhe fica no payload no R2 (axysCAD §1.2)
    -- MANUAL (grid mini-excel) — título + corpo (células por id estável) + dimensões.
    mc_titulo           TEXT    NOT NULL DEFAULT 'Memória de cálculo',
    mc_corpo            JSONB   NOT NULL DEFAULT '{"celulas":{},"prox_id":1}'::jsonb,
    mc_qtd_colunas      SMALLINT DEFAULT 11,               -- A–K (sem coluna-margem)
    mc_qtd_linhas       SMALLINT DEFAULT 10,               -- começa em 10; UI estende ("+ linha" / inserir acima-abaixo)
    -- MANIFESTO DE LEVANTAMENTOS (plugin CAD/BIM): N imports por memória, cada um com PROVENIÊNCIA +
    -- PATH do payload axys-cad-v1 CRU no R2 (o blob pesado NÃO fica no banco — só o resumo/qtd fica,
    -- nos memo_calc_item). Array de {key, titulo, origem, arquivo, path, hash, por, em}. [] no MANUAL puro.
    -- Ex.: piso em 3 levantadas = 3 entradas (auditoria: "levantado por Fulano em dd/mm — arquivo X").
    mc_levantamentos    JSONB   NOT NULL DEFAULT '[]'::jsonb,
    mc_versao           INTEGER NOT NULL DEFAULT 1,        -- etag (concorrência otimista)
    mc_importado_em     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mc_importado_por    TEXT,
    mc_atualizado_em    TIMESTAMPTZ,
    mc_atualizado_por   TEXT,

    CONSTRAINT fk_mc_atv
        FOREIGN KEY (mc_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_mc_origem
        CHECK (mc_origem IN ('CAD', 'BIM', 'RVT', 'IFC', 'MANUAL')),
    CONSTRAINT ck_mc_corpo_obj
        CHECK (jsonb_typeof(mc_corpo) = 'object'),
    CONSTRAINT ck_mc_levantamentos_arr
        CHECK (jsonb_typeof(mc_levantamentos) = 'array')
    -- Sem UNIQUE por arquivo: idempotência de re-import é por `key`/`hash` DENTRO de mc_levantamentos
    -- (app resolve). Vários memos manuais por ativo = naturalmente livres (1 ativo → N memórias).
);

CREATE INDEX ix_mc_atv
    ON ativo.memo_calc (mc_atv_id);

-- Colunas alinhadas ao mapeamento axysCAD §8 (1 captura → 1 memo_calc_item) quando
-- via plugin; no MANUAL o usuário digita codigo/nome/unidade/qtd e as colunas de
-- plugin (capture_id, collector, quantity_type, coeficiente, entidades) ficam NULL.
-- mci_codigo ← friendly_name (slug/agrupador); mci_nome_amigavel ← name (rótulo livre).
CREATE TABLE IF NOT EXISTS ativo.memo_calc_item (
    mci_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mci_mc_id           INTEGER NOT NULL,
    mci_capture_id      TEXT,                              -- capture_id do JSON (identidade p/ sync granular / SUPERSEDED). NULL no MANUAL.
    mci_levantamento_key TEXT,                             -- (CAD/BIM) key do levantamento em memo_calc.mc_levantamentos que originou este bloco. NULL no MANUAL. Fecha a auditoria bloco→arquivo→quem/quando.
    mci_cell_id         TEXT,                              -- MANUAL: id ESTÁVEL da célula do grid (mc_corpo) que origina o bloco; NULL no CAD. Sobrevive a inserir/mover/excluir linha (posição A–K é só display).
    mci_codigo          TEXT    NOT NULL,                  -- friendly_name — slug/agrupador (junção semântica c/ o item)
    mci_nome_amigavel   TEXT,                              -- name — rótulo livre do orçamentista
    mci_local           TEXT,                              -- location_or_floor — âncora de localização (axysCAD: obrigatório)
    mci_collector       TEXT,                              -- AXUNIT | AXCOMP | AXAREA | AXVOL | AXTEXT
    mci_quantity_type   TEXT,                              -- UNIT | LENGTH | AREA | VOLUME | TEXT_VALUE (1:1 c/ collector)
    mci_metodo          TEXT,                              -- method do coletor (selection_count, entity_area_sum…)
    mci_unidade         TEXT,
    mci_qtd_calculada   NUMERIC(14,2) NOT NULL,            -- AUTORIDADE sobre o número (quantidade → 2 casas TRUNC, casa com ati_quantidade)
    mci_coeficiente_json JSONB,                            -- coefficient {type,value,unit} (só AXVOL hoje; forma evolui sem ALTER)
    -- (entidades[] NÃO ficam no banco: a evidência vive no payload axys-cad-v1 CRU no R2, por levantamento — drill-down lê de lá por capture_id)
    mci_status          TEXT    NOT NULL DEFAULT 'SYNCED', -- SYNCED | SUPERSEDED (re-levantamento preserva histórico — axysCAD §9)
    mci_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mci_atualizado_em   TIMESTAMPTZ,
    mci_criado_por      TEXT,
    mci_atualizado_por  TEXT,

    CONSTRAINT fk_mci_mc
        FOREIGN KEY (mci_mc_id)
        REFERENCES ativo.memo_calc (mc_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_mci_collector
        CHECK (mci_collector IS NULL OR mci_collector IN ('AXUNIT','AXCOMP','AXAREA','AXVOL','AXTEXT')),
    CONSTRAINT ck_mci_qtype
        CHECK (mci_quantity_type IS NULL OR mci_quantity_type IN ('UNIT','LENGTH','AREA','VOLUME','TEXT_VALUE')),
    CONSTRAINT ck_mci_status
        CHECK (mci_status IN ('SYNCED', 'SUPERSEDED')),
    CONSTRAINT ck_mci_coef_obj
        CHECK (mci_coeficiente_json IS NULL OR jsonb_typeof(mci_coeficiente_json) = 'object')
);

CREATE INDEX ix_mci_mc
    ON ativo.memo_calc_item (mci_mc_id);
CREATE INDEX ix_mci_codigo
    ON ativo.memo_calc_item (mci_codigo);
CREATE INDEX ix_mci_capture
    ON ativo.memo_calc_item (mci_capture_id);


-- ============================================================
-- TABELA: ativo.memo_calc_item_link            (contrato §8.11)
-- Ponte N:N bloco↔item do orçamento (faz ABERTO e FECHADO caberem no mesmo schema):
--   • 1 bloco → N itens   (o MESMO bloco/célula alimenta vários itens — ex.: concreto +
--     lançamento + adensamento; ou um bloco GLOBAL atende vários itens);
--   • 1 item  → N blocos  (item soma blocos de locais/origens diferentes).
-- Quantidade do item = Σ mci_qtd_calculada dos blocos linkados (quando have_memory_calc).
-- MÃO DUPLA (ON DELETE CASCADE dos dois lados): apaga item → link some (memória "perde a quem
-- referenciou"); apaga bloco → link some (item destravado volta a ser digitação manual).
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.memo_calc_item_link (
    mcil_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mcil_mci_id          INTEGER NOT NULL,
    mcil_ati_id          INTEGER NOT NULL,
    mcil_tipo            TEXT    NOT NULL,                  -- 'DIRECIONADO' | 'GLOBAL'
    mcil_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mcil_criado_por      TEXT,

    CONSTRAINT fk_mcil_mci
        FOREIGN KEY (mcil_mci_id)
        REFERENCES ativo.memo_calc_item (mci_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_mcil_ati
        FOREIGN KEY (mcil_ati_id)
        REFERENCES ativo.ativo_itens (ati_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_mcil_tipo
        CHECK (mcil_tipo IN ('DIRECIONADO', 'GLOBAL')),
    CONSTRAINT uq_mcil_mci_ati
        UNIQUE (mcil_mci_id, mcil_ati_id)
);

CREATE INDEX ix_mcil_ati
    ON ativo.memo_calc_item_link (mcil_ati_id);
CREATE INDEX ix_mcil_mci
    ON ativo.memo_calc_item_link (mcil_mci_id);


-- ============================================================
-- TABELA: ativo.memo_calc_arquivo            (contrato §8.10)
-- Anexos no R2 da memória: mídias (fotos, exibidas e empilhadas no PDF) e docs
-- (pdf/dwg, ver/download). Substitui ativo.memoria_arquivo (mar_) da Fase 1-lite.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.memo_calc_arquivo (
    mca_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mca_mc_id       INTEGER NOT NULL,
    mca_papel       TEXT    NOT NULL DEFAULT 'midia',        -- midia (foto) | doc (pdf/dwg/etc)
    mca_tipo        TEXT,                                    -- imagem | pdf | dwg | ...
    mca_r2_key      TEXT    NOT NULL,                        -- caminho no bucket público
    mca_url         TEXT,                                    -- url pública resolvida
    mca_nome        TEXT    NOT NULL,                        -- nome original
    mca_assunto     TEXT,                                    -- p/ a relação de docs (nome | assunto | ver/download)
    mca_mime        TEXT,
    mca_tamanho_bytes BIGINT,
    mca_largura     INTEGER,
    mca_altura      INTEGER,
    mca_ordenacao   TEXT,                                    -- sort key (sobe na lista = empilha no PDF)
    mca_enviado_em  TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mca_criado_por  TEXT,

    CONSTRAINT fk_mca_mc
        FOREIGN KEY (mca_mc_id) REFERENCES ativo.memo_calc (mc_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_mca_papel
        CHECK (mca_papel IN ('midia', 'doc')),
    CONSTRAINT uq_mca_key
        UNIQUE (mca_r2_key)
);
CREATE INDEX ix_mca_mc ON ativo.memo_calc_arquivo (mca_mc_id);


-- ============================================================
-- TABELA: ativo.ativo_revisoes            (contrato §8.12)
-- Estado vivo + revisões CONGELADAS. NÃO espelha 7 tabelas-gêmeas:
-- a foto fiel vive em rev_snapshot_json; o que se consulta vive em rev_resumo_json.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_revisoes (
    rev_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rev_atv_id          INTEGER NOT NULL,
    rev_codigo          TEXT    NOT NULL,                  -- R01, R02…
    rev_status          TEXT    NOT NULL DEFAULT 'EMITIDA', -- emitida/arquivada…
    rev_data            TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rev_autor           TEXT,
    rev_snapshot_json   JSONB   NOT NULL,                  -- FOTO write-once (orçamento+composições+preços+memória+params)
    rev_resumo_json     JSONB,                             -- resumo denormalizado (totais, ABC) — consulta/diff barato

    CONSTRAINT fk_rev_atv
        FOREIGN KEY (rev_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_rev_atv_codigo
        UNIQUE (rev_atv_id, rev_codigo),
    CONSTRAINT ck_rev_snapshot_obj
        CHECK (jsonb_typeof(rev_snapshot_json) = 'object'),
    CONSTRAINT ck_rev_resumo_obj
        CHECK (rev_resumo_json IS NULL OR jsonb_typeof(rev_resumo_json) = 'object')
);

CREATE INDEX ix_rev_atv
    ON ativo.ativo_revisoes (rev_atv_id);


-- ============================================================
-- TABELA: ativo.ativo_eventos             (contrato §8.13)
-- Trilha de eventos estruturais/negócio (criar, mover, indentar, emitir
-- revisão, rotacionar edição…). Auditoria FORMAL continua no schema audit —
-- isto é trilha de domínio.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_eventos (
    evt_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    evt_atv_id          INTEGER NOT NULL,
    evt_tipo            TEXT    NOT NULL,
    evt_payload_json    JSONB,
    evt_em              TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    evt_por             TEXT,

    CONSTRAINT fk_evt_atv
        FOREIGN KEY (evt_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_evt_payload_obj
        CHECK (evt_payload_json IS NULL OR jsonb_typeof(evt_payload_json) = 'object')
);

CREATE INDEX ix_evt_atv
    ON ativo.ativo_eventos (evt_atv_id, evt_em);


-- ============================================================
-- §BDI E LEIS SOCIAIS  (decisão Renan 2026-06-14; modelo Acórdão 2622/2013-TCU 2026-06-23)
-- BDI: COMPOSTO (header + parcelas) e MÚLTIPLO por obra (1+). Modelo do Acórdão 2622/2013-TCU:
--   classe NORMAL (obra, faixa por tipo) | REDUZIDO (Fornecimento de Materiais/Equipamentos);
--   regime ONERADO | DESONERADO (governa CPRB e a LS recomendada — SEM amarração rígida).
--   abd_tipo_obra referencia catalogo.bdi_tcu_param (faixa q1/médio/q3; default = médio).
--   Parcelas variáveis (AC/SG/R/DF/L) saem do TCU; CP (3,65% fixo), ISS (base×alíquota) e CPRB
--   (0% onerado / transição Lei 14.973/2024: 2026≈2,7% desonerado) são do ativo.
--   Fórmula: BDI = [(1+AC+SG+R)·(1+DF)·(1+L) / (1−(CP+ISS+CPRB))] − 1.
--   CADA linha do orçamento recebe um BDI (ati_bdi_id). Default por obra (abd_default).
-- LS: COMPOSTA (header + parcelas) e ÚNICA por obra (1). tipo ONERADA/DESONERADA.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_bdi (
    abd_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    abd_atv_id          INTEGER NOT NULL,
    abd_classe          TEXT    NOT NULL DEFAULT 'NORMAL',  -- NORMAL (obra) | REDUZIDO (equipamentos/materiais)
    abd_regime          TEXT    NOT NULL DEFAULT 'ONERADO', -- ONERADO | DESONERADO (governa CPRB + LS recomendada)
    abd_tipo_obra       TEXT,                               -- chave em catalogo.bdi_tcu_param (EDIFICIOS…; REDUZIDO ⇒ FORNECIMENTO_EQUIP)
    abd_nome            TEXT,
    abd_iss_base        NUMERIC(14,2) NOT NULL DEFAULT 100, -- % da base de cálculo do ISS sujeita à alíquota
    abd_iss_aliquota    NUMERIC(14,2),                      -- alíquota municipal do ISS (%)
    abd_percent         NUMERIC(14,2),                     -- BDI resultante (%), TRUNC(2) — nunca ROUND (contrato §6)
    abd_default         BOOLEAN NOT NULL DEFAULT FALSE,    -- BDI padrão da obra (aplicado por default às linhas)
    abd_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    abd_atualizado_em   TIMESTAMPTZ,
    abd_criado_por      TEXT,
    abd_atualizado_por  TEXT,

    CONSTRAINT fk_abd_atv
        FOREIGN KEY (abd_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_abd_classe
        CHECK (abd_classe IN ('NORMAL', 'REDUZIDO')),
    CONSTRAINT ck_abd_regime
        CHECK (abd_regime IN ('ONERADO', 'DESONERADO'))
);

CREATE INDEX ix_abd_atv
    ON ativo.ativo_bdi (abd_atv_id);
-- no máximo UM BDI default por obra
CREATE UNIQUE INDEX uq_abd_um_default
    ON ativo.ativo_bdi (abd_atv_id)
    WHERE abd_default;

CREATE TABLE IF NOT EXISTS ativo.ativo_bdi_composicao (
    abdc_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    abdc_abd_id         INTEGER NOT NULL,
    abdc_parcela        TEXT    NOT NULL,                  -- siglas Acórdão 2622/2013: AC | SG | R | DF | L | CP | ISS | CPRB
    abdc_descricao      TEXT,
    abdc_percent        NUMERIC(14,2) NOT NULL,
    abdc_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    abdc_atualizado_em  TIMESTAMPTZ,
    abdc_criado_por     TEXT,
    abdc_atualizado_por TEXT,

    CONSTRAINT fk_abdc_abd
        FOREIGN KEY (abdc_abd_id)
        REFERENCES ativo.ativo_bdi (abd_id)
        ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX ix_abdc_abd
    ON ativo.ativo_bdi_composicao (abdc_abd_id);

-- FK ati_bdi_id → ativo_bdi (via ALTER por causa da ordem de criação).
-- ON DELETE SET NULL: apagar um BDI não apaga linhas; elas ficam sem BDI até reatribuir.
ALTER TABLE ativo.ativo_itens
    ADD CONSTRAINT fk_ati_bdi
    FOREIGN KEY (ati_bdi_id)
    REFERENCES ativo.ativo_bdi (abd_id)
    ON UPDATE CASCADE ON DELETE SET NULL;

CREATE INDEX ix_ati_bdi
    ON ativo.ativo_itens (ati_bdi_id)
    WHERE ati_bdi_id IS NOT NULL;

-- ------------------------------------------------------------
-- Leis Sociais — ÚNICA por obra (header + parcelas)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ativo.ativo_ls (
    als_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    als_atv_id          INTEGER NOT NULL,
    als_tipo            TEXT    NOT NULL,                  -- ONERADA | DESONERADA (desoneração da folha)
    als_mdo             TEXT    NOT NULL DEFAULT 'HORISTA', -- regime de contratação da MDO: HORISTA | MENSALISTA (qual coluna de LS é aplicada ao preço)
    als_percent_horista     NUMERIC(14,2),                 -- LS resultante (%) p/ horista (2 casas TRUNC)
    als_percent_mensalista  NUMERIC(14,2),                 -- LS resultante (%) p/ mensalista (2 casas TRUNC)
    als_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    als_atualizado_em   TIMESTAMPTZ,
    als_criado_por      TEXT,
    als_atualizado_por  TEXT,

    CONSTRAINT fk_als_atv
        FOREIGN KEY (als_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT ck_als_tipo
        CHECK (als_tipo IN ('ONERADA', 'DESONERADA')),
    CONSTRAINT ck_als_mdo
        CHECK (als_mdo IN ('HORISTA', 'MENSALISTA')),
    CONSTRAINT uq_als_atv
        UNIQUE (als_atv_id)                                -- ÚNICA por obra
);

-- itens (parcelas A/B/C/D) da LS DA OBRA — espelha catalogo.edicoes_leis_sociais_itens.
-- Nasce semeada do catálogo (edição×UF×modalidade da fonte-base) e é editável POR ATIVO: cada obra
-- pode ter a sua (o orçamentista manda; o emp/fonte-base só semeia o padrão).
CREATE TABLE IF NOT EXISTS ativo.ativo_ls_item (
    alsi_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alsi_als_id         INTEGER NOT NULL,
    alsi_grupo          CHAR(1),                           -- A | B | C | D (grupos da planilha de LS)
    alsi_codigo         TEXT,                              -- A1, A2, B1… (INSS, SESI…)
    alsi_descricao      TEXT,
    alsi_percent_horista     NUMERIC(14,2),
    alsi_percent_mensalista  NUMERIC(14,2),
    alsi_ordem          INTEGER NOT NULL DEFAULT 0,
    alsi_criado_em      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    alsi_atualizado_em  TIMESTAMPTZ,
    alsi_criado_por     TEXT,
    alsi_atualizado_por TEXT,

    CONSTRAINT fk_alsi_als
        FOREIGN KEY (alsi_als_id)
        REFERENCES ativo.ativo_ls (als_id)
        ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX ix_alsi_als
    ON ativo.ativo_ls_item (alsi_als_id);


-- ============================================================
-- §CRONOGRAMA físico-financeiro  (decisão Renan 2026-06-14, ponto #5.c)
-- Fasiamento do valor por PERÍODO. Feito por NÍVEL, até o limite n-1 do orçamento
-- (parou no nível 5 → cronograma vai até nível 4; normalmente nível 3): tudo abaixo
-- do "guarda-chuva" (o item do nível de corte) segue o padrão dele.
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.cronograma (
    cro_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cro_atv_id          INTEGER NOT NULL,
    cro_nome            TEXT,
    cro_prazo_dias      INTEGER,                           -- prazo total (ex.: 360)
    cro_periodo_dias    INTEGER NOT NULL DEFAULT 30,       -- tamanho do período (ex.: 30)
    cro_num_periodos    INTEGER,                           -- nº de períodos (ex.: 12)
    cro_nivel_corte     INTEGER,                           -- nível do "guarda-chuva" (≤ n-1)
    cro_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cro_atualizado_em   TIMESTAMPTZ,
    cro_criado_por      TEXT,
    cro_atualizado_por  TEXT,

    CONSTRAINT fk_cro_atv
        FOREIGN KEY (cro_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE
);

CREATE INDEX ix_cro_atv
    ON ativo.cronograma (cro_atv_id);

CREATE TABLE IF NOT EXISTS ativo.cronograma_itens (
    cri_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cri_cro_id          INTEGER NOT NULL,
    cri_ati_id          INTEGER NOT NULL,                  -- item no nível de corte
    cri_periodo         INTEGER NOT NULL,                  -- 1..cro_num_periodos
    cri_percent         NUMERIC(9,6) NOT NULL,             -- fração do valor do item neste período
    cri_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    cri_atualizado_em   TIMESTAMPTZ,
    cri_criado_por      TEXT,
    cri_atualizado_por  TEXT,

    CONSTRAINT fk_cri_cro
        FOREIGN KEY (cri_cro_id)
        REFERENCES ativo.cronograma (cro_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_cri_ati
        FOREIGN KEY (cri_ati_id)
        REFERENCES ativo.ativo_itens (ati_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT uq_cri_cro_ati_periodo
        UNIQUE (cri_cro_id, cri_ati_id, cri_periodo)
);

CREATE INDEX ix_cri_cro
    ON ativo.cronograma_itens (cri_cro_id);
CREATE INDEX ix_cri_ati
    ON ativo.cronograma_itens (cri_ati_id);


-- ============================================================
-- §DOCUMENTOS / DIVERSIDADES DO ATIVO  (decisão Renan 2026-06-14)
-- Registro REAL (não JSONB de cabeçalho) dos documentos/peças que descrevem o ativo
-- — em especial o "repo-paradigma" dos modelos (is_catalog_source): arquivos que
-- mostram o que está orçado. Tabela enxuta, sem NULLs, refator barato. Mesma doutrina
-- do catalogo.documentos (que substituiu o ins_external_path JSONB).
-- [VALIDAR] sufixo "_catalog" (EN) vs "_catalogo" (PT, padrão do resto do banco).
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.ativo_diversidades_tipo_catalog (
    adt_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    adt_codigo          TEXT    NOT NULL,                  -- código estável (ARQ, EST, ELE…)
    adt_descricao       TEXT    NOT NULL,                  -- rótulo (CAIXA ALTA — identidade)
    adt_ordem           INTEGER NOT NULL DEFAULT 1000,
    adt_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    adt_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    adt_atualizado_em   TIMESTAMPTZ,
    adt_criado_por      TEXT,
    adt_atualizado_por  TEXT,

    CONSTRAINT uq_adt_codigo
        UNIQUE (adt_codigo),
    CONSTRAINT ck_adt_codigo_vazio
        CHECK (btrim(adt_codigo) <> ''),
    CONSTRAINT ck_adt_descricao_vazia
        CHECK (btrim(adt_descricao) <> '')
);

-- seed inicial (disciplinas de projeto) — CAIXA ALTA na identidade (feedback_caixa_alta_catalogo)
INSERT INTO ativo.ativo_diversidades_tipo_catalog (adt_codigo, adt_descricao, adt_ordem) VALUES
    ('ARQ', 'PROJETO ARQUITETÔNICO', 1000),
    ('EST', 'PROJETO ESTRUTURAL',    2000),
    ('ELE', 'PROJETO ELÉTRICO',      3000),
    ('HID', 'PROJETO HIDRÁULICO',    4000),
    ('MEC', 'PROJETO MECÂNICO',      5000),
    ('GAS', 'PROJETO GASES',         6000)
ON CONFLICT (adt_codigo) DO NOTHING;

-- ------------------------------------------------------------
-- TABELA: ativo.ativo_diversidades_catalog  (entradas por ativo)
-- Um documento/peça do ativo, tipado pela disciplina. Path no R2.
-- prefixo adc_ = Ativo Diversidade Catalog.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ativo.ativo_diversidades_catalog (
    adc_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    adc_atv_id          INTEGER NOT NULL,                  -- ativo dono
    adc_adt_id          INTEGER NOT NULL,                  -- tipo/disciplina
    adc_descricao       TEXT,                              -- descrição da peça
    adc_path            TEXT,                              -- caminho no R2 (ou link)
    adc_ordem           INTEGER NOT NULL DEFAULT 1000,
    adc_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    adc_atualizado_em   TIMESTAMPTZ,
    adc_criado_por      TEXT,
    adc_atualizado_por  TEXT,

    CONSTRAINT fk_adc_atv
        FOREIGN KEY (adc_atv_id)
        REFERENCES ativo.ativos (atv_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_adc_adt
        FOREIGN KEY (adc_adt_id)
        REFERENCES ativo.ativo_diversidades_tipo_catalog (adt_id)
        ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE INDEX ix_adc_atv
    ON ativo.ativo_diversidades_catalog (adc_atv_id, adc_ordem);
CREATE INDEX ix_adc_adt
    ON ativo.ativo_diversidades_catalog (adc_adt_id);


-- ============================================================
-- §CATÁLOGO DE ATIVOS / DRIVERS  (decisão 2026-06-14 — fora do contrato v0.2)
-- O gerador automatizado de orçamento é o produto vendável da Axys: a partir dos
-- PARÂMETROS da ficha (ficha_parametros/atributos) e de um MODELO (ativo com
-- atv_is_catalog_source=TRUE), DRIVERS calculam quantidades dos itens.
-- "Árvore única": o modelo é um ativo comum; gerar = copiar a subárvore do modelo
-- para o ativo do tenant + rodar os drivers contra a ficha dele.
--
-- drv_regra_json: [VALIDAR] formato da regra/fórmula (referencia par_codigo de
--   entrada → quantidade). Mantido JSONB p/ evoluir SEM ALTER (refator quase proibido).
-- drv_tenant_uuid NULL = driver GLOBAL (Axys, visível a todos); preenchido = driver
--   privado do tenant. (Driver É customizável por tenant — ao contrário de
--   ficha_parametros, que é vocabulário só-global.) [VALIDAR se tenant cria driver]
-- ============================================================
CREATE TABLE IF NOT EXISTS ativo.drivers (
    drv_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    drv_tenant_uuid     UUID,                              -- NULL = global (Axys). [VALIDAR] sem FK física.
    drv_codigo          TEXT    NOT NULL,                  -- código estável do driver
    drv_nome            TEXT    NOT NULL,
    drv_descricao       TEXT,
    drv_tipo            TEXT,                              -- natureza da regra (FORMULA, LOOKUP…) — [VALIDAR]
    drv_unidade         TEXT,                              -- unidade da quantidade gerada
    drv_regra_json      JSONB,                             -- a regra/fórmula (entradas = par_codigo). [VALIDAR]
    drv_ativo           BOOLEAN NOT NULL DEFAULT TRUE,
    drv_meta_json       JSONB,
    drv_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    drv_atualizado_em   TIMESTAMPTZ,
    drv_criado_por      TEXT,
    drv_atualizado_por  TEXT,

    CONSTRAINT uq_drivers_codigo_tenant
        UNIQUE (drv_tenant_uuid, drv_codigo),
    CONSTRAINT ck_drivers_regra_obj
        CHECK (drv_regra_json IS NULL OR jsonb_typeof(drv_regra_json) = 'object'),
    CONSTRAINT ck_drivers_meta_obj
        CHECK (drv_meta_json IS NULL OR jsonb_typeof(drv_meta_json) = 'object')
);

-- ------------------------------------------------------------
-- TABELA-PONTE: ativo.ativo_itens_drivers  (N:N item ↔ driver)
-- Só existe linha quando o item de modelo USA driver (sem NULLs em massa).
-- Um item pode somar vários drivers (alvenaria = área parede + área platibanda);
-- um driver pode servir a vários itens.
-- prefixo aid_ = Ativo Item Driver.
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS ativo.ativo_itens_drivers (
    aid_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    aid_ati_id          INTEGER NOT NULL,
    aid_drv_id          INTEGER NOT NULL,
    aid_fator           NUMERIC(18,6),                     -- multiplicador opcional do driver neste item
    aid_meta_json       JSONB,                             -- parâmetros do vínculo (mapeamento de entradas etc.)
    aid_criado_em       TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    aid_atualizado_em   TIMESTAMPTZ,
    aid_criado_por      TEXT,
    aid_atualizado_por  TEXT,

    CONSTRAINT fk_aid_ati
        FOREIGN KEY (aid_ati_id)
        REFERENCES ativo.ativo_itens (ati_id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    CONSTRAINT fk_aid_drv
        FOREIGN KEY (aid_drv_id)
        REFERENCES ativo.drivers (drv_id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT uq_aid_ati_drv
        UNIQUE (aid_ati_id, aid_drv_id),
    CONSTRAINT ck_aid_meta_obj
        CHECK (aid_meta_json IS NULL OR jsonb_typeof(aid_meta_json) = 'object')
);

CREATE INDEX ix_aid_ati
    ON ativo.ativo_itens_drivers (aid_ati_id);
CREATE INDEX ix_aid_drv
    ON ativo.ativo_itens_drivers (aid_drv_id);


-- ============================================================
-- NAMESPACE RESERVADO (contrato §6 / §12) — NÃO CRIAR AGORA.
-- Cada microapp traz o próprio DDL no seu slot quando nascer:
--   ativo.ativo_docs    (Easy Docs)
--   ativo.ativo_pm      (Easy ProjectManager)
--   ativo.ativo_diario  (Easy BuildDiary)
--   ativo.ativo_fin     (Easy FinControl)
--   ativo.ativo_licit   (Easy LicitPlan)
--   ativo.ativo_repo    (Repositório de arquivos)
-- Namespace reservado ≠ tabela criada.
-- ============================================================



-- ============================================================
-- §ARQUIVAMENTO — desconstrução / reconstrução por tenant  [VALIDAR / pode virar contrato]
-- Problema: dados de orçamento de tenant SEM licença ativa há muito tempo não
-- podem ficar no banco quente (barato p/ 1, inviável p/ 10M). Evolui o backup R2 já
-- aprovado (memória project_audit_r2_backup) p/ ciclo por-tenant dirigido pelo Hub.
--
-- FRONTEIRA (X.2, decisão Renan): a REGRA/CONTEXTO/limites são do HUB. O Easy NÃO
-- conhece a regra — apenas EXECUTA quando chamado: (a) desconstruir(tenant) e
-- (b) reconstruir(tenant). O Hub documenta o ciclo do lado dele.
--
-- CICLO (serviço + Celery, não SQL puro):
--   1. DESCONSTRUÇÃO: Hub detecta tenant sem licença há > N dias (N em tabela do HUB)
--      → chama Easy → Celery async: SELECT de TODAS as tabelas do tenant (alcançáveis
--      via tenant_uuid nas raízes + FK) → BACKFILL JSON estruturado (mesmos nomes/roles
--      do banco) → grava no destino (R2 catalogado, ou schema frio) → DELETE do quente.
--   2. RECONSTRUÇÃO: Hub cobra e chama → Easy recarrega o backfill no quente.
--      PKs GENERATED BY DEFAULT permitem reinsert com id original (FKs preservadas).
--   3. RETENÇÃO: payloads guardados ~5 anos; não voltou, purga até de lá (gatilho do Hub).
--
-- POR QUE O SCHEMA JÁ SUPORTA: tenant_uuid só nas raízes + folhas por FK ⇒ recorte
-- por tenant é determinístico (sem rastrear tenant em toda folha). catalogo.* é GLOBAL
-- (nunca entra no backfill do tenant). Só falta o REGISTRO abaixo (o "catálogo no SQL").
--
-- arquivo.arquivamentos: registro de cada arquivamento (onde está, status, validade).
-- O payload em si vai p/ R2 (ou schema frio); aqui fica só o índice consultável.
-- ============================================================
CREATE SCHEMA IF NOT EXISTS arquivo;

GRANT USAGE ON SCHEMA arquivo TO "axys_tec";
ALTER DEFAULT PRIVILEGES IN SCHEMA arquivo
    GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO "axys_tec";
ALTER DEFAULT PRIVILEGES IN SCHEMA arquivo
    GRANT USAGE, SELECT ON SEQUENCES TO "axys_tec";

CREATE TABLE IF NOT EXISTS arquivo.arquivamentos (
    arq_id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    arq_tenant_uuid     UUID    NOT NULL,                  -- tenant arquivado
    arq_status          TEXT    NOT NULL DEFAULT 'ARQUIVADO', -- ARQUIVADO | RESTAURADO | PURGADO
    arq_destino         TEXT    NOT NULL DEFAULT 'R2',      -- 'R2' | 'SCHEMA_FRIO'
    arq_localizacao     TEXT,                              -- path no R2 (ou nome do schema frio)
    arq_payload_hash    TEXT,                              -- checksum do backfill p/ integridade
    arq_tabelas_json    JSONB,                             -- { "ativo.ativos": 12, "ativo.ativo_itens": 3480, … } banco vs qtd
    arq_arquivado_em    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    arq_arquivado_por   TEXT,                              -- ator (serviço/hub)
    arq_restaurado_em   TIMESTAMPTZ,
    arq_expira_em       TIMESTAMPTZ,                       -- arquivado_em + 5 anos (purga)
    arq_meta_json       JSONB,

    CONSTRAINT ck_arq_status
        CHECK (arq_status IN ('ARQUIVADO', 'RESTAURADO', 'PURGADO')),
    CONSTRAINT ck_arq_destino
        CHECK (arq_destino IN ('R2', 'SCHEMA_FRIO')),
    CONSTRAINT ck_arq_tabelas_obj
        CHECK (arq_tabelas_json IS NULL OR jsonb_typeof(arq_tabelas_json) = 'object'),
    CONSTRAINT ck_arq_meta_obj
        CHECK (arq_meta_json IS NULL OR jsonb_typeof(arq_meta_json) = 'object')
);

CREATE INDEX ix_arq_tenant
    ON arquivo.arquivamentos (arq_tenant_uuid, arq_status);
CREATE INDEX ix_arq_expira
    ON arquivo.arquivamentos (arq_expira_em)
    WHERE arq_status = 'ARQUIVADO';

-- ============================================================
-- Memória de Cálculo — Fase 1-lite REMOVIDA no cutover (2026-06-26).
-- As tabelas mec_/mes_/mar_ deram lugar à família memo_calc / memo_calc_item /
-- memo_calc_item_link / memo_calc_arquivo (Modelo B, §8.10/§8.11). DROP explícito
-- p/ limpar bancos de DEV que já as tinham (em fresh é no-op).
-- Spec: backend/frontend/templates/ativos/bancada_orca_memo-calc.md
-- ============================================================
DROP TABLE IF EXISTS ativo.memoria_saida   CASCADE;
DROP TABLE IF EXISTS ativo.memoria_arquivo CASCADE;
DROP TABLE IF EXISTS ativo.memoria_calculo CASCADE;
